from tallybook.errors import TallybookError, ValidationError, is_int
from tallybook.money import Money, parse_amount
from tallybook.model import Posting, Transaction

__all__ = ["transactions_to_csv", "transactions_to_json", "transactions_from_json", "render_table", "to_csv",
           "to_json", "money_to_dict", "transaction_to_dict", "ExportError"]


class ExportError(ValidationError):
    """A table or JSON document that cannot be handled."""


# ------------------------------------------------------------------- CSV
def _csv_field(value):
    text = "" if value is None else str(value)
    if any(c in text for c in ',"\r\n'):
        return '"' + text.replace('"', '""') + '"'
    return text


def to_csv(headers, rows):
    lines = [",".join(_csv_field(h) for h in headers)]
    for row in rows:
        lines.append(",".join(_csv_field(c) for c in row))
    return "\n".join(lines) + "\n"


def _date_text(d):
    return "%04d-%02d-%02d" % (d.year, d.month, d.day)


def _tags(tx):
    return sorted(set(tx.tags or ()))


CSV_HEADERS = ["id", "date", "flag", "payee", "narration", "tags", "account", "amount", "currency", "note"]


def transactions_to_csv(txs):
    rows = []
    for tx in txs:
        head = [tx.id, _date_text(tx.date), tx.flag, tx.payee, tx.narration, ";".join(_tags(tx))]
        if not tx.postings:
            rows.append(head + ["", "", "", ""])
        for p in tx.postings:
            if p.amount is None:
                rows.append(head + [p.account, "", "", p.note])
            else:
                rows.append(head + [p.account, p.amount.amount_str(), p.amount.currency, p.note])
    return to_csv(CSV_HEADERS, rows)


# ------------------------------------------------------------------ JSON
def to_json(value):
    return json.dumps(value, indent=2, sort_keys=True, ensure_ascii=False) + "\n"


def money_to_dict(money):
    if money is None:
        return None
    return {"amount": money.amount_str(), "currency": money.currency}


def posting_to_dict(p):
    return {"account": p.account, "amount": money_to_dict(p.amount), "note": p.note}


def transaction_to_dict(tx):
    return {
        "id": tx.id,
        "date": _date_text(tx.date),
        "flag": tx.flag,
        "payee": tx.payee,
        "narration": tx.narration,
        "tags": _tags(tx),
        "postings": [posting_to_dict(p) for p in tx.postings],
    }


def transactions_to_json(txs):
    return to_json([transaction_to_dict(tx) for tx in txs])


_TX_KEYS = {"id", "date", "flag", "payee", "narration", "tags", "postings"}
_POSTING_KEYS = {"account", "amount", "note"}


def money_from_dict(obj, where="amount"):
    """Read a money object {"amount": text, "currency": text}; ExportError otherwise."""
    if not isinstance(obj, dict) or set(obj) != {"amount", "currency"}:
        raise ExportError("%s: an amount must be an object with exactly 'amount' and 'currency'" % where)
    if not isinstance(obj["amount"], str) or not isinstance(obj["currency"], str):
        raise ExportError("%s: 'amount' and 'currency' must be text" % where)
    try:
        return Money(parse_amount(obj["amount"], obj["currency"]), obj["currency"])
    except TallybookError as e:
        raise ExportError("%s: %s" % (where, e.message)) from None


def transactions_from_json(text):
    try:
        data = json.loads(text)
    except (ValueError, TypeError) as e:
        raise ExportError("not valid JSON: %s" % e) from None
    if not isinstance(data, list):
        raise ExportError("expected a JSON array of transactions")
    out = []
    for i, item in enumerate(data, 1):
        where = "transaction %d" % i
        if not isinstance(item, dict):
            raise ExportError("%s: not an object" % where)
        for k in item:
            if k not in _TX_KEYS:
                raise ExportError("%s: unknown key %r" % (where, k))
        for k in ("date", "payee", "postings"):
            if k not in item:
                raise ExportError("%s: missing %r" % (where, k))
        if not isinstance(item["date"], str):
            raise ExportError("%s: invalid date %r" % (where, item["date"]))
        try:
            d = parse_date(item["date"])
        except DateError as e:
            raise ExportError("%s: %s" % (where, e.message)) from None
        tid = item.get("id")
        if tid is not None and (not is_int(tid) or tid < 1):
            raise ExportError("%s: invalid id %r" % (where, tid))
        flag = item.get("flag", "*")
        if flag not in ("*", "!") or not isinstance(flag, str):
            raise ExportError("%s: invalid flag %r" % (where, flag))
        payee = item["payee"]
        if not isinstance(payee, str):
            raise ExportError("%s: payee must be text" % where)
        narration = item.get("narration", "")
        if not isinstance(narration, str):
            raise ExportError("%s: narration must be text" % where)
        tags = item.get("tags", [])
        if not isinstance(tags, list) or not all(isinstance(t, str) for t in tags):
            raise ExportError("%s: tags must be a list of text" % where)
        postings_raw = item["postings"]
        if not isinstance(postings_raw, list):
            raise ExportError("%s: postings must be a list" % where)
        postings = []
        for j, pr in enumerate(postings_raw, 1):
            pwhere = "%s posting %d" % (where, j)
            if not isinstance(pr, dict):
                raise ExportError("%s: not an object" % pwhere)
            for k in pr:
                if k not in _POSTING_KEYS:
                    raise ExportError("%s: unknown key %r" % (pwhere, k))
            if "account" not in pr or not isinstance(pr["account"], str):
                raise ExportError("%s: account missing or not text" % pwhere)
            amount = pr.get("amount")
            if amount is not None:
                amount = money_from_dict(amount, pwhere)
            note = pr.get("note", "")
            if not isinstance(note, str):
                raise ExportError("%s: note must be text" % pwhere)
            postings.append(Posting(pr["account"], amount, note))
        out.append(Transaction(d, payee, narration, postings, tuple(sorted(set(tags))), flag, tid))
    return out


# ---------------------------------------------------------------- tables
def _cell(value):
    text = "" if value is None else str(value)
    return text.replace("\t", " ").replace("\r", " ").replace("\n", " ")


def render_table(headers, rows, align=None):
    headers = [_cell(h) for h in headers]
    n = len(headers)
    if n == 0:
        return ""
    if align is None:
        aligns = ["l"] * n
    else:
        if not isinstance(align, (str, list, tuple)):
            raise ExportError("invalid alignment %r" % (align,))
        aligns = list(align)
        if len(aligns) != n or any(a not in ("l", "r") for a in aligns):
            raise ExportError("invalid alignment %r for %d columns" % (align, n))
    body = []
    for row in rows:
        cells = [_cell(c) for c in row]
        if len(cells) != n:
            raise ExportError("a row has %d cells, expected %d" % (len(cells), n))
        body.append(cells)
    widths = [len(h) for h in headers]
    for cells in body:
        for i, c in enumerate(cells):
            widths[i] = max(widths[i], len(c))

    def line(cells):
        parts = [c.ljust(widths[i]) if aligns[i] == "l" else c.rjust(widths[i]) for i, c in enumerate(cells)]
        return "  ".join(parts).rstrip(" ")

    out = [line(headers), line(["-" * w for w in widths])]
    out.extend(line(c) for c in body)
    return "\n".join(out) + "\n"

"""Exact money: whole minor units and a currency code."""

import re

from tallybook.currency import CurrencyError, currency
from tallybook.errors import ValidationError, is_int

__all__ = ["Money", "MoneyError", "parse_amount", "format_minor", "round_div"]


class MoneyError(ValidationError):
    """A bad amount or an operation mixing currencies."""


def round_div(n, d):
    """n / d rounded to the nearest integer, halves away from zero."""
    if not is_int(n) or not is_int(d):
        raise MoneyError("round_div needs integers, got %r and %r" % (n, d))
    if d <= 0:
        raise MoneyError("round_div needs a positive divisor, got %r" % (d,))
    q, r = divmod(abs(n), d)
    if 2 * r >= d:
        q += 1
    return q if n >= 0 else -q


def format_minor(minor, code):
    exp = currency(code).exponent
    if not is_int(minor):
        raise MoneyError("minor units must be an integer, got %r" % (minor,))
    sign = "-" if minor < 0 else ""
    digits = str(abs(minor))
    if exp == 0:
        return sign + digits
    digits = digits.rjust(exp + 1, "0")
    return sign + digits[:-exp] + "." + digits[-exp:]


_AMOUNT_RE = re.compile(r"([+-]?)([0-9]+)(?:\.([0-9]+))?")


def parse_amount(text, code):
    exp = currency(code).exponent
    if not isinstance(text, str):
        raise MoneyError("invalid amount %r: expected text" % (text,))
    m = _AMOUNT_RE.fullmatch(text)
    if not m:
        raise MoneyError("invalid amount '%s'" % text)
    sign, whole, frac = m.groups()
    if frac is not None:
        if exp == 0:
            raise MoneyError("invalid amount '%s': %s has no decimals" % (text, code))
        if len(frac) > exp:
            raise MoneyError("invalid amount '%s': %s has at most %d decimals" % (text, code, exp))
    frac = (frac or "").ljust(exp, "0")
    value = int(whole) * 10 ** exp + (int(frac) if frac else 0)
    return -value if sign == "-" else value


class Money:
    __slots__ = ("_minor", "_currency")

    def __init__(self, minor, currency_code):
        if not is_int(minor):
            raise MoneyError("minor units must be an integer, got %r" % (minor,))
        currency(currency_code)
        object.__setattr__(self, "_minor", int(minor))
        object.__setattr__(self, "_currency", currency_code)

    @property
    def minor(self):
        return self._minor

    @property
    def currency(self):
        return self._currency

    @property
    def exponent(self):
        return currency(self._currency).exponent

    def __setattr__(self, name, value):
        raise AttributeError("Money is immutable")

    def __delattr__(self, name):
        raise AttributeError("Money is immutable")

    def __reduce__(self):
        return (Money, (self._minor, self._currency))

    def __copy__(self):
        return self

    def __deepcopy__(self, memo):
        return self

    @classmethod
    def zero(cls, code):
        return cls(0, code)

    @classmethod
    def of(cls, text, code):
        return cls(parse_amount(text, code), code)

    @classmethod
    def parse(cls, text):
        if not isinstance(text, str):
            raise MoneyError("invalid money %r: expected text" % (text,))
        parts = text.split(" ")
        if len(parts) != 2 or not parts[0] or not parts[1] or any(c in text for c in "\t\r\n\v\f"):
            raise MoneyError("invalid money '%s': expected 'AMOUNT CUR'" % (text,))
        amount, code = parts
        currency(code)
        return cls(parse_amount(amount, code), code)

    def amount_str(self):
        return format_minor(self._minor, self._currency)

    def __str__(self):
        return "%s %s" % (self.amount_str(), self._currency)

    def __repr__(self):
        return "Money(%d, '%s')" % (self._minor, self._currency)

    def __hash__(self):
        return hash((self._minor, self._currency))

    def __eq__(self, other):
        if not isinstance(other, Money):
            return False
        return self._minor == other._minor and self._currency == other._currency

    def __ne__(self, other):
        return not self.__eq__(other)

    def _same(self, other, verb):
        if not isinstance(other, Money):
            return False
        if other._currency != self._currency:
            raise MoneyError("cannot %s %s and %s: different currencies" % (verb, self._currency, other._currency))
        return True

    def __add__(self, other):
        if not self._same(other, "add"):
            return NotImplemented
        return Money(self._minor + other._minor, self._currency)

    def __sub__(self, other):
        if not self._same(other, "subtract"):
            return NotImplemented
        return Money(self._minor - other._minor, self._currency)

    def __neg__(self):
        return Money(-self._minor, self._currency)

    def __pos__(self):
        return self

    def __abs__(self):
        return Money(abs(self._minor), self._currency)

    def __mul__(self, other):
        if not is_int(other):
            return NotImplemented
        return Money(self._minor * other, self._currency)

    __rmul__ = __mul__

    def __lt__(self, other):
        if not self._same(other, "compare"):
            return NotImplemented
        return self._minor < other._minor

    def __le__(self, other):
        if not self._same(other, "compare"):
            return NotImplemented
        return self._minor <= other._minor

    def __gt__(self, other):
        if not self._same(other, "compare"):
            return NotImplemented
        return self._minor > other._minor

    def __ge__(self, other):
        if not self._same(other, "compare"):
            return NotImplemented
        return self._minor >= other._minor

    def is_zero(self):
        return self._minor == 0

    def sign(self):
        return (self._minor > 0) - (self._minor < 0)

    def scale(self, num, den=1):
        if not is_int(num) or not is_int(den):
            raise MoneyError("scale needs integers, got %r and %r" % (num, den))
        if den == 0:
            raise MoneyError("scale by a ratio with a zero denominator")
        if den < 0:
            num, den = -num, -den
        return Money(round_div(self._minor * num, den), self._currency)

    def allocate(self, weights):
        if not isinstance(weights, (list, tuple)) or not weights:
            raise MoneyError("allocate needs a non-empty list of weights")
        for w in weights:
            if not is_int(w) or w < 0:
                raise MoneyError("invalid weight %r: weights are whole numbers of at least 0" % (w,))
        total = sum(weights)
        if total <= 0:
            raise MoneyError("allocate needs weights with a positive sum")
        amount = abs(self._minor)
        parts = [amount * w // total for w in weights]
        rems = [amount * w % total for w in weights]
        left = amount - sum(parts)
        order = sorted(range(len(weights)), key=lambda i: (-rems[i], i))
        for i in order[:left]:
            parts[i] += 1
        neg = self._minor < 0
        return [Money(-p if neg else p, self._currency) for p in parts]
