"""Budgets: allowances per calendar period and how spending compares."""

import datetime
import decimal
import re
from fractions import Fraction

from tallybook.dates import Period, last_day
from tallybook.errors import ValidationError
from tallybook.money import Money, round_div

__all__ = ["Budget", "BudgetError", "BudgetLine", "budget_status"]

PERIOD_KINDS = ("month", "quarter", "year")
_KIND_ORDER = {"month": 0, "quarter": 1, "year": 2}
_SEGMENT_RE = re.compile(r"[A-Z][A-Za-z0-9_-]*")


class BudgetError(ValidationError):
    """A malformed budget or budget request."""


def _is_date(value):
    return isinstance(value, datetime.date) and not isinstance(value, datetime.datetime)


def _check_pattern(pattern):
    if not isinstance(pattern, str):
        raise BudgetError("invalid budget pattern %r: expected text" % (pattern,))
    if not pattern:
        raise BudgetError("invalid budget pattern '': it is empty")
    for seg in pattern.split(":"):
        if seg != "*" and not _SEGMENT_RE.fullmatch(seg):
            raise BudgetError("invalid budget pattern '%s': each segment is '*' or an account name segment"
                              % pattern)


def _pattern_matches(segs, path):
    parts = path.split(":")
    if len(parts) < len(segs):
        return False
    return all(s == "*" or s == p for s, p in zip(segs, parts))


class Budget:
    __slots__ = ("_pattern", "_period_kind", "_amount", "_start")

    def __init__(self, pattern, period_kind, amount, start):
        _check_pattern(pattern)
        if not isinstance(period_kind, str) or period_kind not in PERIOD_KINDS:
            raise BudgetError("invalid budget period kind %r: expected month, quarter or year" % (period_kind,))
        if not isinstance(amount, Money):
            raise BudgetError("invalid budget amount %r: expected Money" % (amount,))
        if amount.minor <= 0:
            raise BudgetError("invalid budget amount %s: it must be greater than zero" % (amount,))
        if not _is_date(start):
            raise BudgetError("invalid budget start %r: expected a date" % (start,))
        object.__setattr__(self, "_pattern", pattern)
        object.__setattr__(self, "_period_kind", period_kind)
        object.__setattr__(self, "_amount", amount)
        object.__setattr__(self, "_start", start)

    pattern = property(lambda self: self._pattern)
    period_kind = property(lambda self: self._period_kind)
    amount = property(lambda self: self._amount)
    start = property(lambda self: self._start)

    def __setattr__(self, name, value):
        raise AttributeError("Budget is immutable")

    def __delattr__(self, name):
        raise AttributeError("Budget is immutable")

    def __reduce__(self):
        return (Budget, (self._pattern, self._period_kind, self._amount, self._start))

    def _key(self):
        return (self._pattern, self._period_kind, self._amount, self._start)

    def __eq__(self, other):
        if not isinstance(other, Budget):
            return NotImplemented
        return self._key() == other._key()

    def __ne__(self, other):
        r = self.__eq__(other)
        return r if r is NotImplemented else not r

    def __hash__(self):
        return hash(self._key())

    def __repr__(self):
        return "Budget(%r, %r, %r, %r)" % self._key()


def _calendar_period(d, kind):
    if kind == "month":
        return datetime.date(d.year, d.month, 1), datetime.date(d.year, d.month, last_day(d.year, d.month))
    if kind == "quarter":
        mo = (d.month - 1) // 3 * 3 + 1
        return datetime.date(d.year, mo, 1), datetime.date(d.year, mo + 2, last_day(d.year, mo + 2))
    return datetime.date(d.year, 1, 1), datetime.date(d.year, 12, 31)


def _allowance_fraction(budget, period):
    """Sum of overlapping-days / days for each calendar period in force, or None if not in force."""
    first_start, _ = _calendar_period(budget.start, budget.period_kind)
    if first_start > period.end:
        return None
    total = Fraction(0)
    d = max(first_start, period.start)
    while d <= period.end:
        ps, pe = _calendar_period(d, budget.period_kind)
        lo = max(ps, period.start)
        hi = min(pe, period.end)
        total += Fraction((hi - lo).days + 1, (pe - ps).days + 1)
        if pe >= period.end:
            break
        d = pe + datetime.timedelta(days=1)
    return total


def _percent(actual, allowance):
    if allowance == 0:
        tenths = 0 if actual == 0 else 1000
    else:
        tenths = round_div(actual * 1000, allowance)
    sign = "-" if tenths < 0 else ""
    q, r = divmod(abs(tenths), 10)
    return decimal.Decimal("%s%d.%d" % (sign, q, r))


class BudgetLine:
    __slots__ = ("_pattern", "_period_kind", "_budget", "_actual", "_remaining", "_percent", "_over", "_accounts")
    _FIELDS = ("pattern", "period_kind", "budget", "actual", "remaining", "percent", "over", "accounts")

    def __init__(self, pattern, period_kind, budget, actual, remaining, percent, over, accounts):
        for name, value in zip(self._FIELDS, (pattern, period_kind, budget, actual, remaining, percent, over,
                                              tuple(tuple(a) for a in accounts))):
            object.__setattr__(self, "_" + name, value)

    pattern = property(lambda self: self._pattern)
    period_kind = property(lambda self: self._period_kind)
    budget = property(lambda self: self._budget)
    actual = property(lambda self: self._actual)
    remaining = property(lambda self: self._remaining)
    percent = property(lambda self: self._percent)
    over = property(lambda self: self._over)
    accounts = property(lambda self: self._accounts)

    def __setattr__(self, name, value):
        raise AttributeError("BudgetLine is immutable")

    def __delattr__(self, name):
        raise AttributeError("BudgetLine is immutable")

    def _key(self):
        return tuple(getattr(self, "_" + f) for f in self._FIELDS)

    def __reduce__(self):
        return (BudgetLine, self._key())

    def __eq__(self, other):
        if not isinstance(other, BudgetLine):
            return NotImplemented
        return self._key() == other._key()

    def __ne__(self, other):
        r = self.__eq__(other)
        return r if r is NotImplemented else not r

    def __hash__(self):
        return hash(self._key())

    def __repr__(self):
        return "BudgetLine(%s)" % ", ".join("%s=%r" % (f, getattr(self, f)) for f in self._FIELDS)

    def to_dict(self):
        def money(m):
            return {"amount": m.amount_str(), "currency": m.currency}
        return {
            "pattern": self._pattern,
            "period_kind": self._period_kind,
            "budget": money(self._budget),
            "actual": money(self._actual),
            "remaining": money(self._remaining),
            "percent": str(self._percent),
            "over": bool(self._over),
            "accounts": [{"account": a, "amount": money(m)} for a, m in self._accounts],
        }


def budget_status(budgets, ledger, period):
    if isinstance(budgets, (str, bytes)):
        raise BudgetError("budgets must be a list of Budget")
    try:
        budgets = list(budgets)
    except TypeError:
        raise BudgetError("budgets must be a list of Budget") from None
    for b in budgets:
        if not isinstance(b, Budget):
            raise BudgetError("not a budget: %r" % (b,))
    if not isinstance(period, Period):
        raise BudgetError("invalid period %r: expected a Period" % (period,))

    # Expense postings within the period, per account and currency.
    spending = {}
    for tx, p in ledger.postings():
        if not (period.start <= tx.date <= period.end):
            continue
        if p.amount is None or p.account.split(":", 1)[0] != "Expenses":
            continue
        key = (p.account, p.amount.currency)
        spending[key] = spending.get(key, 0) + p.amount.minor

    order = sorted(range(len(budgets)),
                   key=lambda i: (budgets[i].pattern, _KIND_ORDER[budgets[i].period_kind], budgets[i].start, i))
    lines = []
    for i in order:
        b = budgets[i]
        frac = _allowance_fraction(b, period)
        if frac is None:
            continue
        code = b.amount.currency
        scaled = frac * b.amount.minor
        allowance = round_div(scaled.numerator, scaled.denominator)
        segs = b.pattern.split(":")
        per_account = {}
        for (account, cur), minor in spending.items():
            if cur == code and _pattern_matches(segs, account):
                per_account[account] = per_account.get(account, 0) + minor
        actual = sum(per_account.values())
        accounts = tuple((a, Money(v, code)) for a, v in sorted(per_account.items()) if v != 0)
        lines.append(BudgetLine(b.pattern, b.period_kind, Money(allowance, code), Money(actual, code),
                                Money(allowance - actual, code), _percent(actual, allowance),
                                actual > allowance, accounts))
    return lines

"""Reports: trial balance, balance sheet, income statement, cash flow, register, net worth."""

import datetime

from tallybook.accounts import ROOT_TYPES
from tallybook.currency import currency as _currency
from tallybook.dates import Period, periods
from tallybook.errors import ValidationError
from tallybook.export import money_to_dict, render_table, to_csv
from tallybook.ledger import Ledger
from tallybook.money import Money, round_div

__all__ = ["trial_balance", "balance_sheet", "income_statement", "cashflow", "register", "net_worth",
           "render_text", "report_to_csv", "ReportError"]

REPORT_KINDS = ("trial_balance", "balance_sheet", "income_statement", "cashflow", "register", "net_worth")
STEPS = ("week", "month", "quarter", "year")


class ReportError(ValidationError):
    """A report that cannot be made or drawn."""


# ---------------------------------------------------------------- helpers
def _is_date(value):
    return isinstance(value, datetime.date) and not isinstance(value, datetime.datetime)


def _date_text(d):
    return None if d is None else "%04d-%02d-%02d" % (d.year, d.month, d.day)


def _check_ledger(ledger):
    if not isinstance(ledger, Ledger):
        raise ReportError("not a ledger: %r" % (ledger,))


def _check_as_of(as_of):
    if as_of is not None and not _is_date(as_of):
        raise ReportError("invalid date %r" % (as_of,))


def _check_period(period, optional=False):
    if period is None and optional:
        return
    if not isinstance(period, Period):
        raise ReportError("invalid period %r" % (period,))


def _check_convert_to(convert_to):
    if convert_to is not None:
        _currency(convert_to)  # CurrencyError as it is


def _type_of(path):
    return ROOT_TYPES.get(path.split(":", 1)[0])


def _m(minor, code):
    return money_to_dict(Money(minor, code))


def _money_list(sums, keep_zero):
    """A list of money dicts from {currency: minor}, sorted by currency."""
    return [_m(v, c) for c, v in sorted(sums.items()) if keep_zero or v != 0]


def _account_lines(sums):
    """Sorted (account, currency, minor) for non-zero entries of {(account, currency): minor}."""
    return [(a, c, v) for (a, c), v in sorted(sums.items()) if v != 0]


def _add(d, key, value):
    d[key] = d.get(key, 0) + value


def _percent(part, total):
    if total == 0:
        return "0.0"
    if total < 0:
        part, total = -part, -total
    tenths = round_div(part * 1000, total)
    if tenths == 0:
        return "0.0"
    sign = "-" if tenths < 0 else ""
    a = abs(tenths)
    return "%s%d.%d" % (sign, a // 10, a % 10)


def _convert(ledger, minor, code, convert_to, on):
    return ledger.rates.convert(Money(minor, code), convert_to, on)


# ------------------------------------------------------------ trial balance
def trial_balance(ledger, as_of=None):
    _check_ledger(ledger)
    _check_as_of(as_of)
    sums = {}
    for tx, p in ledger.postings():
        if as_of is not None and tx.date > as_of:
            continue
        _add(sums, (p.account, p.amount.currency), p.amount.minor)
    accounts = []
    totals = {}
    for account, cur, v in _account_lines(sums):
        t = totals.setdefault(cur, [0, 0])
        if v > 0:
            t[0] += v
        else:
            t[1] += -v
        accounts.append({"account": account, "type": _type_of(account),
                         "debit": _m(v, cur) if v > 0 else None,
                         "credit": _m(-v, cur) if v < 0 else None})
    return {"report": "trial_balance", "as_of": _date_text(as_of), "accounts": accounts,
            "totals": [{"currency": c, "debit": _m(d, c), "credit": _m(cr, c), "balanced": d == cr}
                       for c, (d, cr) in sorted(totals.items())]}


# ------------------------------------------------------------ balance sheet
def balance_sheet(ledger, as_of=None, convert_to=None, today=None):
    _check_ledger(ledger)
    _check_as_of(as_of)
    if convert_to is not None and as_of is None:
        raise ReportError("converting needs a date: give as_of with convert_to")
    _check_convert_to(convert_to)
    sections = {"asset": {}, "liability": {}, "equity": {}}
    retained = {}
    for tx, p in ledger.postings():
        if as_of is not None and tx.date > as_of:
            continue
        t = _type_of(p.account)
        cur, v = p.amount.currency, p.amount.minor
        if t == "asset":
            _add(sections["asset"], (p.account, cur), v)
        elif t in ("liability", "equity"):
            _add(sections[t], (p.account, cur), -v)
        elif t in ("income", "expense"):
            _add(retained, cur, -v)

    def section(kind):
        lines = []
        total = {}
        for account, cur, v in _account_lines(sections[kind]):
            if convert_to is None:
                lines.append({"account": account, "balance": _m(v, cur)})
                _add(total, cur, v)
            else:
                conv = _convert(ledger, v, cur, convert_to, as_of)
                lines.append({"account": account, "balance": money_to_dict(conv), "original": _m(v, cur)})
                _add(total, convert_to, conv.minor)
        return lines, total

    a_lines, a_total = section("asset")
    l_lines, l_total = section("liability")
    e_lines, e_total = section("equity")
    if convert_to is None:
        re_list = _money_list(retained, keep_zero=False)
        for c, v in retained.items():
            if v != 0:
                _add(e_total, c, v)
    else:
        nonzero = [(c, v) for c, v in sorted(retained.items()) if v != 0]
        re_list = []
        if nonzero:
            s = 0
            for c, v in nonzero:
                s += _convert(ledger, v, c, convert_to, as_of).minor
            re_list = [_m(s, convert_to)]
            _add(e_total, convert_to, s)
        for t in (a_total, l_total, e_total):
            t.setdefault(convert_to, 0)
    curs = set(a_total) | set(l_total) | set(e_total)
    balanced = all(a_total.get(c, 0) == l_total.get(c, 0) + e_total.get(c, 0) for c in curs)
    return {"report": "balance_sheet", "as_of": _date_text(as_of), "currency": convert_to,
            "assets": {"accounts": a_lines, "total": _money_list(a_total, True)},
            "liabilities": {"accounts": l_lines, "total": _money_list(l_total, True)},
            "equity": {"accounts": e_lines, "retained_earnings": re_list, "total": _money_list(e_total, True)},
            "balanced": balanced}


# --------------------------------------------------------- income statement
def income_statement(ledger, period, convert_to=None):
    _check_ledger(ledger)
    _check_period(period)
    _check_convert_to(convert_to)
    sums = {"income": {}, "expense": {}}
    for tx, p in ledger.postings():
        if not (period.start <= tx.date <= period.end):
            continue
        t = _type_of(p.account)
        if t == "income":
            _add(sums["income"], (p.account, p.amount.currency), -p.amount.minor)
        elif t == "expense":
            _add(sums["expense"], (p.account, p.amount.currency), p.amount.minor)

    def section(kind):
        raw = _account_lines(sums[kind])
        total = {}
        items = []
        for account, cur, v in raw:
            if convert_to is None:
                items.append((account, cur, v, None))
                _add(total, cur, v)
            else:
                conv = _convert(ledger, v, cur, convert_to, period.end)
                items.append((account, convert_to, conv.minor, _m(v, cur)))
                _add(total, convert_to, conv.minor)
        if convert_to is not None:
            total.setdefault(convert_to, 0)
        lines = []
        for account, cur, v, original in items:
            line = {"account": account, "amount": _m(v, cur), "percent": _percent(v, total[cur])}
            if original is not None:
                line["original"] = original
            lines.append(line)
        return lines, total

    i_lines, i_total = section("income")
    e_lines, e_total = section("expense")
    net = {c: i_total.get(c, 0) - e_total.get(c, 0) for c in set(i_total) | set(e_total)}
    return {"report": "income_statement", "start": _date_text(period.start), "end": _date_text(period.end),
            "currency": convert_to,
            "income": {"accounts": i_lines, "total": _money_list(i_total, True)},
            "expenses": {"accounts": e_lines, "total": _money_list(e_total, True)},
            "net": _money_list(net, True)}


# ----------------------------------------------------------------- cashflow
def cashflow(ledger, period):
    _check_ledger(ledger)
    _check_period(period)
    opening, closing, flows = {}, {}, {}
    for tx in ledger.transactions():
        if tx.date > period.end:
            continue
        for p in tx.postings:
            if _type_of(p.account) == "asset":
                cur = p.amount.currency
                closing.setdefault(cur, 0)
                opening.setdefault(cur, 0)
                closing[cur] += p.amount.minor
                if tx.date < period.start:
                    opening[cur] += p.amount.minor
        if tx.date < period.start:
            continue
        asset_sum = {}
        for p in tx.postings:
            if _type_of(p.account) == "asset":
                _add(asset_sum, p.amount.currency, p.amount.minor)
        for p in tx.postings:
            if _type_of(p.account) != "asset" and asset_sum.get(p.amount.currency, 0) != 0:
                _add(flows, (p.account, p.amount.currency), -p.amount.minor)
    inflows, outflows = [], []
    total_in = {c: 0 for c in closing}
    total_out = {c: 0 for c in closing}
    for account, cur, v in _account_lines(flows):
        if v > 0:
            inflows.append({"account": account, "amount": _m(v, cur)})
            total_in[cur] = total_in.get(cur, 0) + v
        else:
            outflows.append({"account": account, "amount": _m(-v, cur)})
            total_out[cur] = total_out.get(cur, 0) - v
    net = {c: total_in.get(c, 0) - total_out.get(c, 0) for c in closing}
    return {"report": "cashflow", "start": _date_text(period.start), "end": _date_text(period.end),
            "opening": _money_list(opening, True), "inflows": inflows, "outflows": outflows,
            "total_in": _money_list(total_in, True), "total_out": _money_list(total_out, True),
            "net": _money_list(net, True), "closing": _money_list(closing, True)}


# ----------------------------------------------------------------- register
def register(ledger, account, period=None, rollup=False):
    _check_ledger(ledger)
    _check_period(period, optional=True)
    if not isinstance(rollup, bool):
        raise ReportError("rollup must be true or false, got %r" % (rollup,))
    if not isinstance(account, str) or not ledger.chart.exists(account):
        raise ReportError("no such account %s" % ("'%s'" % account if isinstance(account, str) else repr(account)))
    prefix = account + ":"
    opening, running, rows = {}, {}, []
    for tx in ledger.transactions():
        if period is not None and tx.date > period.end:
            continue
        for p in tx.postings:
            if not (p.account == account or (rollup and p.account.startswith(prefix))):
                continue
            cur, v = p.amount.currency, p.amount.minor
            opening.setdefault(cur, 0)
            running.setdefault(cur, 0)
            running[cur] += v
            if period is not None and tx.date < period.start:
                opening[cur] += v
                continue
            rows.append({"date": _date_text(tx.date), "id": tx.id, "payee": tx.payee, "narration": tx.narration,
                         "account": p.account, "amount": _m(v, cur), "balance": _m(running[cur], cur)})
    return {"report": "register", "account": account, "rollup": rollup,
            "start": _date_text(period.start) if period is not None else None,
            "end": _date_text(period.end) if period is not None else None,
            "opening": _money_list(opening, True), "rows": rows, "closing": _money_list(running, True)}


# ---------------------------------------------------------------- net worth
def net_worth(ledger, period, step="month"):
    _check_ledger(ledger)
    _check_period(period)
    if not isinstance(step, str) or step not in STEPS:
        raise ReportError("unknown step %r: expected week, month, quarter or year" % (step,))
    steps = periods(period.start, period.end, step)
    txs = ledger.transactions()
    points = []
    for st in steps:
        d = st.end
        assets, liabilities = {}, {}
        for tx in txs:
            if tx.date > d:
                break
            for p in tx.postings:
                t = _type_of(p.account)
                if t in ("asset", "liability"):
                    cur = p.amount.currency
                    assets.setdefault(cur, 0)
                    liabilities.setdefault(cur, 0)
                    if t == "asset":
                        assets[cur] += p.amount.minor
                    else:
                        liabilities[cur] -= p.amount.minor
        net = {c: assets[c] - liabilities[c] for c in assets}
        points.append({"date": _date_text(d), "assets": _money_list(assets, True),
                       "liabilities": _money_list(liabilities, True), "net": _money_list(net, True)})
    return {"report": "net_worth", "start": _date_text(period.start), "end": _date_text(period.end),
            "step": step, "points": points}


# --------------------------------------------------------------- rendering
def _kind(report):
    if not isinstance(report, dict) or report.get("report") not in REPORT_KINDS:
        raise ReportError("not a report: %r" % (report,))
    return report["report"]


def _mt(m):
    return "%s %s" % (m["amount"], m["currency"])


def _blocks(width, *blocks):
    rows = []
    for b in blocks:
        if not b:
            continue
        if rows:
            rows.append([""] * width)
        rows.extend(b)
    return rows


def _text_trial_balance(r):
    title = "Trial balance as of %s" % r["as_of"] if r["as_of"] else "Trial balance"
    rows = [[a["account"], a["type"], _mt(a["debit"]) if a["debit"] else "",
             _mt(a["credit"]) if a["credit"] else ""] for a in r["accounts"]]
    rows += [["Total", "", _mt(t["debit"]), _mt(t["credit"])] for t in r["totals"]]
    return title, ["Account", "Type", "Debit", "Credit"], rows, "llrr"


def _text_balance_sheet(r):
    title = "Balance sheet as of %s" % r["as_of"] if r["as_of"] else "Balance sheet"
    if r.get("currency"):
        title += " (in %s)" % r["currency"]

    def block(key, heading, total_label, extra=()):
        sec = r[key]
        b = [[heading, ""]]
        b += [["  " + a["account"], _mt(a["balance"])] for a in sec["accounts"]]
        b += list(extra)
        b += [[total_label, _mt(m)] for m in sec["total"]]
        return b

    rows = _blocks(2, block("assets", "Assets", "Total assets"),
                   block("liabilities", "Liabilities", "Total liabilities"),
                   block("equity", "Equity", "Total equity",
                         [["  Retained earnings", _mt(m)] for m in r["equity"]["retained_earnings"]]))
    return title, ["Account", "Balance"], rows, "lr"


def _text_income_statement(r):
    title = "Income statement %s to %s" % (r["start"], r["end"])
    if r.get("currency"):
        title += " (in %s)" % r["currency"]

    def block(key, heading, total_label):
        sec = r[key]
        b = [[heading, "", ""]]
        b += [["  " + a["account"], _mt(a["amount"]), a["percent"] + "%"] for a in sec["accounts"]]
        b += [[total_label, _mt(m), ""] for m in sec["total"]]
        return b

    rows = _blocks(3, block("income", "Income", "Total income"),
                   block("expenses", "Expenses", "Total expenses"),
                   [["Net income", _mt(m), ""] for m in r["net"]])
    return title, ["Account", "Amount", "Percent"], rows, "lrr"


def _text_cashflow(r):
    title = "Cash flow %s to %s" % (r["start"], r["end"])

    def block(lines, totals, heading, total_label):
        b = [[heading, ""]]
        b += [["  " + a["account"], _mt(a["amount"])] for a in lines]
        b += [[total_label, _mt(m)] for m in totals]
        return b

    rows = _blocks(2, [["Opening balance", _mt(m)] for m in r["opening"]],
                   block(r["inflows"], r["total_in"], "Money in", "Total money in"),
                   block(r["outflows"], r["total_out"], "Money out", "Total money out"),
                   [["Net change", _mt(m)] for m in r["net"]] + [["Closing balance", _mt(m)] for m in r["closing"]])
    return title, ["Account", "Amount"], rows, "lr"


def _text_net_worth(r):
    title = "Net worth %s to %s (by %s)" % (r["start"], r["end"], r["step"])
    rows = []
    for p in r["points"]:
        if not p["assets"]:
            rows.append([p["date"], "", "", ""])
        for a, l, n in zip(p["assets"], p["liabilities"], p["net"]):
            rows.append([p["date"], _mt(a), _mt(l), _mt(n)])
    return title, ["Date", "Assets", "Liabilities", "Net"], rows, "lrrr"


def _text_register(r):
    title = "Register %s" % r["account"]
    if r["rollup"]:
        title += " (with sub-accounts)"
    if r["start"] is not None:
        title += " %s to %s" % (r["start"], r["end"])
    rows = [["", "", "Opening balance", "", "", _mt(m)] for m in r["opening"]]
    for row in r["rows"]:
        rows.append([row["date"], "" if row["id"] is None else str(row["id"]), row["payee"], row["account"],
                     _mt(row["amount"]), _mt(row["balance"])])
    rows += [["", "", "Closing balance", "", "", _mt(m)] for m in r["closing"]]
    return title, ["Date", "Id", "Payee", "Account", "Amount", "Balance"], rows, "llllrr"


_TEXT = {"trial_balance": _text_trial_balance, "balance_sheet": _text_balance_sheet,
         "income_statement": _text_income_statement, "cashflow": _text_cashflow,
         "net_worth": _text_net_worth, "register": _text_register}


def render_text(report):
    kind = _kind(report)
    try:
        title, headers, rows, align = _TEXT[kind](report)
    except (KeyError, TypeError, IndexError, AttributeError):
        raise ReportError("malformed %s report" % kind) from None
    return title + "\n\n" + render_table(headers, rows, align)


# --------------------------------------------------------------------- CSV
def _csv_trial_balance(r):
    rows = []
    for a in r["accounts"]:
        m = a["debit"] or a["credit"]
        rows.append([a["account"], a["type"], m["currency"], a["debit"]["amount"] if a["debit"] else "",
                     a["credit"]["amount"] if a["credit"] else ""])
    return ["account", "type", "currency", "debit", "credit"], rows


def _csv_balance_sheet(r):
    rows = []
    for key in ("assets", "liabilities", "equity"):
        for a in r[key]["accounts"]:
            rows.append([key, a["account"], a["balance"]["currency"], a["balance"]["amount"]])
    for m in r["equity"]["retained_earnings"]:
        rows.append(["equity", "Retained earnings", m["currency"], m["amount"]])
    return ["section", "account", "currency", "balance"], rows


def _csv_income_statement(r):
    rows = []
    for key in ("income", "expenses"):
        for a in r[key]["accounts"]:
            rows.append([key, a["account"], a["amount"]["currency"], a["amount"]["amount"], a["percent"]])
    return ["section", "account", "currency", "amount", "percent"], rows


def _csv_cashflow(r):
    rows = [["opening", "", m["currency"], m["amount"]] for m in r["opening"]]
    rows += [["in", a["account"], a["amount"]["currency"], a["amount"]["amount"]] for a in r["inflows"]]
    rows += [["out", a["account"], a["amount"]["currency"], a["amount"]["amount"]] for a in r["outflows"]]
    rows += [["closing", "", m["currency"], m["amount"]] for m in r["closing"]]
    return ["section", "account", "currency", "amount"], rows


def _csv_register(r):
    rows = [[row["date"], "" if row["id"] is None else row["id"], row["payee"], row["narration"], row["account"],
             row["amount"]["currency"], row["amount"]["amount"], row["balance"]["amount"]] for row in r["rows"]]
    return ["date", "id", "payee", "narration", "account", "currency", "amount", "balance"], rows


def _csv_net_worth(r):
    rows = []
    for p in r["points"]:
        for a, l, n in zip(p["assets"], p["liabilities"], p["net"]):
            rows.append([p["date"], a["currency"], a["amount"], l["amount"], n["amount"]])
    return ["date", "currency", "assets", "liabilities", "net"], rows


_CSV = {"trial_balance": _csv_trial_balance, "balance_sheet": _csv_balance_sheet,
        "income_statement": _csv_income_statement, "cashflow": _csv_cashflow,
        "net_worth": _csv_net_worth, "register": _csv_register}


def report_to_csv(report):
    kind = _kind(report)
    try:
        headers, rows = _CSV[kind](report)
    except (KeyError, TypeError, IndexError, AttributeError):
        raise ReportError("malformed %s report" % kind) from None
    return to_csv(headers, rows)

"""Rules that sort transactions into accounts."""

import dataclasses
import datetime
import re
from fractions import Fraction

from tallybook.accounts import valid_any_root_path
from tallybook.currency import currency, is_currency
from tallybook.dates import DateError, parse_date
from tallybook.errors import ParseError

__all__ = ["parse_rules", "RuleSet", "Rule", "RulesError"]


class RulesError(ParseError):
    """A mistake in a rules file; .line is the 1-based line of the first bad rule."""

    def __init__(self, message="", line=None, **detail):
        super().__init__(message, **detail)
        self.line = line


class _Bad(Exception):
    """Internal: a problem on the line being parsed."""


_LINE_SPLIT_RE = re.compile(r"\r\n|\n|\r")
_OP_CHARS = "<>=!~"
_OPS = ("<=", ">=", "!=", "!~", "<", ">", "=", "~")
_SPACE = " \t"
_AMOUNT_RE = re.compile(r"([+-]?[0-9]+(?:\.[0-9]+)?)([A-Za-z]*)")
_TAG_RE = re.compile(r"[A-Za-z0-9_-]+")

_TEXT_FIELDS = ("payee", "narration")
_ORDER_FIELDS = ("amount", "date")
_TEXT_OPS = ("=", "!=", "~", "!~")
_ORDER_OPS = ("<", "<=", ">", ">=", "=", "!=")
_ACTIONS = ("account", "tag", "narration", "payee", "flag")

# token kinds
_WORD, _STR, _OP = "word", "string", "operator"


def _tokenize(line):
    tokens = []
    i, n = 0, len(line)
    while i < n:
        c = line[i]
        if c in _SPACE:
            i += 1
            continue
        if c == '"':
            j = i + 1
            buf = []
            while True:
                if j >= n:
                    raise _Bad("string is never closed")
                ch = line[j]
                if ch == "\\":
                    if j + 1 >= n:
                        raise _Bad("string is never closed")
                    nxt = line[j + 1]
                    if nxt == '"':
                        buf.append('"')
                    else:
                        buf.append(ch + nxt)
                    j += 2
                    continue
                if ch == '"':
                    break
                buf.append(ch)
                j += 1
            tokens.append((_STR, "".join(buf)))
            i = j + 1
            continue
        if c in _OP_CHARS:
            two = line[i:i + 2]
            if two in _OPS:
                tokens.append((_OP, two))
                i += 2
                continue
            if c == "!":
                # a lone "!" is a word (as in "flag !")
                tokens.append((_WORD, "!"))
                i += 1
                continue
            tokens.append((_OP, c))
            i += 1
            continue
        j = i
        while j < n and line[j] not in _SPACE and line[j] != '"' and line[j] not in _OP_CHARS:
            j += 1
        tokens.append((_WORD, line[i:j]))
        i = j
    return tokens


def _show(tok):
    if tok is None:
        return "end of line"
    kind, text = tok
    if kind == _STR:
        return '"%s"' % text
    return "'%s'" % text


class _Cond:
    __slots__ = ("field", "op", "value", "code", "regex")

    def __init__(self, field, op, value, code=None, regex=None):
        self.field = field
        self.op = op
        self.value = value
        self.code = code
        self.regex = regex

    def holds(self, fields):
        f = self.field
        if f in _TEXT_FIELDS:
            text = fields.get(f)
            if text is None:
                text = ""
            text = str(text)
            if self.op == "=":
                return text.casefold() == self.value.casefold()
            if self.op == "!=":
                return text.casefold() != self.value.casefold()
            found = self.regex.search(text) is not None
            return found if self.op == "~" else not found
        if f == "amount":
            money = fields.get("amount")
            if money is None:
                return False
            if self.code is not None and money.currency != self.code:
                return False
            left = Fraction(money.minor, 10 ** currency(money.currency).exponent)
        else:
            left = fields.get("date")
            if not isinstance(left, datetime.date):
                return False
            if isinstance(left, datetime.datetime):
                left = left.date()
        right = self.value
        op = self.op
        if op == "<":
            return left < right
        if op == "<=":
            return left <= right
        if op == ">":
            return left > right
        if op == ">=":
            return left >= right
        if op == "=":
            return left == right
        return left != right


class Rule:
    """One rule: conditions (empty for `any`) and actions."""

    def __init__(self, line, conditions, account=None, tags=(), narration=None, payee=None, flag=None,
                 text=""):
        self.line = line
        self.conditions = tuple(conditions)
        self.account = account
        self.tags = tuple(tags)
        self.narration = narration
        self.payee = payee
        self.flag = flag
        self.text = text

    def matches(self, fields):
        return all(c.holds(fields) for c in self.conditions)

    def actions(self):
        out = {}
        if self.account is not None:
            out["account"] = self.account
        if self.tags:
            out["tags"] = list(self.tags)
        if self.narration is not None:
            out["narration"] = self.narration
        if self.payee is not None:
            out["payee"] = self.payee
        if self.flag is not None:
            out["flag"] = self.flag
        return out

    def __repr__(self):
        return "Rule(line=%d, %r)" % (self.line, self.text)


def _parse_condition(tokens, pos):
    """Parse one condition starting at tokens[pos]; returns (cond, new_pos)."""
    tok = tokens[pos] if pos < len(tokens) else None
    if tok is None or tok[0] != _WORD:
        raise _Bad("expected a condition, found %s" % _show(tok))
    field = tok[1]
    if field in ("then", "and"):
        raise _Bad("expected a condition, found %s" % _show(tok))
    if field not in _TEXT_FIELDS and field not in _ORDER_FIELDS:
        raise _Bad("unknown field %s" % _show(tok))
    pos += 1
    tok = tokens[pos] if pos < len(tokens) else None
    if tok is None or tok[0] != _OP:
        raise _Bad("expected an operator after '%s', found %s" % (field, _show(tok)))
    op = tok[1]
    allowed = _TEXT_OPS if field in _TEXT_FIELDS else _ORDER_OPS
    if op not in allowed:
        raise _Bad("operator '%s' does not work with '%s'" % (op, field))
    pos += 1
    tok = tokens[pos] if pos < len(tokens) else None
    if tok is None or (tok[0] == _WORD and tok[1] in ("then", "and")):
        raise _Bad("missing value after '%s %s'" % (field, op))
    if field in _TEXT_FIELDS:
        if tok[0] != _STR:
            raise _Bad("expected a quoted text after '%s %s', found %s" % (field, op, _show(tok)))
        value = tok[1]
        regex = None
        if op in ("~", "!~"):
            try:
                regex = re.compile(value, re.IGNORECASE)
            except (re.error, OverflowError, RecursionError, ValueError) as e:
                raise _Bad('invalid regular expression "%s": %s' % (value, e))
        return _Cond(field, op, value, regex=regex), pos + 1
    if tok[0] != _WORD:
        raise _Bad("expected a %s after '%s %s', found %s" % (
            "number" if field == "amount" else "date", field, op, _show(tok)))
    text = tok[1]
    if field == "amount":
        m = _AMOUNT_RE.fullmatch(text)
        if not m:
            raise _Bad("invalid amount '%s'" % text)
        number, code = m.groups()
        if code:
            if not re.fullmatch(r"[A-Z]{3}", code):
                raise _Bad("invalid amount '%s': the currency code must be three upper-case letters" % text)
            if not is_currency(code):
                raise _Bad("invalid amount '%s': unknown currency %s" % (text, code))
        return _Cond(field, op, Fraction(number), code=code or None), pos + 1
    try:
        value = parse_date(text)
    except DateError:
        raise _Bad("invalid date '%s': expected a real YYYY-MM-DD date" % text)
    return _Cond(field, op, value), pos + 1


def _parse_line(text, lineno):
    tokens = _tokenize(text)
    if not tokens or tokens[0] != (_WORD, "when"):
        raise _Bad("a rule starts with 'when'")
    pos = 1
    conditions = []
    if pos < len(tokens) and tokens[pos] == (_WORD, "any"):
        pos += 1
        tok = tokens[pos] if pos < len(tokens) else None
        if tok != (_WORD, "then"):
            if tok == (_WORD, "and"):
                raise _Bad("'any' cannot be combined with other conditions")
            if tok is None:
                raise _Bad("missing 'then'")
            raise _Bad("expected 'then' after 'any', found %s" % _show(tok))
    else:
        while True:
            cond, pos = _parse_condition(tokens, pos)
            conditions.append(cond)
            tok = tokens[pos] if pos < len(tokens) else None
            if tok == (_WORD, "and"):
                pos += 1
                if pos < len(tokens) and tokens[pos] == (_WORD, "any"):
                    raise _Bad("'any' cannot be combined with other conditions")
                continue
            if tok == (_WORD, "then"):
                break
            if tok is None:
                raise _Bad("missing 'then'")
            raise _Bad("expected 'and' or 'then', found %s" % _show(tok))
    pos += 1  # past "then"
    if pos >= len(tokens):
        raise _Bad("nothing after 'then'")
    account = narration = payee = flag = None
    tags = []
    seen = set()
    while pos < len(tokens):
        tok = tokens[pos]
        if tok[0] != _WORD or tok[1] not in _ACTIONS:
            if tok[0] == _WORD and tok[1].isalpha() and tok[1].islower():
                raise _Bad("unknown action %s" % _show(tok))
            raise _Bad("expected an action, found %s" % _show(tok))
        name = tok[1]
        if name != "tag":
            if name in seen:
                raise _Bad("'%s' given twice" % name)
            seen.add(name)
        pos += 1
        val = tokens[pos] if pos < len(tokens) else None
        if val is None:
            raise _Bad("missing value after '%s'" % name)
        pos += 1
        if name in ("narration", "payee"):
            if val[0] != _STR:
                raise _Bad("expected a quoted text after '%s', found %s" % (name, _show(val)))
            if name == "narration":
                narration = val[1]
            else:
                if not val[1].strip():
                    raise _Bad("the payee cannot be empty")
                payee = val[1]
            continue
        if val[0] != _WORD:
            raise _Bad("expected a value after '%s', found %s" % (name, _show(val)))
        word = val[1]
        if name == "account":
            if not valid_any_root_path(word):
                raise _Bad("invalid account path '%s'" % word)
            account = word
        elif name == "tag":
            if not _TAG_RE.fullmatch(word):
                raise _Bad("invalid tag name '%s'" % word)
            low = word.lower()
            if low not in tags:
                tags.append(low)
        else:
            if word not in ("*", "!"):
                raise _Bad("invalid flag '%s': expected * or !" % word)
            flag = word
    return Rule(lineno, conditions, account=account, tags=tags, narration=narration, payee=payee,
                flag=flag, text=text.strip())


def parse_rules(text):
    """Read a rules file into a RuleSet (RulesError on the first bad rule)."""
    if not isinstance(text, str):
        raise RulesError("rules must be text, got %r" % (text,), line=None)
    if text.startswith("﻿"):
        text = text[1:]
    rules = []
    if text == "":
        return RuleSet(rules)
    for lineno, line in enumerate(_LINE_SPLIT_RE.split(text), 1):
        stripped = line.strip(" \t")
        if not stripped or stripped.startswith("#"):
            continue
        try:
            rules.append(_parse_line(line, lineno))
        except _Bad as e:
            raise RulesError("line %d: %s" % (lineno, e), line=lineno) from None
    return RuleSet(rules)


class RuleSet:
    """Rules in file order; the first one whose conditions all hold wins."""

    def __init__(self, rules=()):
        self._rules = list(rules)

    def __len__(self):
        return len(self._rules)

    def __iter__(self):
        return iter(list(self._rules))

    def __repr__(self):
        return "RuleSet(%d rules)" % len(self._rules)

    def match(self, fields):
        for rule in self._rules:
            if rule.matches(fields):
                return rule
        return None

    def apply(self, fields):
        rule = self.match(fields)
        if rule is None:
            return None
        return rule.actions()

    def categorize(self, tx):
        postings = list(tx.postings or [])
        fields = {
            "payee": tx.payee,
            "narration": tx.narration,
            "date": tx.date,
            "amount": postings[0].amount if postings else None,
        }
        rule = self.match(fields)
        if rule is None:
            return tx
        changes = {"tags": tuple(sorted(set(tx.tags or ()) | set(rule.tags)))}
        if rule.payee is not None:
            changes["payee"] = rule.payee
        if rule.narration is not None:
            changes["narration"] = rule.narration
        if rule.flag is not None:
            changes["flag"] = rule.flag
        if rule.account is not None and len(postings) == 2:
            postings[1] = dataclasses.replace(postings[1], account=rule.account)
        changes["postings"] = postings
        return dataclasses.replace(tx, **changes)

"""Recurring transactions: schedules in words and dated copies of a template."""

import datetime
import re

from tallybook.dates import DateError, add_months, last_day, parse_date
from tallybook.errors import ValidationError, is_int
from tallybook.model import Transaction

__all__ = ["Schedule", "Recurring", "RecurringError", "parse_schedule", "occurrences", "expand",
           "instantiate", "next_occurrence", "describe"]


class RecurringError(ValidationError):
    """A malformed schedule or recurring item."""


SHAPES = ("daily, weekly on DAY (mon..sun), monthly on N (1-31), monthly on last, yearly on MM-DD, "
          "every N days|weeks|months|years from YYYY-MM-DD")

_WEEKDAYS = ("mon", "tue", "wed", "thu", "fri", "sat", "sun")
_WEEKDAY_NAMES = ("Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday")
_MONTH_NAMES = ("January", "February", "March", "April", "May", "June", "July", "August", "September",
                "October", "November", "December")
_UNITS = {"day": "day", "days": "day", "week": "week", "weeks": "week",
          "month": "month", "months": "month", "year": "year", "years": "year"}
_NAME_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]*")
_MIN_ORD = datetime.date.min.toordinal()
_MAX_ORD = datetime.date.max.toordinal()


def _is_date(value):
    return isinstance(value, datetime.date) and not isinstance(value, datetime.datetime)


def _ceil_div(a, b):
    return -((-a) // b)


class Schedule:
    """A rhythm of dates. Build one with parse_schedule.

    kind is one of daily, weekly (value: weekday 0-6), monthly (value: 1-31 or "last"),
    yearly (value: (month, day)), every (value: (n, unit, from_date)).
    """

    __slots__ = ("_kind", "_value")

    def __init__(self, kind, value=None):
        object.__setattr__(self, "_kind", kind)
        object.__setattr__(self, "_value", value)

    kind = property(lambda self: self._kind)
    value = property(lambda self: self._value)

    def __setattr__(self, name, value):
        raise AttributeError("Schedule is immutable")

    def __delattr__(self, name):
        raise AttributeError("Schedule is immutable")

    def __reduce__(self):
        return (parse_schedule, (str(self),))

    def __eq__(self, other):
        if not isinstance(other, Schedule):
            return NotImplemented
        return self._kind == other._kind and self._value == other._value

    def __ne__(self, other):
        r = self.__eq__(other)
        return r if r is NotImplemented else not r

    def __hash__(self):
        return hash((self._kind, self._value))

    def __str__(self):
        k, v = self._kind, self._value
        if k == "daily":
            return "daily"
        if k == "weekly":
            return "weekly on %s" % _WEEKDAYS[v]
        if k == "monthly":
            return "monthly on %s" % v
        if k == "yearly":
            return "yearly on %02d-%02d" % v
        n, unit, frm = v
        return "every %d %s from %s" % (n, unit if n == 1 else unit + "s", frm.isoformat())

    def __repr__(self):
        return "Schedule(%r)" % str(self)

    # ------------------------------------------------------------ index model
    # The schedule's dates are indexed by integers k, ascending in k. _date(k)
    # returns the k-th date or None when it is outside the date range;
    # _index_ge(d) returns the smallest index whose date is >= d.

    def _date(self, k):
        kd, v = self._kind, self._value
        try:
            if kd == "daily":
                if not _MIN_ORD <= k <= _MAX_ORD:
                    return None
                return datetime.date.fromordinal(k)
            if kd == "weekly":
                o = 7 * k + 1 + v
                if not _MIN_ORD <= o <= _MAX_ORD:
                    return None
                return datetime.date.fromordinal(o)
            if kd == "monthly":
                y, m = divmod(k, 12)
                m += 1
                if not 1 <= y <= 9999:
                    return None
                ld = last_day(y, m)
                return datetime.date(y, m, ld if v == "last" else min(v, ld))
            if kd == "yearly":
                if not 1 <= k <= 9999:
                    return None
                mo, dd = v
                return datetime.date(k, mo, min(dd, last_day(k, mo)))
            n, unit, frm = v
            if k < 0:
                return None
            if unit in ("day", "week"):
                o = frm.toordinal() + k * n * (7 if unit == "week" else 1)
                if o > _MAX_ORD:
                    return None
                return datetime.date.fromordinal(o)
            months = k * n * (12 if unit == "year" else 1)
            if frm.year * 12 + frm.month - 1 + months > 9999 * 12 + 11:
                return None
            return add_months(frm, months)
        except (OverflowError, ValueError, DateError):
            return None

    def _index_ge(self, d):
        kd, v = self._kind, self._value
        if kd == "daily":
            return d.toordinal()
        if kd == "weekly":
            return _ceil_div(d.toordinal() - 1 - v, 7)
        if kd == "monthly":
            k = d.year * 12 + d.month - 1
        elif kd == "yearly":
            k = d.year
        else:
            n, unit, frm = v
            if d <= frm:
                return 0
            if unit in ("day", "week"):
                step = n * (7 if unit == "week" else 1)
                return _ceil_div(d.toordinal() - frm.toordinal(), step)
            step = n * (12 if unit == "year" else 1)
            diff = (d.year * 12 + d.month) - (frm.year * 12 + frm.month)
            k = max(0, diff // step)
            while k > 0:
                prev = self._date(k - 1)
                if prev is None or prev < d:
                    break
                k -= 1
        # Step forward while the k-th date is before d (at most a couple of times).
        while True:
            x = self._date(k)
            if x is None or x >= d:
                return k
            k += 1

    def _iter(self, lo, hi=None, kmax=None):
        """Dates of the schedule from index lo on, up to date hi and index kmax."""
        k = lo
        while kmax is None or k <= kmax:
            x = self._date(k)
            if x is None or (hi is not None and x > hi):
                return
            yield x
            k += 1

    def between(self, start, end):
        if not _is_date(start) or not _is_date(end):
            raise RecurringError("between needs two dates, got %r and %r" % (start, end))
        if end < start:
            return []
        return list(self._iter(self._index_ge(start), end))


def _bad(text):
    shown = "'%s'" % text if isinstance(text, str) else repr(text)
    return RecurringError("invalid schedule %s: expected one of %s" % (shown, SHAPES))


def parse_schedule(text):
    if isinstance(text, Schedule):
        return text
    if not isinstance(text, str):
        raise _bad(text)
    words = text.lower().split()
    if words == ["daily"]:
        return Schedule("daily")
    if len(words) == 3 and words[1] == "on":
        kind, _, arg = words
        if kind == "weekly" and arg in _WEEKDAYS:
            return Schedule("weekly", _WEEKDAYS.index(arg))
        if kind == "monthly":
            if arg == "last":
                return Schedule("monthly", "last")
            if re.fullmatch(r"[0-9]{1,2}", arg) and 1 <= int(arg) <= 31:
                return Schedule("monthly", int(arg))
        if kind == "yearly":
            m = re.fullmatch(r"([0-9]{2})-([0-9]{2})", arg)
            if m:
                mo, dd = int(m.group(1)), int(m.group(2))
                if 1 <= mo <= 12 and 1 <= dd <= last_day(2024, mo):
                    return Schedule("yearly", (mo, dd))
    if len(words) == 5 and words[0] == "every" and words[3] == "from":
        n, unit, frm = words[1], words[2], words[4]
        if re.fullmatch(r"[0-9]+", n) and int(n) >= 1 and unit in _UNITS:
            try:
                d = parse_date(frm)
            except DateError:
                d = None
            if d is not None:
                return Schedule("every", (int(n), _UNITS[unit], d))
    raise _bad(text)


def _ordinal(n):
    if 10 <= n % 100 <= 20:
        suffix = "th"
    else:
        suffix = {1: "st", 2: "nd", 3: "rd"}.get(n % 10, "th")
    return "%d%s" % (n, suffix)


def describe(schedule):
    s = parse_schedule(schedule)
    k, v = s.kind, s.value
    if k == "daily":
        return "every day"
    if k == "weekly":
        return "every %s" % _WEEKDAY_NAMES[v]
    if k == "monthly":
        if v == "last":
            return "on the last day of every month"
        return "on the %s of every month" % _ordinal(v)
    if k == "yearly":
        return "every year on %d %s" % (v[1], _MONTH_NAMES[v[0] - 1])
    n, unit, frm = v
    if n == 1:
        return "every %s from %s" % (unit, frm.isoformat())
    return "every %d %ss from %s" % (n, unit, frm.isoformat())


class Recurring:
    __slots__ = ("_name", "_schedule", "_template", "_start", "_end", "_count")

    def __init__(self, name, schedule, template, start, end=None, count=None):
        if not isinstance(name, str) or not _NAME_RE.fullmatch(name):
            raise RecurringError("invalid recurring name %s: use ASCII letters, digits, '-' and '_', "
                                 "not starting with '-' or '_'"
                                 % ("'%s'" % name if isinstance(name, str) else repr(name)))
        if isinstance(schedule, str):
            schedule = parse_schedule(schedule)
        elif not isinstance(schedule, Schedule):
            raise RecurringError("invalid schedule %r: expected a Schedule or text" % (schedule,))
        if not isinstance(template, Transaction):
            raise RecurringError("invalid template %r: expected a Transaction" % (template,))
        if not _is_date(start):
            raise RecurringError("invalid start %r: expected a date" % (start,))
        if end is not None:
            if not _is_date(end):
                raise RecurringError("invalid end %r: expected a date" % (end,))
            if end < start:
                raise RecurringError("end %s is before start %s" % (end.isoformat(), start.isoformat()))
        if count is not None and (not is_int(count) or count < 1):
            raise RecurringError("invalid count %r: expected a whole number of at least 1" % (count,))
        object.__setattr__(self, "_name", name)
        object.__setattr__(self, "_schedule", schedule)
        object.__setattr__(self, "_template", template)
        object.__setattr__(self, "_start", start)
        object.__setattr__(self, "_end", end)
        object.__setattr__(self, "_count", count)

    name = property(lambda self: self._name)
    schedule = property(lambda self: self._schedule)
    template = property(lambda self: self._template)
    start = property(lambda self: self._start)
    end = property(lambda self: self._end)
    count = property(lambda self: self._count)

    def __setattr__(self, name, value):
        raise AttributeError("Recurring is immutable")

    def __delattr__(self, name):
        raise AttributeError("Recurring is immutable")

    def _key(self):
        return (self._name, self._schedule, self._template, self._start, self._end, self._count)

    def __reduce__(self):
        return (Recurring, self._key())

    def __eq__(self, other):
        if not isinstance(other, Recurring):
            return NotImplemented
        return self._key() == other._key()

    def __ne__(self, other):
        r = self.__eq__(other)
        return r if r is NotImplemented else not r

    __hash__ = None  # the template is a mutable Transaction

    def __repr__(self):
        return "Recurring(%r, %r, %r, start=%r, end=%r, count=%r)" % (
            self._name, str(self._schedule), self._template, self._start, self._end, self._count)


def _check_rec(rec):
    if not isinstance(rec, Recurring):
        raise RecurringError("not a recurring item: %r" % (rec,))


def _series(rec, lo_date, hi_date):
    """Dates of rec's series that are >= lo_date and <= hi_date (hi_date may be None)."""
    s = rec.schedule
    if rec.end is not None and (hi_date is None or rec.end < hi_date):
        hi_date = rec.end
    kmax = None
    if rec.count is not None:
        kmax = s._index_ge(rec.start) + rec.count - 1
    lo = s._index_ge(max(lo_date, rec.start))
    return s._iter(lo, hi_date, kmax)


def occurrences(rec, start, end):
    _check_rec(rec)
    if not _is_date(start) or not _is_date(end):
        raise RecurringError("occurrences needs two dates, got %r and %r" % (start, end))
    if end < start:
        return []
    return list(_series(rec, start, end))


def next_occurrence(rec, after):
    _check_rec(rec)
    if not _is_date(after):
        raise RecurringError("invalid date %r" % (after,))
    if after >= datetime.date.max:
        return None
    for d in _series(rec, after + datetime.timedelta(days=1), None):
        return d
    return None


def instantiate(rec, on):
    _check_rec(rec)
    if not _is_date(on):
        raise RecurringError("invalid date %r" % (on,))
    t = rec.template
    tags = tuple(sorted(set(tuple(t.tags) + ("recurring",))))
    return Transaction(on, t.payee, t.narration, list(t.postings), tags, t.flag, None)


def expand(recs, start, end):
    if isinstance(recs, (str, bytes)):
        raise RecurringError("expand needs a list of Recurring")
    recs = list(recs)
    for r in recs:
        _check_rec(r)
    if not _is_date(start) or not _is_date(end):
        raise RecurringError("expand needs two dates, got %r and %r" % (start, end))
    items = []
    for i, r in enumerate(recs):
        for d in occurrences(r, start, end):
            items.append((d, r.name, i))
    items.sort()
    return [instantiate(recs[i], d) for d, _, i in items]

"""The journal file: a whole book as one readable text file."""

import re
from dataclasses import dataclass, field
from typing import List

from tallybook.accounts import account_type, valid_path
from tallybook.currency import CurrencyError, is_currency, parse_rate_text
from tallybook.dates import DateError, format_date, parse_date
from tallybook.errors import ParseError, TallybookError
from tallybook.ledger import Ledger
from tallybook.model import Account, Posting, Transaction
from tallybook.money import Money, parse_amount

__all__ = ["Journal", "JournalError", "parse_journal", "format_journal", "format_transaction"]

_TAG_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]*")
_BLANKS = " \t"


class JournalError(ParseError):
    """A mistake in the writing of a journal file; `.line` is its 1-based line number."""

    def __init__(self, line, description="", **detail):
        if isinstance(line, str) and not description:
            # JournalError("line 3: ...") form, for completeness
            m = re.match(r"line ([0-9]+): ", line)
            message, line = line, (int(m.group(1)) if m else None)
        else:
            message = "line %d: %s" % (line, description)
        super().__init__(message, **detail)
        self.line = line


@dataclass
class Journal:
    accounts: List[Account] = field(default_factory=list)
    rates: list = field(default_factory=list)
    transactions: List[Transaction] = field(default_factory=list)

    def __post_init__(self):
        self.accounts = list(self.accounts)
        self.rates = list(self.rates)
        self.transactions = list(self.transactions)

    def to_ledger(self):
        ledger = Ledger()
        for acc in self.accounts:
            ledger.chart.add(acc.path, type=acc.type, currency=acc.currency, opened=acc.opened, note=acc.note)
            if acc.closed is not None:
                ledger.chart.close(acc.path, acc.closed)
        for src, dst, on, rate_text in self.rates:
            ledger.rates.set(src, dst, rate_text, on)
        for tx in self.transactions:
            ledger.add(tx)
        return ledger


# ---------------------------------------------------------------------- reading


class _Mistake(Exception):
    pass


def _tokenize(line):
    """Split a line into ("bare"|"quoted", text) items and the comment text after `;` (or None)."""
    items = []
    comment = None
    i, n = 0, len(line)
    while i < n:
        c = line[i]
        if c in _BLANKS:
            i += 1
            continue
        if c == ";":
            comment = line[i + 1:]
            break
        if c == '"':
            j = i + 1
            buf = []
            while True:
                if j >= n:
                    raise _Mistake("missing closing quote")
                ch = line[j]
                if ch == "\\":
                    if j + 1 < n and line[j + 1] in '"\\':
                        buf.append(line[j + 1])
                        j += 2
                        continue
                    raise _Mistake("invalid backslash in quoted text")
                if ch == '"':
                    break
                buf.append(ch)
                j += 1
            j += 1
            if j < n and line[j] not in _BLANKS and line[j] != ";":
                raise _Mistake("unexpected text after closing quote")
            items.append(("quoted", "".join(buf)))
            i = j
            continue
        j = i
        while j < n and line[j] not in _BLANKS and line[j] != ";":
            j += 1
        items.append(("bare", line[i:j]))
        i = j
    return items, comment


def _date(text):
    try:
        return parse_date(text)
    except DateError:
        raise _Mistake("invalid date '%s'" % text) from None


def _bare(item, what):
    kind, text = item
    if kind != "bare":
        raise _Mistake("unexpected quoted text, expected %s" % what)
    return text


def _parse_account(items):
    # items[0] is "account"
    if len(items) < 2:
        raise _Mistake("missing account path")
    path = _bare(items[1], "an account path")
    if not valid_path(path):
        raise _Mistake("invalid account path '%s'" % path)
    rest = items[2:]
    cur = opened = closed = None
    note = ""
    k = 0
    if k < len(rest) and rest[k][0] == "bare" and rest[k][1] not in ("open", "close"):
        cur = rest[k][1]
        if not is_currency(cur):
            raise _Mistake("unknown currency '%s'" % cur)
        k += 1
    for word in ("open", "close"):
        if k < len(rest) and rest[k] == ("bare", word):
            if k + 1 >= len(rest):
                raise _Mistake("missing date after %s" % word)
            d = _date(_bare(rest[k + 1], "a date"))
            if word == "open":
                opened = d
            else:
                closed = d
            k += 2
    if k < len(rest) and rest[k][0] == "quoted":
        note = rest[k][1]
        k += 1
    if k < len(rest):
        raise _Mistake("unexpected '%s'" % rest[k][1])
    if opened is not None and closed is not None and closed < opened:
        raise _Mistake("account %s is closed before it is opened" % path)
    return Account(path, account_type(path), cur, opened, closed, note)


def _parse_rate(items):
    words = [_bare(it, "a rate part") for it in items[1:]]
    if len(words) != 4:
        raise _Mistake("expected 'rate DATE FROM TO RATE'")
    d = _date(words[0])
    src, dst, text = words[1], words[2], words[3]
    for code in (src, dst):
        if not is_currency(code):
            raise _Mistake("unknown currency '%s'" % code)
    if src == dst:
        raise _Mistake("a rate needs two different currencies")
    try:
        parse_rate_text(text)
    except CurrencyError:
        raise _Mistake("invalid rate '%s'" % text) from None
    return (src, dst, d, text)


def _parse_tx_line(items):
    d = _date(items[0][1])
    k = 1
    flag = "*"
    if k < len(items) and items[k][0] == "bare" and items[k][1] in ("*", "!"):
        flag = items[k][1]
        k += 1
    strings = []
    while k < len(items) and items[k][0] == "quoted":
        strings.append(items[k][1])
        k += 1
    if not strings:
        raise _Mistake("missing payee")
    if len(strings) > 2:
        raise _Mistake("too many quoted strings")
    tags = set()
    while k < len(items):
        kind, text = items[k]
        if kind != "bare" or not text.startswith("#") or not _TAG_RE.fullmatch(text[1:]):
            raise _Mistake("unexpected '%s'" % text)
        tags.add(text[1:])
        k += 1
    payee = strings[0]
    narration = strings[1] if len(strings) > 1 else ""
    return Transaction(d, payee, narration, [], tuple(sorted(tags)), flag, None)


def _parse_posting(items, comment):
    words = [_bare(it, "a posting part") for it in items]
    note = comment.strip(" \t") if comment is not None else ""
    if not words:
        raise _Mistake("missing account")
    path = words[0]
    if not valid_path(path):
        raise _Mistake("invalid account path '%s'" % path)
    if len(words) == 1:
        return Posting(path, None, note)
    if len(words) == 2:
        raise _Mistake("missing currency after amount")
    if len(words) > 3:
        raise _Mistake("unexpected '%s'" % words[3])
    amount, code = words[1], words[2]
    if not is_currency(code):
        raise _Mistake("unknown currency '%s'" % code)
    try:
        minor = parse_amount(amount, code)
    except TallybookError as e:
        raise _Mistake(e.message) from None
    return Posting(path, Money(minor, code), note)


def parse_journal(text):
    if not isinstance(text, str):
        raise JournalError(1, "expected text, got %r" % (text,))
    if text.startswith("﻿"):
        text = text[1:]
    lines = text.split("\n")
    if lines and lines[-1] == "":
        lines.pop()
    journal = Journal()
    declared = set()
    current = None  # the Transaction whose postings are being read
    for number, line in enumerate(lines, 1):
        if line.endswith("\r"):
            line = line[:-1]
        try:
            stripped = line.lstrip(_BLANKS)
            if not stripped:
                current = None
                continue
            if stripped[0] in ";#":
                continue
            items, comment = _tokenize(line)
            if line[0] in _BLANKS:
                if current is None:
                    raise _Mistake("indented line outside a transaction")
                current.postings.append(_parse_posting(items, comment))
                continue
            current = None
            head = items[0] if items else ("bare", "")
            if head == ("bare", "account"):
                acc = _parse_account(items)
                if acc.path in declared:
                    raise _Mistake("account %s is declared twice" % acc.path)
                declared.add(acc.path)
                journal.accounts.append(acc)
            elif head == ("bare", "rate"):
                journal.rates.append(_parse_rate(items))
            elif head[0] == "bare" and head[1][:1].isdigit():
                current = _parse_tx_line(items)
                journal.transactions.append(current)
            else:
                raise _Mistake("unexpected '%s'" % head[1])
        except _Mistake as e:
            raise JournalError(number, str(e)) from None
    return journal


# ---------------------------------------------------------------------- writing


def _quote(text):
    return '"' + text.replace("\\", "\\\\").replace('"', '\\"') + '"'


def _account_line(acc):
    parts = ["account", acc.path]
    if acc.currency is not None:
        parts.append(acc.currency)
    if acc.opened is not None:
        parts += ["open", format_date(acc.opened)]
    if acc.closed is not None:
        parts += ["close", format_date(acc.closed)]
    if acc.note:
        parts.append(_quote(acc.note))
    return " ".join(parts)


def _rate_line(rate):
    src, dst, on, text = rate
    return "rate %s %s %s %s" % (format_date(on), src, dst, text)


def format_transaction(tx):
    head = "%s %s %s" % (format_date(tx.date), tx.flag, _quote(tx.payee))
    if tx.narration:
        head += " " + _quote(tx.narration)
    for tag in sorted(set(tx.tags)):
        head += " #" + tag
    lines = [head]
    with_amount = [p for p in tx.postings if p.amount is not None]
    acc_width = max((len(p.account) for p in with_amount), default=0)
    amt_width = max((len(p.amount.amount_str()) for p in with_amount), default=0)
    for p in tx.postings:
        if p.amount is None:
            line = "  " + p.account
        else:
            line = "  %s  %s %s" % (p.account.ljust(acc_width), p.amount.amount_str().rjust(amt_width),
                                    p.amount.currency)
        if p.note:
            line += "  ; " + p.note
        lines.append(line)
    return "\n".join(lines) + "\n"


def format_journal(journal):
    groups = []
    if journal.accounts:
        groups.append("".join(_account_line(a) + "\n" for a in journal.accounts))
    if journal.rates:
        groups.append("".join(_rate_line(r) + "\n" for r in journal.rates))
    if journal.transactions:
        groups.append("\n".join(format_transaction(t) for t in journal.transactions))
    return "\n".join(groups)

"""The query language for finding transactions."""

import operator
import re
from fractions import Fraction

from tallybook.currency import is_currency
from tallybook.dates import DateError, Period, parse_date
from tallybook.errors import ParseError

__all__ = ["parse_query", "select", "Query", "QueryError"]


class QueryError(ParseError):
    """A query that cannot be understood; `.position` is the 1-based place of the mistake."""

    def __init__(self, description, position, **detail):
        super().__init__("%s at position %d" % (description, position), **detail)
        self.position = position


_SPACES = " \t"
_STOP = " \t()"
_NAME_RE = re.compile(r"[A-Za-z][A-Za-z0-9_-]*")
_OP_RE = re.compile(r"<=|>=|!=|<|>|=")
_PART_RE = re.compile(r"[A-Za-z0-9_-]+")
_AMOUNT_RE = re.compile(r"([+-]?[0-9]+(?:\.[0-9]+)?)([A-Za-z]*)")
_NAMES = ("payee", "narration", "tag", "date", "flag", "id", "account")
_COMPARABLE = ("date", "amount")
_KEYWORDS = ("and", "or", "not")
_OPS = {
    "<": operator.lt,
    "<=": operator.le,
    ">": operator.gt,
    ">=": operator.ge,
    "=": operator.eq,
    "!=": operator.ne,
}


# ------------------------------------------------------------------ the tree


class _Node:
    on_posting = False

    def eval(self, tx, posting):  # pragma: no cover - overridden
        raise NotImplementedError


class _And(_Node):
    def __init__(self, left, right):
        self.left, self.right = left, right

    def eval(self, tx, posting):
        return self.left.eval(tx, posting) and self.right.eval(tx, posting)


class _Or(_Node):
    def __init__(self, left, right):
        self.left, self.right = left, right

    def eval(self, tx, posting):
        return self.left.eval(tx, posting) or self.right.eval(tx, posting)


class _Not(_Node):
    def __init__(self, inner):
        self.inner = inner

    def eval(self, tx, posting):
        return not self.inner.eval(tx, posting)


class _Contains(_Node):
    def __init__(self, fields, text):
        self.fields = fields
        self.text = text.lower()

    def eval(self, tx, posting):
        for f in self.fields:
            value = getattr(tx, f, None)
            if isinstance(value, str) and self.text in value.lower():
                return True
        return False


class _Tag(_Node):
    def __init__(self, name):
        self.name = name.lower()

    def eval(self, tx, posting):
        return any(isinstance(t, str) and t.lower() == self.name for t in (tx.tags or ()))


class _InPeriod(_Node):
    def __init__(self, period):
        self.period = period

    def eval(self, tx, posting):
        return self.period.start <= tx.date <= self.period.end


class _DateCmp(_Node):
    def __init__(self, op, date):
        self.op, self.date = _OPS[op], date

    def eval(self, tx, posting):
        return self.op(tx.date, self.date)


class _Flag(_Node):
    def __init__(self, flag):
        self.flag = flag

    def eval(self, tx, posting):
        return tx.flag == self.flag


class _Id(_Node):
    def __init__(self, value):
        self.value = value

    def eval(self, tx, posting):
        return tx.id is not None and not isinstance(tx.id, bool) and tx.id == self.value


class _Account(_Node):
    def __init__(self, parts):
        self.parts = parts

    def eval(self, tx, posting):
        return isinstance(posting.account, str) and _pattern_matches(self.parts, posting.account)


class _AmountCmp(_Node):
    def __init__(self, op, value, code):
        self.op, self.value, self.code = _OPS[op], value, code

    def eval(self, tx, posting):
        m = posting.amount
        if m is None:
            return False
        if self.code is not None and m.currency != self.code:
            return False
        return self.op(Fraction(m.minor, 10 ** m.exponent), self.value)


def _pattern_matches(parts, path):
    """Does the pattern name the account (or an account above it)?"""
    segs = path.split(":")

    def match(i, j):
        if i == len(parts):
            return True  # the account may go on below
        p = parts[i]
        if p == "**":
            return any(match(i + 1, k) for k in range(j, len(segs) + 1))
        if j >= len(segs):
            return False
        if p == "*" or p == segs[j]:
            return match(i + 1, j + 1)
        return False

    return match(0, 0)


def _compile_pattern(text):
    parts = text.split(":")
    for p in parts:
        if p in ("*", "**"):
            continue
        if not _PART_RE.fullmatch(p):
            return None
    return parts


# ----------------------------------------------------------------- the lexer


class _Token:
    __slots__ = ("kind", "pos", "node", "error")

    def __init__(self, kind, pos, node=None, error=None):
        self.kind = kind  # "term", "and", "or", "not", "(", ")", "end", "error"
        self.pos = pos
        self.node = node
        self.error = error


def _read_quoted(text, i):
    """Read a quoted string whose opening quote is at index i; return (value, index after it)."""
    n = len(text)
    j = i + 1
    buf = []
    while True:
        if j >= n:
            raise QueryError("unterminated quote", i + 1)
        c = text[j]
        if c == "\\" and j + 1 < n and text[j + 1] in '"\\':
            buf.append(text[j + 1])
            j += 2
            continue
        if c == '"':
            break
        buf.append(c)
        j += 1
    j += 1
    if j < n and text[j] not in _STOP:
        raise QueryError("unexpected text after closing quote", j + 1)
    return "".join(buf), j


def _read_bare(text, i):
    j = i
    while j < len(text) and text[j] not in _STOP:
        j += 1
    return text[i:j], j


def _make_term(name, value, quoted, start, chart, op=None):
    """Build the node for one term; `start` is the 1-based position of the term."""
    def bad(what):
        return QueryError("%s in '%s'" % (what, term_text), start)

    term_text = "%s%s%s" % (name, op or ":", value)
    if value == "":
        if quoted:
            raise bad("empty quotes")
        raise bad("missing value")
    if op is None:
        if name in ("payee", "narration"):
            return _Contains((name,), value)
        if name == "tag":
            return _Tag(value)
        if name == "date":
            try:
                return _InPeriod(Period.parse(value))
            except DateError:
                raise bad("invalid period") from None
        if name == "flag":
            if value not in ("*", "!"):
                raise bad("invalid flag, expected * or !")
            return _Flag(value)
        if name == "id":
            if not re.fullmatch(r"[0-9]+", value):
                raise bad("invalid id, expected digits")
            return _Id(int(value))
        if name == "account":
            parts = _compile_pattern(value)
            if parts is None:
                raise bad("invalid account pattern")
            if chart is not None and not any(_pattern_matches(parts, a.path) for a in chart.accounts()):
                raise QueryError("no account matches '%s'" % term_text, start)
            return _Account(parts)
        raise AssertionError(name)  # pragma: no cover
    if name == "date":
        try:
            return _DateCmp(op, parse_date(value))
        except DateError:
            raise bad("invalid date") from None
    # amount
    m = _AMOUNT_RE.fullmatch(value) if not quoted else None
    if m is None:
        raise bad("invalid amount")
    number, code = m.groups()
    if code:
        if not re.fullmatch(r"[A-Z]{3}", code) or not is_currency(code):
            raise bad("invalid currency")
    return _AmountCmp(op, Fraction(number), code or None)


def _lex(text, chart):
    """The tokens of the query; a mistake becomes an "error" token where it stands."""
    tokens = []
    i, n = 0, len(text)
    try:
        while i < n:
            c = text[i]
            if c in _SPACES:
                i += 1
                continue
            start = i + 1
            if c in "()":
                tokens.append(_Token(c, start))
                i += 1
                continue
            if c == '"':
                value, i = _read_quoted(text, i)
                if value == "":
                    raise QueryError("empty quotes", start)
                tokens.append(_Token("term", start, _Contains(("payee", "narration"), value)))
                continue
            m = _NAME_RE.match(text, i)
            if m:
                name = m.group(0).lower()
                j = m.end()
                if j < n and text[j] == ":":
                    if name not in _NAMES:
                        raise QueryError("unknown name '%s'" % m.group(0), start)
                    j += 1
                    if j < n and text[j] == '"':
                        value, i = _read_quoted(text, j)
                        quoted = True
                    else:
                        value, i = _read_bare(text, j)
                        quoted = False
                    tokens.append(_Token("term", start, _make_term(name, value, quoted, start, chart)))
                    continue
                if name in _COMPARABLE:
                    k = j
                    while k < n and text[k] in _SPACES:
                        k += 1
                    om = _OP_RE.match(text, k)
                    if om:
                        k = om.end()
                        while k < n and text[k] in _SPACES:
                            k += 1
                        value, i = _read_bare(text, k)
                        tokens.append(_Token("term", start,
                                             _make_term(name, value, False, start, chart, om.group(0))))
                        continue
            word, i = _read_bare(text, i)
            if word.lower() in _KEYWORDS:
                tokens.append(_Token(word.lower(), start))
            else:
                tokens.append(_Token("term", start, _Contains(("payee", "narration"), word)))
    except QueryError as e:
        tokens.append(_Token("error", e.position, error=e))
        return tokens
    tokens.append(_Token("end", n + 1))
    return tokens


# ---------------------------------------------------------------- the parser


class _Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.i = 0

    def peek(self):
        tok = self.tokens[self.i]
        if tok.kind == "error":
            raise tok.error
        return tok

    def take(self):
        tok = self.peek()
        self.i += 1
        return tok

    def parse(self):
        node = self.parse_or()
        tok = self.peek()
        if tok.kind == ")":
            raise QueryError("')' without a matching '('", tok.pos)
        if tok.kind != "end":  # pragma: no cover - cannot happen
            raise QueryError("unexpected text", tok.pos)
        return node

    def parse_or(self):
        node = self.parse_and()
        while self.peek().kind == "or":
            self.take()
            node = _Or(node, self.parse_and())
        return node

    def parse_and(self):
        node = self.parse_not()
        while True:
            kind = self.peek().kind
            if kind == "and":
                self.take()
            elif kind not in ("term", "not", "("):
                return node
            node = _And(node, self.parse_not())

    def parse_not(self):
        if self.peek().kind == "not":
            self.take()
            return _Not(self.parse_not())
        return self.parse_primary()

    def parse_primary(self):
        tok = self.take()
        if tok.kind == "term":
            return tok.node
        if tok.kind == "(":
            node = self.parse_or()
            close = self.peek()
            if close.kind != ")":
                raise QueryError("'(' is never closed", tok.pos)
            self.take()
            return node
        if tok.kind == "end":
            raise QueryError("expected a term but the query ends", tok.pos)
        raise QueryError("expected a term but found '%s'" % tok.kind, tok.pos)


# ----------------------------------------------------------------- the query


class Query:
    """A parsed query; use `parse_query` to make one."""

    def __init__(self, text, chart=None):
        if not isinstance(text, str):
            raise QueryError("a query must be text, got %r" % (text,), 1)
        self.text = text
        tokens = _lex(text, chart)
        if len(tokens) == 1 and tokens[0].kind == "end":
            self._root = None
        else:
            self._root = _Parser(tokens).parse()

    @property
    def is_empty(self):
        return self._root is None

    def __repr__(self):
        return "Query(%r)" % (self.text,)

    def __eq__(self, other):
        return isinstance(other, Query) and other.text == self.text

    def __hash__(self):
        return hash(self.text)

    def matching_postings(self, tx):
        postings = list(tx.postings)
        if self._root is None:
            return postings
        return [p for p in postings if self._root.eval(tx, p)]

    def matches(self, tx):
        if self._root is None:
            return True
        return any(self._root.eval(tx, p) for p in tx.postings)


def parse_query(text, chart=None):
    return Query(text, chart)


def select(transactions, q):
    if not isinstance(q, Query):
        q = parse_query(q)
    return [tx for tx in transactions if q.matches(tx)]

"""Importing bank statements (CSV) through a profile."""

import datetime
import re
from collections import Counter

from tallybook.accounts import valid_any_root_path
from tallybook.currency import currency, is_currency
from tallybook.errors import ParseError
from tallybook.model import Posting, Transaction
from tallybook.money import Money
from tallybook.rules import RuleSet, parse_rules

__all__ = ["parse_profile", "ImportProfile", "import_csv", "ImportResult", "CsvImportError"]


class CsvImportError(ParseError):
    """A bad profile, or a file that cannot be imported at all."""

    def __init__(self, message="", line=None, **detail):
        super().__init__(message, **detail)
        self.line = line


class _Bad(Exception):
    pass


_LINE_SPLIT_RE = re.compile(r"\r\n|\n|\r")
_TAG_RE = re.compile(r"[A-Za-z0-9_-]+")
_COLUMN_SETTINGS = ("date_column", "payee_column", "narration_column", "amount_column", "debit_column",
                    "credit_column")
_SETTINGS = _COLUMN_SETTINGS + ("currency", "account", "default_account", "date_format", "delimiter", "skip_rows",
                                "has_header", "negate", "decimal_separator", "thousands_separator", "flag", "tags")
_REQUIRED = ("date_column", "payee_column", "currency", "account")
_BOOLS = {"yes": True, "true": True, "no": False, "false": False}
_DELIMITER_WORDS = {"comma": ",", "tab": "\t", "semicolon": ";", "pipe": "|", "space": " "}
_THOUSANDS = {"none": "", "comma": ",", "dot": ".", "space": " ", "apostrophe": "'",
              ",": ",", ".": ".", "'": "'", " ": " "}

_MONTHS = ["january", "february", "march", "april", "may", "june", "july", "august", "september", "october",
           "november", "december"]
_MONTH_FULL = {name: i for i, name in enumerate(_MONTHS, 1)}
_MONTH_ABBR = {name[:3]: i for i, name in enumerate(_MONTHS, 1)}


class ImportProfile:
    """How one bank lays out its CSV statements."""

    def __init__(self, date_column=None, payee_column=None, narration_column=None, amount_column=None,
                 debit_column=None, credit_column=None, currency=None, account=None, default_account=None,
                 date_format="%Y-%m-%d", delimiter=",", skip_rows=0, has_header=True, negate=False,
                 decimal_separator=".", thousands_separator="", flag="*", tags=()):
        self.date_column = date_column
        self.payee_column = payee_column
        self.narration_column = narration_column
        self.amount_column = amount_column
        self.debit_column = debit_column
        self.credit_column = credit_column
        self.currency = currency
        self.account = account
        self.default_account = default_account
        self.date_format = date_format
        self.delimiter = delimiter
        self.skip_rows = skip_rows
        self.has_header = has_header
        self.negate = negate
        self.decimal_separator = decimal_separator
        self.thousands_separator = thousands_separator
        self.flag = flag
        self.tags = tuple(tags)

    def _items(self):
        return tuple((name, getattr(self, name)) for name in _SETTINGS)

    def __eq__(self, other):
        return isinstance(other, ImportProfile) and self._items() == other._items()

    def __ne__(self, other):
        return not self.__eq__(other)

    def __repr__(self):
        return "ImportProfile(%s)" % ", ".join("%s=%r" % kv for kv in self._items())


# ---------------------------------------------------------------- date formats

def _compile_date_format(fmt):
    """A regex and a list of group kinds for a date format; _Bad when the format is wrong."""
    parts = []
    kinds = []
    i, n = 0, len(fmt)
    while i < n:
        c = fmt[i]
        if c != "%":
            parts.append(re.escape(c))
            i += 1
            continue
        if i + 1 >= n:
            raise _Bad("invalid date_format '%s': a lone %% at the end" % fmt)
        d = fmt[i + 1]
        i += 2
        if d == "%":
            parts.append("%")
        elif d == "Y":
            parts.append("([0-9]{4})")
            kinds.append("Y")
        elif d == "y":
            parts.append("([0-9]{2})")
            kinds.append("y")
        elif d == "m":
            parts.append("([0-9]{1,2})")
            kinds.append("m")
        elif d == "d":
            parts.append("([0-9]{1,2})")
            kinds.append("d")
        elif d == "b":
            parts.append("([A-Za-z]{3})")
            kinds.append("b")
        elif d == "B":
            parts.append("([A-Za-z]+)")
            kinds.append("B")
        else:
            raise _Bad("invalid date_format '%s': unknown directive %%%s" % (fmt, d))
    years = sum(k in "Yy" for k in kinds)
    months = sum(k in "mbB" for k in kinds)
    days = sum(k == "d" for k in kinds)
    if years != 1 or months != 1 or days != 1:
        raise _Bad("invalid date_format '%s': needs a year, a month and a day, each once" % fmt)
    return re.compile("".join(parts)), kinds


def _parse_date_cell(text, fmt, compiled):
    regex, kinds = compiled
    m = regex.fullmatch(text)
    if m:
        year = month = day = None
        for kind, value in zip(kinds, m.groups()):
            if kind == "Y":
                year = int(value)
            elif kind == "y":
                year = 2000 + int(value)
            elif kind == "m":
                month = int(value)
            elif kind == "d":
                day = int(value)
            elif kind == "b":
                month = _MONTH_ABBR.get(value.lower())
            else:
                month = _MONTH_FULL.get(value.lower())
        if month is not None:
            try:
                return datetime.date(year, month, day)
            except ValueError:
                pass
    raise _Bad("invalid date '%s': expected a real date written %s" % (text, fmt))


# ---------------------------------------------------------------- profile

def _check_column(value, has_header):
    if value == "":
        raise _Bad("empty column")
    if value.startswith("#"):
        digits = value[1:]
        if not digits or not digits.isascii() or not digits.isdigit():
            raise _Bad("invalid column '%s': expected #N, a column number from 1" % value)
        if int(digits) == 0:
            raise _Bad("invalid column '%s': columns are counted from 1" % value)
        return value
    if not has_header:
        raise _Bad("invalid column '%s': with has_header = no only #N columns are allowed" % value)
    return value


def _strip_value(raw):
    value = raw.strip(" ")
    if value != "\t":
        value = value.strip(" \t")
    if len(value) >= 2 and value[0] == '"' and value[-1] == '"':
        value = value[1:-1]
    return value


def parse_profile(text):
    """Read a profile text into an ImportProfile (CsvImportError when it is bad)."""
    if not isinstance(text, str):
        raise CsvImportError("a profile must be text, got %r" % (text,))
    if text.startswith("﻿"):
        text = text[1:]
    lines = []
    for lineno, line in enumerate(_LINE_SPLIT_RE.split(text), 1):
        stripped = line.strip(" \t")
        if not stripped or stripped.startswith("#"):
            continue
        lines.append((lineno, line))

    # has_header may come after the columns: look it up first (a bad value is reported on its own line).
    has_header = True
    for lineno, line in lines:
        if "=" in line:
            name, raw = line.split("=", 1)
            if name.strip(" \t") == "has_header":
                v = _BOOLS.get(_strip_value(raw).lower())
                if v is not None:
                    has_header = v
                break

    values = {}
    for lineno, line in lines:
        try:
            if "=" not in line:
                raise _Bad("expected 'setting = value'")
            name, raw = line.split("=", 1)
            name = name.strip(" \t")
            value = _strip_value(raw)
            if name not in _SETTINGS:
                raise _Bad("unknown setting '%s'" % name)
            if name in values:
                raise _Bad("setting '%s' given twice" % name)
            values[name] = _check_setting(name, value, has_header)
        except _Bad as e:
            raise CsvImportError("line %d: %s" % (lineno, e), line=lineno) from None

    for name in _REQUIRED:
        if name not in values:
            raise CsvImportError("missing required setting '%s'" % name)
    has_amount = "amount_column" in values
    has_debit = "debit_column" in values
    has_credit = "credit_column" in values
    if has_amount and (has_debit or has_credit):
        raise CsvImportError("amount_column cannot be used together with debit_column/credit_column")
    if not has_amount:
        if has_debit != has_credit:
            raise CsvImportError("debit_column and credit_column must be given together")
        if not has_debit:
            raise CsvImportError("missing amount_column (or debit_column and credit_column)")
    profile = ImportProfile(**values)
    if profile.decimal_separator == profile.thousands_separator:
        raise CsvImportError("decimal_separator and thousands_separator cannot be the same")
    return profile


def _check_setting(name, value, has_header):
    if name in _COLUMN_SETTINGS:
        return _check_column(value, has_header)
    if name in ("account", "default_account"):
        if not valid_any_root_path(value):
            raise _Bad("invalid account path '%s'" % value)
        return value
    if name == "currency":
        if not is_currency(value):
            raise _Bad("unknown currency '%s'" % value)
        return value
    if name == "date_format":
        _compile_date_format(value)
        return value
    if name == "delimiter":
        if value in _DELIMITER_WORDS:
            return _DELIMITER_WORDS[value]
        if len(value) != 1 or value in '"\r\n':
            raise _Bad("invalid delimiter '%s'" % value)
        return value
    if name == "skip_rows":
        if not value or not value.isascii() or not value.isdigit():
            raise _Bad("invalid skip_rows '%s': expected a whole number" % value)
        return int(value)
    if name in ("has_header", "negate"):
        v = _BOOLS.get(value.lower())
        if v is None:
            raise _Bad("invalid %s '%s': expected yes, no, true or false" % (name, value))
        return v
    if name == "decimal_separator":
        if value not in (".", ","):
            raise _Bad("invalid decimal_separator '%s': expected . or ," % value)
        return value
    if name == "thousands_separator":
        if value not in _THOUSANDS:
            raise _Bad("invalid thousands_separator '%s'" % value)
        return _THOUSANDS[value]
    if name == "flag":
        if value not in ("*", "!"):
            raise _Bad("invalid flag '%s': expected * or !" % value)
        return value
    # tags
    if not value.strip():
        raise _Bad("tags cannot be empty")
    tags = set()
    for part in value.split(","):
        part = part.strip(" \t")
        if not _TAG_RE.fullmatch(part):
            raise _Bad("invalid tag name '%s'" % part)
        tags.add(part.lower())
    return tuple(sorted(tags))


# ---------------------------------------------------------------- reading CSV

def _skip_lines(text, count):
    """Drop `count` lines (any line ending); returns (rest, number of lines dropped)."""
    pos = 0
    dropped = 0
    n = len(text)
    while dropped < count and pos < n:
        m = _LINE_SPLIT_RE.search(text, pos)
        if m is None:
            pos = n
        else:
            pos = m.end()
        dropped += 1
    return text[pos:], dropped


def _read_records(text, delimiter, first_line):
    """Yield (line_number, cells) for every CSV record."""
    records = []
    i, n = 0, len(text)
    line = first_line
    while i < n:
        start = line
        cells = []
        cell = []
        while True:
            # read one field
            if i < n and text[i] == '"':
                i += 1
                while i < n:
                    c = text[i]
                    if c == '"':
                        if i + 1 < n and text[i + 1] == '"':
                            cell.append('"')
                            i += 2
                            continue
                        i += 1
                        break
                    if c == "\n":
                        line += 1
                    cell.append(c)
                    i += 1
            # unquoted part (or what follows a closing quote)
            while i < n and text[i] != delimiter and text[i] != "\n" and not text.startswith("\r\n", i):
                cell.append(text[i])
                i += 1
            cells.append("".join(cell))
            cell = []
            if i >= n:
                break
            if text[i] == delimiter:
                i += 1
                if i >= n:
                    cells.append("")
                    break
                continue
            # line end
            i += 2 if text[i] == "\r" else 1
            line += 1
            break
        records.append((start, cells))
    return records


# ---------------------------------------------------------------- amounts

def _amount_regex(decimal, thousands):
    d = re.escape(decimal)
    if thousands:
        t = re.escape(thousands)
        whole = r"(?:[0-9]{1,3}(?:%s[0-9]{3})+|[0-9]+)" % t
    else:
        whole = r"[0-9]+"
    return re.compile(r"(%s)(?:%s([0-9]+))?" % (whole, d))


def _parse_amount_cell(text, profile, regex, exponent):
    """Signed minor units for a cell (already trimmed); _Bad when it is not an amount."""
    if text == "":
        raise _Bad("empty amount")
    body = text
    negative = False
    if len(body) >= 2 and body[0] == "(" and body[-1] == ")":
        body = body[1:-1]
        negative = True
        sign_ok = False
    else:
        sign_ok = True
    if sign_ok and body[:1] in ("+", "-"):
        negative = body[0] == "-"
        body = body[1:]
    m = regex.fullmatch(body)
    if not m:
        raise _Bad("invalid amount '%s'" % text)
    whole, frac = m.groups()
    if profile.thousands_separator:
        whole = whole.replace(profile.thousands_separator, "")
    frac = frac or ""
    if len(frac) > exponent:
        raise _Bad("invalid amount '%s': %s has %s" % (
            text, profile.currency, "no decimals" if exponent == 0 else "at most %d decimals" % exponent))
    value = int(whole) * 10 ** exponent + (int(frac.ljust(exponent, "0")) if exponent else 0)
    return -value if negative else value


# ---------------------------------------------------------------- import

class ImportResult:
    """What an import produced: new transactions, duplicates and bad rows."""

    def __init__(self, transactions=None, duplicates=None, errors=None):
        self.transactions = list(transactions or [])
        self.duplicates = list(duplicates or [])
        self.errors = list(errors or [])

    def __repr__(self):
        return "ImportResult(%d transactions, %d duplicates, %d errors)" % (
            len(self.transactions), len(self.duplicates), len(self.errors))


def _clean(text):
    return " ".join(text.split())


def _key(tx, account):
    for p in tx.postings or ():
        if p.account == account:
            return (tx.date, p.amount, tx.payee)
    return None


def import_csv(text, profile, rules=None, existing=()):
    """Turn a CSV statement into transactions (see ImportResult)."""
    if isinstance(profile, str):
        profile = parse_profile(profile)
    if not isinstance(profile, ImportProfile):
        raise CsvImportError("profile must be an ImportProfile or profile text, got %r" % (profile,))
    if isinstance(rules, str):
        rules = parse_rules(rules)
    if rules is not None and not isinstance(rules, RuleSet):
        raise CsvImportError("rules must be a RuleSet, rules text or None, got %r" % (rules,))
    if not isinstance(text, str):
        raise CsvImportError("the CSV file must be text, got %r" % (text,))
    if text.startswith("﻿"):
        text = text[1:]

    rest, dropped = _skip_lines(text, profile.skip_rows)
    records = _read_records(rest, profile.delimiter, dropped + 1)
    records = [(ln, cells) for ln, cells in records if any(c.strip() for c in cells)]

    # resolve columns to 0-based indexes
    columns = {}
    names = [n for n in _COLUMN_SETTINGS if getattr(profile, n) is not None]
    if profile.has_header:
        if not records:
            raise CsvImportError("the file has no header")
        header = [c.strip().casefold() for c in records[0][1]]
        records = records[1:]
    for name in names:
        spec = getattr(profile, name)
        if spec.startswith("#") and spec[1:].isdigit():
            columns[name] = int(spec[1:]) - 1
            continue
        if not profile.has_header:
            raise CsvImportError("column '%s' needs a header: use #N with has_header = no" % spec)
        want = spec.strip().casefold()
        if want not in header:
            raise CsvImportError("column '%s' is not in the header" % spec)
        columns[name] = header.index(want)

    fmt = profile.date_format
    compiled = _compile_date_format(fmt)
    exponent = currency(profile.currency).exponent
    amount_re = _amount_regex(profile.decimal_separator, profile.thousands_separator)

    built = []  # (row, tx)
    errors = []
    for row, cells in records:
        try:
            def cell(name):
                idx = columns[name]
                if idx >= len(cells):
                    raise _Bad("row has no column '%s'" % getattr(profile, name))
                return cells[idx]

            date_text = cell("date_column").strip()
            payee_text = cell("payee_column")
            if profile.amount_column is not None:
                amount_cells = [cell("amount_column")]
            else:
                amount_cells = [cell("debit_column"), cell("credit_column")]
            narration = ""
            if "narration_column" in columns and columns["narration_column"] < len(cells):
                narration = _clean(cells[columns["narration_column"]])

            on = _parse_date_cell(date_text, fmt, compiled)
            payee = _clean(payee_text)
            if not payee:
                raise _Bad("empty payee")
            if profile.amount_column is not None:
                minor = _parse_amount_cell(amount_cells[0].strip(), profile, amount_re, exponent)
            else:
                debit, credit = (c.strip() for c in amount_cells)
                if debit and credit:
                    raise _Bad("both debit '%s' and credit '%s' are filled" % (debit, credit))
                if not debit and not credit:
                    raise _Bad("neither debit nor credit is filled")
                if credit:
                    minor = _parse_amount_cell(credit, profile, amount_re, exponent)
                else:
                    minor = -_parse_amount_cell(debit, profile, amount_re, exponent)
            if profile.negate:
                minor = -minor
            if minor == 0:
                raise _Bad("amount is zero")
            amount = Money(minor, profile.currency)

            counter = None
            flag = profile.flag
            tags = set(profile.tags)
            if rules is not None:
                rule = rules.match({"payee": payee, "narration": narration, "date": on, "amount": amount})
                if rule is not None:
                    counter = rule.account
                    if rule.payee is not None:
                        payee = rule.payee
                    if rule.narration is not None:
                        narration = rule.narration
                    if rule.flag is not None:
                        flag = rule.flag
                    tags.update(rule.tags)
            if counter is None:
                counter = profile.default_account
            if counter is None:
                raise _Bad("no account for the other side: no rule picks one and there is no default_account")
            tx = Transaction(
                date=on,
                payee=payee,
                narration=narration,
                postings=[Posting(profile.account, amount), Posting(counter, -amount)],
                tags=tuple(sorted(tags)),
                flag=flag,
                id=None,
            )
            built.append(tx)
        except _Bad as e:
            errors.append((row, str(e)))

    have = Counter()
    for tx in existing or ():
        k = _key(tx, profile.account)
        if k is not None:
            have[k] += 1
    seen = Counter()
    result = ImportResult(errors=errors)
    for tx in built:
        k = _key(tx, profile.account)
        seen[k] += 1
        if seen[k] <= have[k]:
            result.duplicates.append(tx)
        else:
            result.transactions.append(tx)
    return result

"""The book file: one SQLite database with numbered schema versions."""

import datetime
import json
import os
import re
import sqlite3
from dataclasses import dataclass, field
from typing import List

from tallybook.accounts import TYPES, Chart, ChartError, path_key
from tallybook.currency import RateTable, is_currency
from tallybook.dates import format_date, parse_date
from tallybook.errors import (ConflictError, NotFoundError, TallybookError, ValidationError, is_int)
from tallybook.ledger import Ledger, LedgerError
from tallybook.model import Account, Posting, Transaction
from tallybook.money import Money

__all__ = ["Store", "LATEST_VERSION", "BulkAdd", "ImportOutcome"]

LATEST_VERSION = 4
SQLITE_HEADER = b"SQLite format 3\x00"
PROFILE_NAME_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]*")


@dataclass
class BulkAdd:
    added: List[Transaction] = field(default_factory=list)
    skipped: List[int] = field(default_factory=list)


@dataclass
class ImportOutcome:
    added: List[Transaction] = field(default_factory=list)
    duplicates: List[Transaction] = field(default_factory=list)
    errors: list = field(default_factory=list)


# ---------------------------------------------------------------------------- migrations
def _migrate_1(conn):
    conn.execute("CREATE TABLE accounts (path TEXT PRIMARY KEY, type TEXT NOT NULL, currency TEXT, opened TEXT, "
                 "note TEXT NOT NULL DEFAULT '')")
    conn.execute("CREATE TABLE transactions (id INTEGER PRIMARY KEY AUTOINCREMENT, date TEXT NOT NULL, "
                 "payee TEXT NOT NULL, narration TEXT NOT NULL DEFAULT '', cleared INTEGER NOT NULL DEFAULT 1)")
    conn.execute("CREATE TABLE postings (id INTEGER PRIMARY KEY AUTOINCREMENT, "
                 "tx_id INTEGER NOT NULL REFERENCES transactions(id) ON DELETE CASCADE, "
                 "seq INTEGER NOT NULL, account TEXT NOT NULL REFERENCES accounts(path), "
                 "minor INTEGER NOT NULL, currency TEXT NOT NULL)")
    conn.execute("CREATE INDEX transactions_date_id ON transactions(date, id)")
    conn.execute("CREATE INDEX postings_tx_seq ON postings(tx_id, seq)")


def _migrate_2(conn):
    bad = conn.execute("SELECT COUNT(*) FROM transactions WHERE cleared IS NULL OR cleared NOT IN (0, 1)").fetchone()
    if bad[0]:
        raise ValueError("%d transactions have a cleared value that is not 0 or 1" % bad[0])
    conn.execute("CREATE TABLE tags (tx_id INTEGER NOT NULL REFERENCES transactions(id) ON DELETE CASCADE, "
                 "tag TEXT NOT NULL, PRIMARY KEY (tx_id, tag))")
    conn.execute("ALTER TABLE transactions ADD COLUMN flag TEXT NOT NULL DEFAULT '*'")
    conn.execute("ALTER TABLE postings ADD COLUMN note TEXT NOT NULL DEFAULT ''")
    conn.execute("UPDATE transactions SET flag = CASE cleared WHEN 0 THEN '!' ELSE '*' END")


_THREE_LETTERS = re.compile(r"[A-Z]{3}")


def _clean_currency(value):
    if value is None:
        return None
    if not isinstance(value, str):
        value = str(value)
    return value.strip(" \t\r\n\f\v").upper()


def _migrate_3(conn):
    conn.execute("CREATE TABLE rates (src TEXT NOT NULL, dst TEXT NOT NULL, on_date TEXT NOT NULL, "
                 "rate_text TEXT NOT NULL, PRIMARY KEY (src, dst, on_date))")
    conn.execute("ALTER TABLE accounts ADD COLUMN closed TEXT")
    for path, cur in conn.execute("SELECT path, currency FROM accounts").fetchall():
        if cur is None:
            continue
        cleaned = _clean_currency(cur)
        if cleaned == "":
            cleaned = None
        elif not _THREE_LETTERS.fullmatch(cleaned):
            raise ValueError("account %s has an invalid currency %r" % (path, cur))
        if cleaned != cur:
            conn.execute("UPDATE accounts SET currency = ? WHERE path = ?", (cleaned, path))
    for pid, cur in conn.execute("SELECT id, currency FROM postings").fetchall():
        cleaned = _clean_currency(cur)
        if cleaned is None or not _THREE_LETTERS.fullmatch(cleaned):
            raise ValueError("posting %s has an invalid currency %r" % (pid, cur))
        if cleaned != cur:
            conn.execute("UPDATE postings SET currency = ? WHERE id = ?", (cleaned, pid))


def _migrate_4(conn):
    conn.execute("CREATE TABLE budgets (pattern TEXT NOT NULL, period_kind TEXT NOT NULL, minor INTEGER NOT NULL, "
                 "currency TEXT NOT NULL, start_date TEXT NOT NULL, PRIMARY KEY (pattern, period_kind))")
    conn.execute("CREATE TABLE recurring (name TEXT PRIMARY KEY, schedule TEXT NOT NULL, template TEXT NOT NULL, "
                 "start_date TEXT NOT NULL, end_date TEXT, max_count INTEGER, materialized_through TEXT)")
    conn.execute("CREATE TABLE rules (id INTEGER PRIMARY KEY CHECK (id = 1), body TEXT NOT NULL)")
    conn.execute("CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT NOT NULL)")
    conn.execute("CREATE TABLE import_keys (key TEXT PRIMARY KEY, "
                 "tx_id INTEGER NOT NULL REFERENCES transactions(id) ON DELETE CASCADE)")


MIGRATIONS = {1: _migrate_1, 2: _migrate_2, 3: _migrate_3, 4: _migrate_4}


# ---------------------------------------------------------------------------- helpers
def _is_date(value):
    return isinstance(value, datetime.date) and not isinstance(value, datetime.datetime)


def _d(text):
    return parse_date(text) if text is not None else None


def _ds(value):
    return format_date(value) if value is not None else None


def _template_to_json(tx):
    return json.dumps({
        "date": _ds(tx.date) if _is_date(tx.date) else None,
        "payee": tx.payee,
        "narration": tx.narration,
        "flag": tx.flag,
        "tags": list(tx.tags),
        "tags_list": isinstance(tx.tags, list),
        "id": tx.id,
        "postings": [{"account": p.account,
                      "amount": None if p.amount is None else [p.amount.minor, p.amount.currency],
                      "note": p.note} for p in tx.postings],
    }, sort_keys=True, ensure_ascii=False)


def _template_from_json(text):
    data = json.loads(text)
    postings = [Posting(p["account"], None if p["amount"] is None else Money(p["amount"][0], p["amount"][1]),
                        p.get("note", "")) for p in data["postings"]]
    tags = list(data["tags"]) if data.get("tags_list") else tuple(data["tags"])
    return Transaction(_d(data["date"]), data["payee"], data["narration"], postings, tags, data["flag"], data["id"])


class Store:
    """A tallybook book file."""

    def __init__(self, path, conn):
        self.path = path
        self._conn = conn
        self._closed = False

    # ------------------------------------------------------------------ opening
    @classmethod
    def open(cls, path, create=False):
        given = path
        fs = os.fspath(path)
        if os.path.isdir(fs):
            raise ConflictError("%s is a directory, not a tallybook book" % fs)
        exists = os.path.exists(fs)
        if not exists:
            if not create:
                raise NotFoundError("no such database: %s" % fs)
            parent = os.path.dirname(os.path.abspath(fs))
            if not os.path.isdir(parent):
                raise NotFoundError("no such directory: %s" % (os.path.dirname(fs) or parent))
        else:
            try:
                with open(fs, "rb") as fh:
                    head = fh.read(16)
            except OSError as e:
                raise ConflictError("cannot read %s: %s" % (fs, e.strerror or e)) from None
            if head and head != SQLITE_HEADER:
                raise ConflictError("%s is not a tallybook book" % fs)
        try:
            conn = sqlite3.connect(fs, timeout=5.0, isolation_level=None, check_same_thread=False)
        except sqlite3.Error as e:
            raise ConflictError("cannot open %s: %s" % (fs, e)) from None
        store = cls(given if isinstance(given, str) else fs, conn)
        try:
            conn.execute("PRAGMA foreign_keys = ON")
            version = store._read_version()
            if version == 0:
                tables = conn.execute("SELECT COUNT(*) FROM sqlite_master WHERE type = 'table' "
                                      "AND name NOT LIKE 'sqlite_%'").fetchone()[0]
                if tables:
                    raise ConflictError("%s is not a tallybook book" % fs)
            if version > LATEST_VERSION:
                raise ConflictError("%s is at version %d, newer than this tallybook (version %d)"
                                    % (fs, version, LATEST_VERSION))
            if create and version == 0:
                store.migrate()
        except sqlite3.DatabaseError as e:
            conn.close()
            raise ConflictError("%s is not a tallybook book: %s" % (fs, e)) from None
        except BaseException:
            conn.close()
            raise
        return store

    def __enter__(self):
        return self

    def __exit__(self, *exc):
        self.close()
        return False

    def close(self):
        if not self._closed:
            self._closed = True
            try:
                self._conn.close()
            except sqlite3.Error:
                pass

    def _check_open(self):
        if self._closed:
            raise ConflictError("the book is closed")

    def _read_version(self):
        try:
            return self._conn.execute("PRAGMA user_version").fetchone()[0]
        except sqlite3.OperationalError as e:
            raise ConflictError("database is busy: %s" % e) from None

    @property
    def version(self):
        self._check_open()
        return self._read_version()

    def _require(self):
        self._check_open()
        v = self._read_version()
        if v != LATEST_VERSION:
            raise ConflictError("database is at version %d, run `tallybook db migrate`" % v)

    def migrate(self):
        self._check_open()
        applied = []
        current = self._read_version()
        if current > LATEST_VERSION:
            raise ConflictError("database is at version %d, newer than this tallybook" % current)
        for v in range(current + 1, LATEST_VERSION + 1):
            try:
                self._conn.execute("BEGIN IMMEDIATE")
            except sqlite3.OperationalError as e:
                raise ConflictError("database is busy: %s" % e) from None
            try:
                MIGRATIONS[v](self._conn)
                self._conn.execute("PRAGMA user_version = %d" % v)
                self._conn.execute("COMMIT")
            except Exception as e:
                try:
                    self._conn.execute("ROLLBACK")
                except sqlite3.Error:
                    pass
                raise ConflictError("migration to version %d failed: %s" % (v, e)) from None
            applied.append(v)
        return applied

    # ------------------------------------------------------------ transactions
    def _q(self, sql, args=()):
        try:
            return self._conn.execute(sql, args).fetchall()
        except sqlite3.OperationalError as e:
            if "locked" in str(e) or "busy" in str(e):
                raise ConflictError("database is busy: %s" % e) from None
            raise

    def _write(self, fn):
        """Run fn() inside one write transaction; all or nothing."""
        try:
            self._conn.execute("BEGIN IMMEDIATE")
        except sqlite3.OperationalError as e:
            raise ConflictError("database is busy: %s" % e) from None
        try:
            result = fn()
            self._conn.execute("COMMIT")
            return result
        except sqlite3.IntegrityError as e:
            self._rollback()
            raise ConflictError("database constraint failed: %s" % e) from None
        except sqlite3.OperationalError as e:
            self._rollback()
            if "locked" in str(e) or "busy" in str(e):
                raise ConflictError("database is busy: %s" % e) from None
            raise
        except BaseException:
            self._rollback()
            raise

    def _rollback(self):
        try:
            self._conn.execute("ROLLBACK")
        except sqlite3.Error:
            pass

    # ---------------------------------------------------------------- accounts
    def _account_rows(self):
        return self._q("SELECT path, type, currency, opened, closed, note FROM accounts")

    @staticmethod
    def _row_account(row):
        path, typ, cur, opened, closed, note = row
        from tallybook.accounts import ROOT_TYPES
        t = ROOT_TYPES.get(path.split(":", 1)[0], typ)
        return Account(path, t, cur, _d(opened), _d(closed), note or "")

    def _build_chart(self):
        chart = Chart()
        rows = sorted(self._account_rows(), key=lambda r: path_key(r[0]))
        for row in rows:
            acc = self._row_account(row)
            try:
                stored = chart.add(acc.path, opened=acc.opened, note=acc.note)
            except ChartError:
                continue
            stored.currency = acc.currency
            stored.closed = acc.closed
        return chart

    def chart(self):
        self._require()
        return self._build_chart()

    def add_account(self, path, type=None, currency=None, opened=None, note=""):
        self._require()
        chart = self._build_chart()
        acc = chart.add(path, type=type, currency=currency, opened=opened, note=note)

        def go():
            self._conn.execute("INSERT INTO accounts (path, type, currency, opened, note, closed) "
                               "VALUES (?, ?, ?, ?, ?, NULL)", (acc.path, acc.type, acc.currency,
                                                                 _ds(acc.opened), acc.note))
        self._write(go)
        return self.get_account(path)

    def get_account(self, path):
        self._require()
        rows = self._q("SELECT path, type, currency, opened, closed, note FROM accounts WHERE path = ?",
                       (path,)) if isinstance(path, str) else []
        if not rows:
            raise NotFoundError("no such account %s" % (path if isinstance(path, str) else repr(path)))
        return self._row_account(rows[0])

    def accounts(self, type=None, under=None, currency=None, include_closed=True):
        self._require()
        if type is not None and type not in TYPES:
            raise ValidationError("invalid account type %r: expected one of %s" % (type, ", ".join(TYPES)))
        out = []
        for row in self._account_rows():
            acc = self._row_account(row)
            if type is not None and acc.type != type:
                continue
            if under is not None and not (acc.path == under or acc.path.startswith(str(under) + ":")):
                continue
            if currency is not None and acc.currency != currency:
                continue
            if not include_closed and acc.closed is not None:
                continue
            out.append(acc)
        out.sort(key=lambda a: path_key(a.path))
        return out

    def count_accounts(self, type=None, under=None, currency=None, include_closed=True):
        return len(self.accounts(type=type, under=under, currency=currency, include_closed=include_closed))

    def close_account(self, path, on):
        self._require()
        self.get_account(path)
        chart = self._build_chart()
        chart.close(path, on)
        last = self._q("SELECT MAX(t.date) FROM postings p JOIN transactions t ON t.id = p.tx_id "
                       "WHERE p.account = ?", (path,))[0][0]
        if last is not None and last > format_date(on):
            raise ConflictError("cannot close %s on %s: it has a posting on %s" % (path, format_date(on), last))

        def go():
            self._conn.execute("UPDATE accounts SET closed = ? WHERE path = ?", (format_date(on), path))
        self._write(go)
        return self.get_account(path)

    def set_account_note(self, path, note):
        self._require()
        self.get_account(path)
        if not isinstance(note, str):
            raise ValidationError("invalid note %r" % (note,))

        def go():
            self._conn.execute("UPDATE accounts SET note = ? WHERE path = ?", (note, path))
        self._write(go)
        return self.get_account(path)

    def delete_account(self, path):
        self._require()
        self.get_account(path)
        used = self._q("SELECT COUNT(*) FROM postings WHERE account = ?", (path,))[0][0]
        if used:
            raise ConflictError("account %s has postings and cannot be deleted" % path)

        def go():
            self._conn.execute("DELETE FROM accounts WHERE path = ?", (path,))
        self._write(go)

    # ------------------------------------------------------------ transactions
    def _load_transactions(self, ids=None):
        if ids is None:
            txrows = self._q("SELECT id, date, payee, narration, flag FROM transactions ORDER BY date, id")
            prows = self._q("SELECT tx_id, account, minor, currency, note FROM postings ORDER BY tx_id, seq, id")
            trows = self._q("SELECT tx_id, tag FROM tags")
        else:
            marks = ",".join("?" * len(ids))
            txrows = self._q("SELECT id, date, payee, narration, flag FROM transactions WHERE id IN (%s) "
                             "ORDER BY date, id" % marks, tuple(ids))
            prows = self._q("SELECT tx_id, account, minor, currency, note FROM postings WHERE tx_id IN (%s) "
                            "ORDER BY tx_id, seq, id" % marks, tuple(ids))
            trows = self._q("SELECT tx_id, tag FROM tags WHERE tx_id IN (%s)" % marks, tuple(ids))
        postings = {}
        for tx_id, account, minor, cur, note in prows:
            postings.setdefault(tx_id, []).append(Posting(account, Money(minor, cur), note or ""))
        tags = {}
        for tx_id, tag in trows:
            tags.setdefault(tx_id, set()).add(tag)
        out = []
        for tid, date, payee, narration, flag in txrows:
            out.append(Transaction(parse_date(date), payee, narration or "", postings.get(tid, []),
                                   tuple(sorted(tags.get(tid, ()))), flag, tid))
        return out

    def _build_rates(self):
        table = RateTable()
        for src, dst, on, text in self._q("SELECT src, dst, on_date, rate_text FROM rates"):
            try:
                table.set(src, dst, text, parse_date(on))
            except TallybookError:
                continue
        return table

    def _build_ledger(self):
        ledger = Ledger(self._build_chart(), self._build_rates())
        for tx in self._load_transactions():
            ledger._load(tx)
        return ledger

    def ledger(self):
        self._require()
        return self._build_ledger()

    def _next_id(self):
        top = self._q("SELECT MAX(id) FROM transactions")[0][0] or 0
        try:
            seq = self._q("SELECT seq FROM sqlite_sequence WHERE name = 'transactions'")
        except sqlite3.OperationalError:
            seq = []
        if seq and seq[0][0] is not None:
            top = max(top, seq[0][0])
        return top + 1

    def _validator(self):
        return Ledger(self._build_chart(), self._build_rates())

    def _ensure_account_rows(self, chart, tx):
        stored = {r[0] for r in self._q("SELECT path FROM accounts")}
        for p in tx.postings:
            if p.account not in stored:
                acc = chart.get(p.account)
                self._conn.execute("INSERT INTO accounts (path, type, currency, opened, note, closed) "
                                   "VALUES (?, ?, ?, ?, ?, ?)", (acc.path, acc.type, acc.currency,
                                                                 _ds(acc.opened), acc.note, _ds(acc.closed)))
                stored.add(p.account)

    def _insert_tx(self, tx, chart):
        self._ensure_account_rows(chart, tx)
        self._conn.execute("INSERT INTO transactions (id, date, payee, narration, cleared, flag) "
                           "VALUES (?, ?, ?, ?, ?, ?)",
                           (tx.id, format_date(tx.date), tx.payee, tx.narration, 1 if tx.flag == "*" else 0,
                            tx.flag))
        for seq, p in enumerate(tx.postings):
            self._conn.execute("INSERT INTO postings (tx_id, seq, account, minor, currency, note) "
                               "VALUES (?, ?, ?, ?, ?, ?)",
                               (tx.id, seq, p.account, p.amount.minor, p.amount.currency, p.note))
        for tag in tx.tags:
            self._conn.execute("INSERT INTO tags (tx_id, tag) VALUES (?, ?)", (tx.id, tag))

    @staticmethod
    def _without_id(tx):
        if not isinstance(tx, Transaction):
            raise LedgerError("not a transaction: %r" % (tx,))
        return Transaction(tx.date, tx.payee, tx.narration, tx.postings, tx.tags, tx.flag, None)

    def add_transaction(self, tx):
        self._require()
        ledger = self._validator()
        stored = ledger.add(self._without_id(tx))

        def go():
            stored.id = self._next_id()
            self._insert_tx(stored, ledger.chart)
            return stored
        return self._write(go)

    def add_transactions(self, txs, keys=None):
        self._require()
        txs = list(txs)
        if keys is not None:
            keys = list(keys)
            if len(keys) != len(txs) or not all(isinstance(k, str) for k in keys):
                raise ValidationError("keys must be one text per transaction")
        existing_keys = {r[0] for r in self._q("SELECT key FROM import_keys")} if keys is not None else set()
        ledger = self._validator()
        prepared = []
        skipped = []
        seen = set()
        for i, tx in enumerate(txs):
            if keys is not None:
                k = keys[i]
                if k in existing_keys or k in seen:
                    skipped.append(i)
                    continue
                seen.add(k)
            try:
                stored = ledger.add(self._without_id(tx))
            except TallybookError as e:
                e.detail = dict(e.detail or {})
                e.detail["index"] = i
                raise
            prepared.append((i, stored))

        def go():
            nid = self._next_id()
            out = []
            for i, stored in prepared:
                stored.id = nid
                nid += 1
                self._insert_tx(stored, ledger.chart)
                if keys is not None:
                    self._conn.execute("INSERT INTO import_keys (key, tx_id) VALUES (?, ?)", (keys[i], stored.id))
                out.append(stored)
            return out
        added = self._write(go) if prepared else []
        return BulkAdd(added=added, skipped=skipped)

    def _parse_query(self, query):
        from tallybook.query import Query, parse_query
        if query is None:
            return None
        if isinstance(query, Query):
            return None if query.is_empty else query
        if not isinstance(query, str):
            raise ValidationError("invalid query %r" % (query,))
        if not query.strip():
            return None
        return parse_query(query, chart=self._build_chart())

    def transactions(self, query=None, limit=None, offset=0):
        self._require()
        if limit is not None and (not is_int(limit) or limit < 0):
            raise ValidationError("invalid limit %r: expected a whole number of at least 0" % (limit,))
        if not is_int(offset) or offset < 0:
            raise ValidationError("invalid offset %r: expected a whole number of at least 0" % (offset,))
        q = self._parse_query(query)
        txs = self._load_transactions()
        if q is not None:
            txs = [t for t in txs if q.matches(t)]
        txs = txs[offset:]
        if limit is not None:
            txs = txs[:limit]
        return txs

    def count_transactions(self, query=None):
        self._require()
        q = self._parse_query(query)
        if q is None:
            return self._q("SELECT COUNT(*) FROM transactions")[0][0]
        return sum(1 for t in self._load_transactions() if q.matches(t))

    def has_import_key(self, key):
        self._require()
        return bool(self._q("SELECT 1 FROM import_keys WHERE key = ?", (key,)))

    def get_transaction(self, id):
        self._require()
        if not is_int(id):
            raise NotFoundError("no transaction %r" % (id,))
        txs = self._load_transactions([id])
        if not txs:
            raise NotFoundError("no transaction %r" % (id,))
        return txs[0]

    def delete_transaction(self, id):
        tx = self.get_transaction(id)

        def go():
            self._conn.execute("DELETE FROM import_keys WHERE tx_id = ?", (id,))
            self._conn.execute("DELETE FROM tags WHERE tx_id = ?", (id,))
            self._conn.execute("DELETE FROM postings WHERE tx_id = ?", (id,))
            self._conn.execute("DELETE FROM transactions WHERE id = ?", (id,))
        self._write(go)
        return tx

    # ------------------------------------------------------------------ rates
    def set_rate(self, src, dst, rate_text, on):
        self._require()
        RateTable().set(src, dst, rate_text, on)

        def go():
            self._conn.execute("INSERT OR REPLACE INTO rates (src, dst, on_date, rate_text) VALUES (?, ?, ?, ?)",
                               (src, dst, format_date(on), rate_text))
        self._write(go)

    def remove_rate(self, src, dst, on):
        self._require()
        if not _is_date(on):
            raise ValidationError("invalid date %r" % (on,))
        rows = self._q("SELECT 1 FROM rates WHERE src = ? AND dst = ? AND on_date = ?", (src, dst, format_date(on)))
        if not rows:
            raise NotFoundError("no rate %s -> %s set on %s" % (src, dst, format_date(on)))

        def go():
            self._conn.execute("DELETE FROM rates WHERE src = ? AND dst = ? AND on_date = ?",
                               (src, dst, format_date(on)))
        self._write(go)

    def rate_rows(self):
        self._require()
        return [(s, d, parse_date(o), t) for s, d, o, t in
                self._q("SELECT src, dst, on_date, rate_text FROM rates ORDER BY src, dst, on_date")]

    def rate_table(self):
        self._require()
        return self._build_rates()

    # ---------------------------------------------------------------- budgets
    def add_budget(self, budget):
        from tallybook.budgets import Budget
        self._require()
        if not isinstance(budget, Budget):
            raise ValidationError("not a budget: %r" % (budget,))
        if self._q("SELECT 1 FROM budgets WHERE pattern = ? AND period_kind = ?",
                   (budget.pattern, budget.period_kind)):
            raise ConflictError("a %s budget for %s already exists" % (budget.period_kind, budget.pattern))

        def go():
            self._conn.execute("INSERT INTO budgets (pattern, period_kind, minor, currency, start_date) "
                               "VALUES (?, ?, ?, ?, ?)", (budget.pattern, budget.period_kind, budget.amount.minor,
                                                          budget.amount.currency, format_date(budget.start)))
        self._write(go)
        return budget

    def remove_budget(self, pattern, period_kind):
        self._require()
        found = [b for b in self.budgets() if b.pattern == pattern and b.period_kind == period_kind]
        if not found:
            raise NotFoundError("no %s budget for %s" % (period_kind, pattern))

        def go():
            self._conn.execute("DELETE FROM budgets WHERE pattern = ? AND period_kind = ?", (pattern, period_kind))
        self._write(go)
        return found[0]

    def budgets(self):
        from tallybook.budgets import Budget
        self._require()
        return [Budget(p, k, Money(m, c), parse_date(s)) for p, k, m, c, s in
                self._q("SELECT pattern, period_kind, minor, currency, start_date FROM budgets "
                        "ORDER BY pattern, period_kind")]

    # -------------------------------------------------------------- recurring
    def add_recurring(self, rec):
        from tallybook.recurring import Recurring
        self._require()
        if not isinstance(rec, Recurring):
            raise ValidationError("not a recurring item: %r" % (rec,))
        if self._q("SELECT 1 FROM recurring WHERE name = ?", (rec.name,)):
            raise ConflictError("recurring item %s already exists" % rec.name)

        def go():
            self._conn.execute("INSERT INTO recurring (name, schedule, template, start_date, end_date, max_count, "
                               "materialized_through) VALUES (?, ?, ?, ?, ?, ?, NULL)",
                               (rec.name, str(rec.schedule), _template_to_json(rec.template),
                                format_date(rec.start), _ds(rec.end), rec.count))
        self._write(go)
        return rec

    def _recurring_rows(self):
        from tallybook.recurring import Recurring
        out = []
        for name, sched, tmpl, start, end, count, through in self._q(
                "SELECT name, schedule, template, start_date, end_date, max_count, materialized_through "
                "FROM recurring ORDER BY name"):
            out.append((Recurring(name, sched, _template_from_json(tmpl), parse_date(start), _d(end), count),
                        _d(through)))
        return out

    def recurring(self):
        self._require()
        return [r for r, _ in self._recurring_rows()]

    def remove_recurring(self, name):
        self._require()
        found = [r for r, _ in self._recurring_rows() if r.name == name]
        if not found:
            raise NotFoundError("no recurring item %s" % (name,))

        def go():
            self._conn.execute("DELETE FROM recurring WHERE name = ?", (name,))
        self._write(go)
        return found[0]

    def materialized_through(self, name):
        self._require()
        rows = self._q("SELECT materialized_through FROM recurring WHERE name = ?", (name,))
        if not rows:
            raise NotFoundError("no recurring item %s" % (name,))
        return _d(rows[0][0])

    def materialize(self, upto=None, today=None):
        from tallybook.recurring import instantiate, occurrences
        self._require()
        for v in (upto, today):
            if v is not None and not _is_date(v):
                raise ValidationError("invalid date %r" % (v,))
        if upto is None and today is None:
            raise ValidationError("materialize needs a horizon: give upto or today")
        horizon = min(d for d in (upto, today) if d is not None)
        items = []
        for rec, through in self._recurring_rows():
            first = rec.start
            if through is not None:
                if through >= horizon:
                    continue
                first = max(first, through + datetime.timedelta(days=1))
            for on in occurrences(rec, first, horizon):
                items.append((on, rec.name, instantiate(rec, on)))
        items.sort(key=lambda t: (t[0], t[1]))
        ledger = self._validator()
        prepared = [ledger.add(self._without_id(tx)) for _, _, tx in items]

        def go():
            nid = self._next_id()
            for stored in prepared:
                stored.id = nid
                nid += 1
                self._insert_tx(stored, ledger.chart)
            hz = format_date(horizon)
            self._conn.execute("UPDATE recurring SET materialized_through = ? WHERE materialized_through IS NULL "
                               "OR materialized_through < ?", (hz, hz))
            return prepared
        return self._write(go)

    # ---------------------------------------------------------- rules/settings
    def set_rules(self, text):
        from tallybook.rules import parse_rules
        self._require()
        if not isinstance(text, str):
            raise ValidationError("rules must be text")
        parse_rules(text)

        def go():
            self._conn.execute("INSERT OR REPLACE INTO rules (id, body) VALUES (1, ?)", (text,))
        self._write(go)

    def rules_text(self):
        self._require()
        rows = self._q("SELECT body FROM rules WHERE id = 1")
        return rows[0][0] if rows else ""

    def rules(self):
        from tallybook.rules import parse_rules
        return parse_rules(self.rules_text())

    def get_setting(self, key, default=None):
        self._require()
        rows = self._q("SELECT value FROM settings WHERE key = ?", (key,)) if isinstance(key, str) else []
        return rows[0][0] if rows else default

    def set_setting(self, key, value):
        self._require()
        if not isinstance(key, str) or not key:
            raise ValidationError("a setting key must be non-empty text")
        if not isinstance(value, str):
            raise ValidationError("a setting value must be text")

        def go():
            self._conn.execute("INSERT OR REPLACE INTO settings (key, value) VALUES (?, ?)", (key, value))
        self._write(go)

    def delete_setting(self, key):
        self._require()

        def go():
            self._conn.execute("DELETE FROM settings WHERE key = ?", (key,))
        self._write(go)

    def settings(self):
        self._require()
        return dict(self._q("SELECT key, value FROM settings ORDER BY key"))

    @staticmethod
    def _check_profile_name(name):
        if not isinstance(name, str) or not PROFILE_NAME_RE.fullmatch(name):
            raise ValidationError("invalid profile name %r" % (name,))

    def set_profile(self, name, text):
        from tallybook.csvimport import parse_profile
        self._require()
        self._check_profile_name(name)
        if not isinstance(text, str):
            raise ValidationError("a profile must be text")
        parse_profile(text)
        self.set_setting("profile." + name, text)

    def profile_text(self, name):
        self._require()
        value = self.get_setting("profile." + name) if isinstance(name, str) else None
        if value is None:
            raise NotFoundError("no profile %s" % (name,))
        return value

    def profiles(self):
        self._require()
        return [k[len("profile."):] for k in self.settings() if k.startswith("profile.")]

    def remove_profile(self, name):
        self.profile_text(name)
        self.delete_setting("profile." + name)

    # ------------------------------------------------------------- CSV import
    def import_csv(self, text, profile, apply_rules=True):
        from tallybook.csvimport import ImportProfile, import_csv, parse_profile
        self._require()
        if isinstance(profile, ImportProfile):
            prof = profile
        elif isinstance(profile, str):
            if PROFILE_NAME_RE.fullmatch(profile):
                prof = parse_profile(self.profile_text(profile))
            else:
                prof = parse_profile(profile)
        else:
            raise ValidationError("invalid profile %r" % (profile,))
        rules = self.rules() if apply_rules else None
        existing = self._load_transactions()
        result = import_csv(text, prof, rules, existing)
        if result.errors:
            return ImportOutcome([], list(result.duplicates), list(result.errors))
        taken = {r[0] for r in self._q("SELECT key FROM import_keys")}
        keys = []
        for tx in result.transactions:
            first = tx.postings[0]
            base = "%s|%s|%s|%d %s" % (format_date(tx.date), tx.payee, first.account, first.amount.minor,
                                       first.amount.currency)
            n = 1
            while "%s|%d" % (base, n) in taken:
                n += 1
            key = "%s|%d" % (base, n)
            taken.add(key)
            keys.append(key)
        bulk = self.add_transactions(result.transactions, keys)
        return ImportOutcome(bulk.added, list(result.duplicates), [])

    # ----------------------------------------------------------------- journal
    def journal(self):
        from tallybook.journal import Journal
        self._require()
        accounts = self.accounts()
        rates = self.rate_rows()
        txs = []
        for tx in self._load_transactions():
            txs.append(Transaction(tx.date, tx.payee, tx.narration, tx.postings, tx.tags, tx.flag, None))
        return Journal(accounts=accounts, rates=rates, transactions=txs)

    def load_journal(self, journal):
        self._require()
        chart = self._build_chart()
        rates = self._build_rates()
        new_accounts = []
        for acc in journal.accounts:
            stored = chart.add(acc.path, type=acc.type, currency=acc.currency, opened=acc.opened, note=acc.note)
            if acc.closed is not None:
                chart.close(acc.path, acc.closed)
            new_accounts.append(stored)
        for src, dst, on, text in journal.rates:
            rates.set(src, dst, text, on)
        ledger = Ledger(chart, rates)
        prepared = [ledger.add(self._without_id(tx)) for tx in journal.transactions]

        def go():
            for acc in new_accounts:
                self._conn.execute("INSERT OR REPLACE INTO accounts (path, type, currency, opened, note, closed) "
                                   "VALUES (?, ?, ?, ?, ?, ?)", (acc.path, acc.type, acc.currency, _ds(acc.opened),
                                                                 acc.note, _ds(acc.closed)))
            for src, dst, on, text in journal.rates:
                self._conn.execute("INSERT OR REPLACE INTO rates (src, dst, on_date, rate_text) VALUES (?, ?, ?, ?)",
                                   (src, dst, format_date(on), text))
            nid = self._next_id()
            for stored in prepared:
                stored.id = nid
                nid += 1
                self._insert_tx(stored, chart)
            return prepared
        return self._write(go)

    # ------------------------------------------------------------ health etc.
    def check(self):
        self._require()
        problems = []
        for (res,) in self._q("PRAGMA integrity_check"):
            if res != "ok":
                problems.append("integrity check: %s" % res)
        for (tx_id,) in self._q("SELECT DISTINCT tx_id FROM postings WHERE tx_id NOT IN (SELECT id FROM transactions)"):
            problems.append("postings point to missing transaction %s" % tx_id)
        for (tx_id,) in self._q("SELECT DISTINCT tx_id FROM tags WHERE tx_id NOT IN (SELECT id FROM transactions)"):
            problems.append("tags point to missing transaction %s" % tx_id)
        for key, tx_id in self._q("SELECT key, tx_id FROM import_keys WHERE tx_id NOT IN (SELECT id FROM transactions)"):
            problems.append("import key %s points to missing transaction %s" % (key, tx_id))
        for (tx_id,) in self._q("SELECT id FROM transactions WHERE id NOT IN (SELECT tx_id FROM postings)"):
            problems.append("transaction %s has no postings" % tx_id)
        for tx_id, account in self._q("SELECT DISTINCT tx_id, account FROM postings "
                                      "WHERE account NOT IN (SELECT path FROM accounts)"):
            problems.append("transaction %s posts to unknown account %s" % (tx_id, account))
        for tx_id, cur, total in self._q("SELECT p.tx_id, p.currency, SUM(p.minor) FROM postings p "
                                         "JOIN transactions t ON t.id = p.tx_id "
                                         "GROUP BY p.tx_id, p.currency HAVING SUM(p.minor) != 0"):
            try:
                from tallybook.money import format_minor
                amount = "%s %s" % (format_minor(total, cur), cur)
            except TallybookError:
                amount = "%s %s" % (total, cur)
            problems.append("transaction %s does not balance: %s" % (tx_id, amount))
        return sorted(problems)

    def backup(self, dest):
        self._require()
        fs = os.fspath(dest)
        if os.path.exists(fs):
            raise ConflictError("%s already exists" % fs)
        parent = os.path.dirname(os.path.abspath(fs))
        if not os.path.isdir(parent):
            raise NotFoundError("no such directory: %s" % (os.path.dirname(fs) or parent))
        try:
            target = sqlite3.connect(fs)
        except sqlite3.Error as e:
            raise ConflictError("cannot create %s: %s" % (fs, e)) from None
        try:
            self._conn.backup(target)
        finally:
            target.close()

    def info(self):
        self._require()

        def count(table):
            return self._q("SELECT COUNT(*) FROM %s" % table)[0][0]
        return {
            "path": self.path,
            "version": self.version,
            "accounts": count("accounts"),
            "transactions": count("transactions"),
            "postings": count("postings"),
            "rates": count("rates"),
            "budgets": count("budgets"),
            "recurring": count("recurring"),
        }

