"""The query language for finding transactions."""

import operator
import re
from fractions import Fraction

from tallybook.currency import is_currency
from tallybook.dates import DateError, Period, parse_date
from tallybook.errors import ParseError

__all__ = ["parse_query", "select", "Query", "QueryError"]


class QueryError(ParseError):
    """A query that cannot be understood; `.position` is the 1-based place of the mistake."""

    def __init__(self, description, position, **detail):
        super().__init__("%s at position %d" % (description, position), **detail)
        self.position = position


_SPACES = " \t"
_STOP = " \t()"
_NAME_RE = re.compile(r"[A-Za-z][A-Za-z0-9_-]*")
_OP_RE = re.compile(r"<=|>=|!=|<|>|=")
_PART_RE = re.compile(r"[A-Za-z0-9_-]+")
_AMOUNT_RE = re.compile(r"([+-]?[0-9]+(?:\.[0-9]+)?)([A-Za-z]*)")
_NAMES = ("payee", "narration", "tag", "date", "flag", "id", "account")
_COMPARABLE = ("date", "amount")
_KEYWORDS = ("and", "or", "not")
_OPS = {
    "<": operator.lt,
    "<=": operator.le,
    ">": operator.gt,
    ">=": operator.ge,
    "=": operator.eq,
    "!=": operator.ne,
}


# ------------------------------------------------------------------ the tree


class _Node:
    on_posting = False

    def eval(self, tx, posting):  # pragma: no cover - overridden
        raise NotImplementedError


class _And(_Node):
    def __init__(self, left, right):
        self.left, self.right = left, right

    def eval(self, tx, posting):
        return self.left.eval(tx, posting) and self.right.eval(tx, posting)


class _Or(_Node):
    def __init__(self, left, right):
        self.left, self.right = left, right

    def eval(self, tx, posting):
        return self.left.eval(tx, posting) or self.right.eval(tx, posting)


class _Not(_Node):
    def __init__(self, inner):
        self.inner = inner

    def eval(self, tx, posting):
        return not self.inner.eval(tx, posting)


class _Contains(_Node):
    def __init__(self, fields, text):
        self.fields = fields
        self.text = text.lower()

    def eval(self, tx, posting):
        for f in self.fields:
            value = getattr(tx, f, None)
            if isinstance(value, str) and self.text in value.lower():
                return True
        return False


class _Tag(_Node):
    def __init__(self, name):
        self.name = name.lower()

    def eval(self, tx, posting):
        return any(isinstance(t, str) and t.lower() == self.name for t in (tx.tags or ()))


class _InPeriod(_Node):
    def __init__(self, period):
        self.period = period

    def eval(self, tx, posting):
        return self.period.start <= tx.date <= self.period.end


class _DateCmp(_Node):
    def __init__(self, op, date):
        self.op, self.date = _OPS[op], date

    def eval(self, tx, posting):
        return self.op(tx.date, self.date)


class _Flag(_Node):
    def __init__(self, flag):
        self.flag = flag

    def eval(self, tx, posting):
        return tx.flag == self.flag


class _Id(_Node):
    def __init__(self, value):
        self.value = value

    def eval(self, tx, posting):
        return tx.id is not None and not isinstance(tx.id, bool) and tx.id == self.value


class _Account(_Node):
    def __init__(self, parts):
        self.parts = parts

    def eval(self, tx, posting):
        return isinstance(posting.account, str) and _pattern_matches(self.parts, posting.account)


class _AmountCmp(_Node):
    def __init__(self, op, value, code):
        self.op, self.value, self.code = _OPS[op], value, code

    def eval(self, tx, posting):
        m = posting.amount
        if m is None:
            return False
        if self.code is not None and m.currency != self.code:
            return False
        return self.op(Fraction(m.minor, 10 ** m.exponent), self.value)


def _pattern_matches(parts, path):
    """Does the pattern name the account (or an account above it)?"""
    segs = path.split(":")

    def match(i, j):
        if i == len(parts):
            return True  # the account may go on below
        p = parts[i]
        if p == "**":
            return any(match(i + 1, k) for k in range(j, len(segs) + 1))
        if j >= len(segs):
            return False
        if p == "*" or p == segs[j]:
            return match(i + 1, j + 1)
        return False

    return match(0, 0)


def _compile_pattern(text):
    parts = text.split(":")
    for p in parts:
        if p in ("*", "**"):
            continue
        if not _PART_RE.fullmatch(p):
            return None
    return parts


# ----------------------------------------------------------------- the lexer


class _Token:
    __slots__ = ("kind", "pos", "node", "error")

    def __init__(self, kind, pos, node=None, error=None):
        self.kind = kind  # "term", "and", "or", "not", "(", ")", "end", "error"
        self.pos = pos
        self.node = node
        self.error = error


def _read_quoted(text, i):
    """Read a quoted string whose opening quote is at index i; return (value, index after it)."""
    n = len(text)
    j = i + 1
    buf = []
    while True:
        if j >= n:
            raise QueryError("unterminated quote", i + 1)
        c = text[j]
        if c == "\\" and j + 1 < n and text[j + 1] in '"\\':
            buf.append(text[j + 1])
            j += 2
            continue
        if c == '"':
            break
        buf.append(c)
        j += 1
    j += 1
    if j < n and text[j] not in _STOP:
        raise QueryError("unexpected text after closing quote", j + 1)
    return "".join(buf), j


def _read_bare(text, i):
    j = i
    while j < len(text) and text[j] not in _STOP:
        j += 1
    return text[i:j], j


def _make_term(name, value, quoted, start, chart, op=None):
    """Build the node for one term; `start` is the 1-based position of the term."""
    def bad(what):
        return QueryError("%s in '%s'" % (what, term_text), start)

    term_text = "%s%s%s" % (name, op or ":", value)
    if value == "":
        if quoted:
            raise bad("empty quotes")
        raise bad("missing value")
    if op is None:
        if name in ("payee", "narration"):
            return _Contains((name,), value)
        if name == "tag":
            return _Tag(value)
        if name == "date":
            try:
                return _InPeriod(Period.parse(value))
            except DateError:
                raise bad("invalid period") from None
        if name == "flag":
            if value not in ("*", "!"):
                raise bad("invalid flag, expected * or !")
            return _Flag(value)
        if name == "id":
            if not re.fullmatch(r"[0-9]+", value):
                raise bad("invalid id, expected digits")
            return _Id(int(value))
        if name == "account":
            parts = _compile_pattern(value)
            if parts is None:
                raise bad("invalid account pattern")
            if chart is not None and not any(_pattern_matches(parts, a.path) for a in chart.accounts()):
                raise QueryError("no account matches '%s'" % term_text, start)
            return _Account(parts)
        raise AssertionError(name)  # pragma: no cover
    if name == "date":
        try:
            return _DateCmp(op, parse_date(value))
        except DateError:
            raise bad("invalid date") from None
    # amount
    m = _AMOUNT_RE.fullmatch(value) if not quoted else None
    if m is None:
        raise bad("invalid amount")
    number, code = m.groups()
    if code:
        if not re.fullmatch(r"[A-Z]{3}", code) or not is_currency(code):
            raise bad("invalid currency")
    return _AmountCmp(op, Fraction(number), code or None)


def _lex(text, chart):
    """The tokens of the query; a mistake becomes an "error" token where it stands."""
    tokens = []
    i, n = 0, len(text)
    try:
        while i < n:
            c = text[i]
            if c in _SPACES:
                i += 1
                continue
            start = i + 1
            if c in "()":
                tokens.append(_Token(c, start))
                i += 1
                continue
            if c == '"':
                value, i = _read_quoted(text, i)
                if value == "":
                    raise QueryError("empty quotes", start)
                tokens.append(_Token("term", start, _Contains(("payee", "narration"), value)))
                continue
            m = _NAME_RE.match(text, i)
            if m:
                name = m.group(0).lower()
                j = m.end()
                if j < n and text[j] == ":":
                    if name not in _NAMES:
                        raise QueryError("unknown name '%s'" % m.group(0), start)
                    j += 1
                    if j < n and text[j] == '"':
                        value, i = _read_quoted(text, j)
                        quoted = True
                    else:
                        value, i = _read_bare(text, j)
                        quoted = False
                    tokens.append(_Token("term", start, _make_term(name, value, quoted, start, chart)))
                    continue
                if name in _COMPARABLE:
                    k = j
                    while k < n and text[k] in _SPACES:
                        k += 1
                    om = _OP_RE.match(text, k)
                    if om:
                        k = om.end()
                        while k < n and text[k] in _SPACES:
                            k += 1
                        value, i = _read_bare(text, k)
                        tokens.append(_Token("term", start,
                                             _make_term(name, value, False, start, chart, om.group(0))))
                        continue
            word, i = _read_bare(text, i)
            if word.lower() in _KEYWORDS:
                tokens.append(_Token(word.lower(), start))
            else:
                tokens.append(_Token("term", start, _Contains(("payee", "narration"), word)))
    except QueryError as e:
        tokens.append(_Token("error", e.position, error=e))
        return tokens
    tokens.append(_Token("end", n + 1))
    return tokens


# ---------------------------------------------------------------- the parser


class _Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.i = 0

    def peek(self):
        tok = self.tokens[self.i]
        if tok.kind == "error":
            raise tok.error
        return tok

    def take(self):
        tok = self.peek()
        self.i += 1
        return tok

    def parse(self):
        node = self.parse_or()
        tok = self.peek()
        if tok.kind == ")":
            raise QueryError("')' without a matching '('", tok.pos)
        if tok.kind != "end":  # pragma: no cover - cannot happen
            raise QueryError("unexpected text", tok.pos)
        return node

    def parse_or(self):
        node = self.parse_and()
        while self.peek().kind == "or":
            self.take()
            node = _Or(node, self.parse_and())
        return node

    def parse_and(self):
        node = self.parse_not()
        while True:
            kind = self.peek().kind
            if kind == "and":
                self.take()
            elif kind not in ("term", "not", "("):
                return node
            node = _And(node, self.parse_not())

    def parse_not(self):
        if self.peek().kind == "not":
            self.take()
            return _Not(self.parse_not())
        return self.parse_primary()

    def parse_primary(self):
        tok = self.take()
        if tok.kind == "term":
            return tok.node
        if tok.kind == "(":
            node = self.parse_or()
            close = self.peek()
            if close.kind != ")":
                raise QueryError("'(' is never closed", tok.pos)
            self.take()
            return node
        if tok.kind == "end":
            raise QueryError("expected a term but the query ends", tok.pos)
        raise QueryError("expected a term but found '%s'" % tok.kind, tok.pos)


# ----------------------------------------------------------------- the query


class Query:
    """A parsed query; use `parse_query` to make one."""

    def __init__(self, text, chart=None):
        if not isinstance(text, str):
            raise QueryError("a query must be text, got %r" % (text,), 1)
        self.text = text
        tokens = _lex(text, chart)
        if len(tokens) == 1 and tokens[0].kind == "end":
            self._root = None
        else:
            self._root = _Parser(tokens).parse()

    @property
    def is_empty(self):
        return self._root is None

    def __repr__(self):
        return "Query(%r)" % (self.text,)

    def __eq__(self, other):
        return isinstance(other, Query) and other.text == self.text

    def __hash__(self):
        return hash(self.text)

    def matching_postings(self, tx):
        postings = list(tx.postings)
        if self._root is None:
            return postings
        return [p for p in postings if self._root.eval(tx, p)]

    def matches(self, tx):
        if self._root is None:
            return True
        return any(self._root.eval(tx, p) for p in tx.postings)


def parse_query(text, chart=None):
    return Query(text, chart)


def select(transactions, q):
    if not isinstance(q, Query):
        q = parse_query(q)
    return [tx for tx in transactions if q.matches(tx)]

"""A small, strict command-line parser for tallybook."""

import re


class UsageError(Exception):
    """The command line itself is wrong (exit status 2)."""


class Fail(Exception):
    """The program refuses (exit status 1)."""

    def __init__(self, message, extra=()):
        super().__init__(message)
        self.extra = list(extra)


class HelpRequested(Exception):
    def __init__(self, text):
        super().__init__(text)
        self.text = text


class Command:
    def __init__(self, words, pos=(), opts=None, required=(), handler=None, book=True, summary=""):
        self.words = tuple(words)
        self.pos = list(pos)          # names; "X?" optional, "X..." one or more, "X*" zero or more
        self.opts = dict(opts or {})  # "--name": "value" | "flag" | "multi"
        self.required = set(required)
        self.handler = handler
        self.book = book
        self.summary = summary

    def usage(self):
        parts = ["usage: tallybook"] + list(self.words)
        for p in self.pos:
            if p.endswith("?"):
                parts.append("[%s]" % p[:-1])
            elif p.endswith("..."):
                parts.append("%s ..." % p[:-3])
            elif p.endswith("*"):
                parts.append("[%s ...]" % p[:-1])
            else:
                parts.append(p)
        for name, kind in self.opts.items():
            meta = OPTION_META.get(name, "VALUE")
            if kind == "flag":
                text = name
            else:
                text = "%s %s" % (name, meta)
            if name == "--posting":
                text = "-p POSTING"
            if kind == "multi":
                text = "[%s]..." % text
            elif name not in self.required:
                text = "[%s]" % text
            parts.append(text)
        return " ".join(parts)


OPTION_META = {
    "--currency": "CUR", "--open": "DATE", "--note": "TEXT", "--type": "TYPE", "--under": "PATH",
    "--on": "DATE", "--date": "DATE", "--narration": "TEXT", "--flag": "F", "--tag": "TAG", "--posting": "POSTING",
    "--query": "QUERY", "--limit": "N", "--offset": "N", "--format": "csv|json|journal", "--profile": "NAME",
    "--profile-file": "FILE", "--per": "KIND", "--start": "DATE", "--end": "DATE", "--count": "N",
    "--period": "PERIOD", "--upto": "DATE", "--as-of": "DATE", "--convert": "CUR", "--host": "HOST",
    "--port": "N", "--from": "D", "--to": "D", "--payee": "TEXT", "--amount": "MONEY", "--journal": "FILE",
    "--rules": "FILE",
}


def parse_command_args(cmd, args):
    """Read the arguments after the command words into (positionals, options)."""
    positional = []
    options = {}
    i = 0
    n = len(args)
    ended = False
    while i < n:
        a = args[i]
        i += 1
        if ended:
            positional.append(a)
            continue
        if a == "--":
            ended = True
            continue
        if a == "-p":
            name, value, has_value = "--posting", None, False
        elif a.startswith("--"):
            if "=" in a:
                name, value = a.split("=", 1)
                has_value = True
            else:
                name, value, has_value = a, None, False
        else:
            positional.append(a)
            continue
        kind = cmd.opts.get(name)
        if kind is None:
            raise UsageError("unknown option %s for '%s'" % (name, " ".join(cmd.words)))
        if kind == "flag":
            if has_value:
                raise UsageError("option %s takes no value" % name)
            if name in options:
                raise UsageError("option %s given twice" % name)
            options[name] = True
            continue
        if not has_value:
            if i >= n:
                raise UsageError("option %s needs a value" % (a if a != "-p" else "-p"))
            value = args[i]
            i += 1
        if kind == "multi":
            options.setdefault(name, []).append(value)
        else:
            if name in options:
                raise UsageError("option %s given twice" % name)
            options[name] = value
    # positionals
    out = {}
    j = 0
    for k, p in enumerate(cmd.pos):
        if p.endswith("..."):
            rest = positional[j:]
            if not rest:
                raise UsageError("missing argument %s" % p[:-3])
            out[p[:-3]] = rest
            j = len(positional)
        elif p.endswith("*"):
            out[p[:-1]] = positional[j:]
            j = len(positional)
        elif p.endswith("?"):
            if j < len(positional):
                out[p[:-1]] = positional[j]
                j += 1
            else:
                out[p[:-1]] = None
        else:
            if j >= len(positional):
                raise UsageError("missing argument %s" % p)
            out[p] = positional[j]
            j += 1
    if j < len(positional):
        raise UsageError("unexpected argument %r" % positional[j])
    for name in cmd.required:
        if name not in options:
            raise UsageError("missing required option %s" % name)
    return out, options


_INT_RE = re.compile(r"-?[0-9]{1,18}")


def whole(text, what="number", negative=False, low=None, high=None):
    if not isinstance(text, str) or not _INT_RE.fullmatch(text):
        raise Fail("invalid %s '%s': expected a whole number" % (what, text))
    value = int(text)
    if value < 0 and not negative:
        raise Fail("invalid %s '%s': must not be negative" % (what, text))
    if low is not None and value < low:
        raise Fail("invalid %s '%s': must be at least %d" % (what, text, low))
    if high is not None and value > high:
        raise Fail("invalid %s '%s': must be at most %d" % (what, text, high))
    return value
