    # every handler gets (store, verb, captured, pieces, query, body) and returns a _Response
    def health(self, s, verb, cap, pieces, q, body):
        return _json(200, {"status": "ok", "version": tallybook.__version__, "schema_version": s.version})

    def accounts(self, s, verb, cap, pieces, q, body):
        if verb == "GET":
            include = _yes_no(q["include_closed"], "include_closed") if "include_closed" in q else True
            accs = s.accounts(type=q.get("type"), under=q.get("under"), currency=q.get("currency"),
                              include_closed=include)
            return _json(200, [account_to_dict(a) for a in accs])
        f = _Fields(body, ("path", "type", "currency", "opened", "note"))
        path = f.get("path", str, True)
        acc = s.add_account(path, type=f.get("type", str), currency=f.get("currency", str),
                            opened=f.date("opened"), note=f.get("note", str) or "")
        return _json(201, account_to_dict(acc))

    def account(self, s, verb, cap, pieces, q, body):
        return _json(200, account_to_dict(s.get_account(cap[0])))

    def account_close(self, s, verb, cap, pieces, q, body):
        f = _Fields(body, ("on",))
        on = f.date("on")
        acc = s.close_account(cap[0], on if on is not None else self.today())
        return _json(200, account_to_dict(acc))

    def transactions(self, s, verb, cap, pieces, q, body):
        if verb == "GET":
            text = q.get("q") or None
            limit = _whole(q["limit"], "limit") if "limit" in q else None
            offset = _whole(q["offset"], "offset") if "offset" in q else 0
            total = s.count_transactions(text)
            items = s.transactions(text, limit=limit, offset=offset)
            return _json(200, {"items": [transaction_to_dict(t) for t in items], "total": total,
                               "limit": limit, "offset": offset})
        tx = _transaction_from(body)
        return _json(201, transaction_to_dict(s.add_transaction(tx)))

    def transaction(self, s, verb, cap, pieces, q, body):
        text = cap[0]
        if not re.fullmatch(r"[0-9]+", text):
            raise NotFoundError("no such transaction %s" % text)
        tid = int(text)
        if verb == "DELETE":
            return _json(200, transaction_to_dict(s.delete_transaction(tid)))
        return _json(200, transaction_to_dict(s.get_transaction(tid)))

    def rates(self, s, verb, cap, pieces, q, body):
        if verb == "GET":
            return _json(200, [rate_to_dict(*r) for r in s.rate_rows()])
        if verb == "DELETE":
            src, dst = _need(q, "src"), _need(q, "dst")
            on = parse_date(_need(q, "date"))
            text = None
            for r in s.rate_rows():
                if r[0] == src and r[1] == dst and r[2] == on:
                    text = r[3]
            s.remove_rate(src, dst, on)
            return _json(200, rate_to_dict(src, dst, on, text))
        f = _Fields(body, ("src", "dst", "date", "rate"))
        src = f.get("src", str, True)
        dst = f.get("dst", str, True)
        on = f.date("date", True)
        rate = f.get("rate", str, True)
        s.set_rate(src, dst, rate, on)
        return _json(200, rate_to_dict(src, dst, on, rate))

    def budgets(self, s, verb, cap, pieces, q, body):
        from tallybook.budgets import Budget
        if verb == "GET":
            return _json(200, [budget_to_dict(b) for b in s.budgets()])
        if verb == "DELETE":
            pattern, kind = _need(q, "pattern"), _need(q, "period_kind")
            return _json(200, budget_to_dict(s.remove_budget(pattern, kind)))
        f = _Fields(body, ("pattern", "period_kind", "amount", "start"))
        pattern = f.get("pattern", str, True)
        kind = f.get("period_kind", str, True)
        amount = _money(f.get("amount", None, True), "amount")
        start = f.date("start", True)
        return _json(201, budget_to_dict(s.add_budget(Budget(pattern, kind, amount, start))))

    def budget_status(self, s, verb, cap, pieces, q, body):
        from tallybook.budgets import budget_status
        period = Period.parse(_need(q, "period"))
        lines = budget_status(s.budgets(), s.ledger(), period)
        return _json(200, [line.to_dict() for line in lines])

    def recurring(self, s, verb, cap, pieces, q, body):
        from tallybook.recurring import Recurring
        if verb == "GET":
            return _json(200, [recurring_to_dict(r) for r in s.recurring()])
        if verb == "DELETE":
            return _json(200, recurring_to_dict(s.remove_recurring(_need(q, "name"))))
        f = _Fields(body, ("name", "schedule", "start", "end", "count", "template"))
        name = f.get("name", None, True)
        schedule = f.get("schedule", str, True)
        start = f.date("start", True)
        end = f.date("end")
        count = f.get("count")
        template = _template_from(f.get("template", dict, True))
        rec = Recurring(name, schedule, template, start, end=end, count=count)
        return _json(201, recurring_to_dict(s.add_recurring(rec)))

    def materialize(self, s, verb, cap, pieces, q, body):
        f = _Fields(body, ("upto",))
        upto = f.date("upto")
        added = s.materialize(upto=upto, today=self.today())
        return _json(200, {"added": [transaction_to_dict(t) for t in added]})

    def import_(self, s, verb, cap, pieces, q, body):
        if isinstance(body, dict):
            f = _Fields(body, ("csv", "profile", "apply_rules"))
            text = f.get("csv", str, True)
            profile = f.get("profile", str, True)
            apply_rules = f.get("apply_rules", bool)
            apply_rules = True if apply_rules is None else apply_rules
        else:
            text = body
            profile = _need(q, "profile")
            apply_rules = _yes_no(q["apply_rules"], "apply_rules") if "apply_rules" in q else True
        outcome = s.import_csv(text, profile, apply_rules=apply_rules)
        if outcome.errors:
            raise ValidationError("import failed: " + "; ".join("row %s: %s" % (row, msg)
                                                                for row, msg in outcome.errors))
        return _json(200, {"added": [transaction_to_dict(t) for t in outcome.added],
                           "duplicates": [transaction_to_dict(t) for t in outcome.duplicates]})

    def rules(self, s, verb, cap, pieces, q, body):
        if verb == "PUT":
            f = _Fields(body, ("rules",))
            s.set_rules(f.get("rules", str, True))
        return _json(200, {"rules": s.rules_text()})

    def export(self, s, verb, cap, pieces, q, body):
        fmt = _format(q, ("json", "csv", "journal"))
        if fmt == "journal":
            from tallybook.journal import format_journal
            return _text(format_journal(s.journal()))
        txs = s.transactions()
        if fmt == "csv":
            return _text(transactions_to_csv(txs), "text/csv; charset=utf-8")
        return _json(200, [transaction_to_dict(t) for t in txs])

    def report(self, s, verb, cap, pieces, q, body):
        from tallybook import reports
        name = pieces[1]
        fmt = _format(q, ("json", "text"))

        def date_param(key):
            return parse_date(q[key]) if key in q else None

        def period_param(required):
            if required:
                return Period.parse(_need(q, "period"))
            return Period.parse(q["period"]) if "period" in q else None

        convert_to = q.get("convert_to")
        if name == "trial-balance":
            as_of = date_param("as_of")
            report = reports.trial_balance(s.ledger(), as_of)
        elif name == "balance-sheet":
            as_of = date_param("as_of")
            report = reports.balance_sheet(s.ledger(), as_of, convert_to, today=self.today())
        elif name == "income-statement":
            period = period_param(True)
            report = reports.income_statement(s.ledger(), period, convert_to)
        elif name == "cashflow":
            period = period_param(True)
            report = reports.cashflow(s.ledger(), period)
        else:
            account = _need(q, "account")
            period = period_param(False)
            rollup = _yes_no(q["rollup"], "rollup") if "rollup" in q else False
            report = reports.register(s.ledger(), account, period, rollup)
        if fmt == "text":
            return _text(reports.render_text(report))
        return _json(200, report)


class _Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"
    server_version = "tallybook/" + tallybook.__version__
    sys_version = ""
    app = None  # set on a subclass by make_server

    def log_message(self, format, *args):
        pass

    def __getattr__(self, name):
        # every verb, known or not, goes through the same dispatcher
        if name.startswith("do_"):
            return self._dispatch
        raise AttributeError(name)

    # ---------------------------------------------------------------- output
    def _send(self, status, body, ctype="application/json; charset=utf-8", headers=()):
        self.close_connection = True
        try:
            self.send_response(status)
            self.send_header("Content-Type", ctype)
            self.send_header("Content-Length", str(len(body)))
            for k, v in headers:
                self.send_header(k, v)
            self.send_header("Connection", "close")
            self.end_headers()
            if self.command != "HEAD" and body:
                self.wfile.write(body)
            self.wfile.flush()
        except (OSError, ValueError):
            pass

    def _send_error_json(self, status, message, headers=()):
        self._send(status, to_json({"error": message or "error"}).encode("utf-8"), headers=headers)

    def send_error(self, code, message=None, explain=None):
        # used by http.server itself for request lines it cannot read
        if not message:
            message = {400: "bad request", 414: "request line too long", 431: "request headers too large",
                       505: "HTTP version not supported"}.get(code, "request error %d" % code)
        if code == 501:
            code = 400
        if self.request_version == "HTTP/0.9":  # always answer with a status line and headers
            self.request_version = "HTTP/1.0"
        self._send_error_json(code, message)

    # ------------------------------------------------------------------ body
    def _drain(self, n):
        while n > 0:
            chunk = self.rfile.read(min(n, 65536))
            if not chunk:
                break
            n -= len(chunk)

    def _read_body(self):
        raw = self.headers.get("Content-Length")
        if raw is None:
            return b""
        raw = raw.strip()
        if not re.fullmatch(r"[0-9]+", raw):
            raise _Answer(400, "invalid Content-Length %r" % raw)
        n = int(raw)
        if n > MAX_BODY:
            if n <= _DRAIN_LIMIT:
                self._drain(n)
            raise _Answer(413, "request body too large: %d bytes, at most %d" % (n, MAX_BODY))
        data = b""
        while len(data) < n:
            chunk = self.rfile.read(n - len(data))
            if not chunk:
                break
            data += chunk
        return data

    # -------------------------------------------------------------- dispatch
    def _dispatch(self):
        try:
            response = self._handle()
        except _Answer as a:
            self._send_error_json(a.status, a.message, a.headers)
            return
        except TallybookError as e:
            self._send_error_json(_STATUS.get(e.code, 400), e.message or e.code)
            return
        except Exception as e:  # anything unexpected: a 500, nothing printed
            self._send_error_json(500, "internal error: %s" % (str(e) or type(e).__name__))
            return
        self._send(response.status, response.body, response.ctype)

    def _handle(self):
        verb = self.command
        pieces, query = _split_path(self.path)
        found = _route(pieces) if pieces is not None else None
        if found is None:
            self._read_body_quietly()
            raise _Answer(404, "no such path: %s" % self.path.split("?", 1)[0].split("#", 1)[0])
        verbs, name, captured, pieces = found
        if verb not in verbs:
            self._read_body_quietly()
            raise _Answer(405, "method %s not allowed here" % verb, [("Allow", ", ".join(sorted(verbs)))])
        data = self._read_body()
        body = None
        if verb in ("POST", "PUT"):
            ctype = _content_type(self.headers.get("Content-Type"))
            if name == "import":
                if not data:
                    body = ""
                elif ctype in ("text/csv", "text/plain"):
                    body = self._decode(data)
                elif ctype == "application/json":
                    body = self._parse_json(data)
                else:
                    raise _Answer(415, "unsupported content type %s: send application/json, text/csv or "
                                       "text/plain" % (ctype or "(none)"))
            else:
                if data and ctype != "application/json":
                    raise _Answer(415, "unsupported content type %s: send application/json" % (ctype or "(none)"))
                body = self._parse_json(data) if data else {}
        app = self.app
        method = getattr(app, "import_" if name == "import" else name)
        store = Store.open(app.db_path)
        try:
            return method(store, verb, captured, pieces, query, body)
        finally:
            store.close()

    def _read_body_quietly(self):
        try:
            self._read_body()
        except _Answer:
            pass

    @staticmethod
    def _decode(data):
        try:
            return data.decode("utf-8")
        except UnicodeDecodeError as e:
            raise ParseError("the body is not valid UTF-8: %s" % e) from None

    def _parse_json(self, data):
        text = self._decode(data)
        try:
            value = json.loads(text)
        except ValueError as e:
            raise ParseError("the body is not valid JSON: %s" % e) from None
        if not isinstance(value, dict):
            raise ValidationError("the body must be a JSON object")
        return value


class _Server(ThreadingHTTPServer):
    daemon_threads = True
    allow_reuse_address = True

    def handle_error(self, request, client_address):
        pass


def make_server(db_path, host="127.0.0.1", port=0, today=None):
    """Check the book and bind a server for it (not yet serving). Raises the storage error for a bad book."""
    if today is not None and (not isinstance(today, datetime.date) or isinstance(today, datetime.datetime)):
        raise ValidationError("invalid today %r: expected a date" % (today,))
    if not is_int(port) or not 0 <= port <= 65535:
        raise ValidationError("invalid port %r: expected 0 to 65535" % (port,))
    store = Store.open(db_path)
    try:
        store.info()
    finally:
        store.close()
    handler = type("Handler", (_Handler,), {"app": _App(db_path, today)})
    try:
        return _Server((host, port), handler)
    except OSError as e:
        raise ConflictError("cannot listen on %s:%s: %s" % (host, port, e.strerror or e)) from None


def serve(db_path, host="127.0.0.1", port=0, today=None):
    """Serve the book at db_path until SIGINT or SIGTERM; returns 0 (the exit status)."""
    server = make_server(db_path, host, port, today)
    previous = {}
    stopping = []

    def stop(signum, frame):
        if not stopping:
            stopping.append(signum)
            # shutdown() waits for serve_forever to finish, so it must run in another thread
            threading.Thread(target=server.shutdown, daemon=True).start()

    try:
        if threading.current_thread() is threading.main_thread():
            for sig in (signal.SIGINT, signal.SIGTERM):
                previous[sig] = signal.signal(sig, stop)
        sys.stdout.write("tallybook listening on http://%s:%d\n" % (host, server.server_address[1]))
        sys.stdout.flush()
        try:
            server.serve_forever()
        except KeyboardInterrupt:
            pass
    finally:
        server.server_close()
        for sig, handler in previous.items():
            signal.signal(sig, handler)
    return 0

"""Budgets: allowances per calendar period and how spending compares."""

import datetime
import decimal
import re
from fractions import Fraction

from tallybook.dates import Period, last_day
from tallybook.errors import ValidationError
from tallybook.money import Money, round_div

__all__ = ["Budget", "BudgetError", "BudgetLine", "budget_status"]

PERIOD_KINDS = ("month", "quarter", "year")
_KIND_ORDER = {"month": 0, "quarter": 1, "year": 2}
_SEGMENT_RE = re.compile(r"[A-Z][A-Za-z0-9_-]*")


class BudgetError(ValidationError):
    """A malformed budget or budget request."""


def _is_date(value):
    return isinstance(value, datetime.date) and not isinstance(value, datetime.datetime)


def _check_pattern(pattern):
    if not isinstance(pattern, str):
        raise BudgetError("invalid budget pattern %r: expected text" % (pattern,))
    if not pattern:
        raise BudgetError("invalid budget pattern '': it is empty")
    for seg in pattern.split(":"):
        if seg != "*" and not _SEGMENT_RE.fullmatch(seg):
            raise BudgetError("invalid budget pattern '%s': each segment is '*' or an account name segment"
                              % pattern)


def _pattern_matches(segs, path):
    parts = path.split(":")
    if len(parts) < len(segs):
        return False
    return all(s == "*" or s == p for s, p in zip(segs, parts))


class Budget:
    __slots__ = ("_pattern", "_period_kind", "_amount", "_start")

    def __init__(self, pattern, period_kind, amount, start):
        _check_pattern(pattern)
        if not isinstance(period_kind, str) or period_kind not in PERIOD_KINDS:
            raise BudgetError("invalid budget period kind %r: expected month, quarter or year" % (period_kind,))
        if not isinstance(amount, Money):
            raise BudgetError("invalid budget amount %r: expected Money" % (amount,))
        if amount.minor <= 0:
            raise BudgetError("invalid budget amount %s: it must be greater than zero" % (amount,))
        if not _is_date(start):
            raise BudgetError("invalid budget start %r: expected a date" % (start,))
        object.__setattr__(self, "_pattern", pattern)
        object.__setattr__(self, "_period_kind", period_kind)
        object.__setattr__(self, "_amount", amount)
        object.__setattr__(self, "_start", start)

    pattern = property(lambda self: self._pattern)
    period_kind = property(lambda self: self._period_kind)
    amount = property(lambda self: self._amount)
    start = property(lambda self: self._start)

    def __setattr__(self, name, value):
        raise AttributeError("Budget is immutable")

    def __delattr__(self, name):
        raise AttributeError("Budget is immutable")

    def __reduce__(self):
        return (Budget, (self._pattern, self._period_kind, self._amount, self._start))

    def _key(self):
        return (self._pattern, self._period_kind, self._amount, self._start)

    def __eq__(self, other):
        if not isinstance(other, Budget):
            return NotImplemented
        return self._key() == other._key()

    def __ne__(self, other):
        r = self.__eq__(other)
        return r if r is NotImplemented else not r

    def __hash__(self):
        return hash(self._key())

    def __repr__(self):
        return "Budget(%r, %r, %r, %r)" % self._key()


def _calendar_period(d, kind):
    if kind == "month":
        return datetime.date(d.year, d.month, 1), datetime.date(d.year, d.month, last_day(d.year, d.month))
    if kind == "quarter":
        mo = (d.month - 1) // 3 * 3 + 1
        return datetime.date(d.year, mo, 1), datetime.date(d.year, mo + 2, last_day(d.year, mo + 2))
    return datetime.date(d.year, 1, 1), datetime.date(d.year, 12, 31)


def _allowance_fraction(budget, period):
    """Sum of overlapping-days / days for each calendar period in force, or None if not in force."""
    first_start, _ = _calendar_period(budget.start, budget.period_kind)
    if first_start > period.end:
        return None
    total = Fraction(0)
    d = max(first_start, period.start)
    while d <= period.end:
        ps, pe = _calendar_period(d, budget.period_kind)
        lo = max(ps, period.start)
        hi = min(pe, period.end)
        total += Fraction((hi - lo).days + 1, (pe - ps).days + 1)
        if pe >= period.end:
            break
        d = pe + datetime.timedelta(days=1)
    return total


def _percent(actual, allowance):
    if allowance == 0:
        tenths = 0 if actual == 0 else 1000
    else:
        tenths = round_div(actual * 1000, allowance)
    sign = "-" if tenths < 0 else ""
    q, r = divmod(abs(tenths), 10)
    return decimal.Decimal("%s%d.%d" % (sign, q, r))


class BudgetLine:
    __slots__ = ("_pattern", "_period_kind", "_budget", "_actual", "_remaining", "_percent", "_over", "_accounts")
    _FIELDS = ("pattern", "period_kind", "budget", "actual", "remaining", "percent", "over", "accounts")

    def __init__(self, pattern, period_kind, budget, actual, remaining, percent, over, accounts):
        for name, value in zip(self._FIELDS, (pattern, period_kind, budget, actual, remaining, percent, over,
                                              tuple(tuple(a) for a in accounts))):
            object.__setattr__(self, "_" + name, value)

    pattern = property(lambda self: self._pattern)
    period_kind = property(lambda self: self._period_kind)
    budget = property(lambda self: self._budget)
    actual = property(lambda self: self._actual)
    remaining = property(lambda self: self._remaining)
    percent = property(lambda self: self._percent)
    over = property(lambda self: self._over)
    accounts = property(lambda self: self._accounts)

    def __setattr__(self, name, value):
        raise AttributeError("BudgetLine is immutable")

    def __delattr__(self, name):
        raise AttributeError("BudgetLine is immutable")

    def _key(self):
        return tuple(getattr(self, "_" + f) for f in self._FIELDS)

    def __reduce__(self):
        return (BudgetLine, self._key())

    def __eq__(self, other):
        if not isinstance(other, BudgetLine):
            return NotImplemented
        return self._key() == other._key()

    def __ne__(self, other):
        r = self.__eq__(other)
        return r if r is NotImplemented else not r

    def __hash__(self):
        return hash(self._key())

    def __repr__(self):
        return "BudgetLine(%s)" % ", ".join("%s=%r" % (f, getattr(self, f)) for f in self._FIELDS)

    def to_dict(self):
        def money(m):
            return {"amount": m.amount_str(), "currency": m.currency}
        return {
            "pattern": self._pattern,
            "period_kind": self._period_kind,
            "budget": money(self._budget),
            "actual": money(self._actual),
            "remaining": money(self._remaining),
            "percent": str(self._percent),
            "over": bool(self._over),
            "accounts": [{"account": a, "amount": money(m)} for a, m in self._accounts],
        }


def budget_status(budgets, ledger, period):
    if isinstance(budgets, (str, bytes)):
        raise BudgetError("budgets must be a list of Budget")
    try:
        budgets = list(budgets)
    except TypeError:
        raise BudgetError("budgets must be a list of Budget") from None
    for b in budgets:
        if not isinstance(b, Budget):
            raise BudgetError("not a budget: %r" % (b,))
    if not isinstance(period, Period):
        raise BudgetError("invalid period %r: expected a Period" % (period,))

    # Expense postings within the period, per account and currency.
    spending = {}
    for tx, p in ledger.postings():
        if not (period.start <= tx.date <= period.end):
            continue
        if p.amount is None or p.account.split(":", 1)[0] != "Expenses":
            continue
        key = (p.account, p.amount.currency)
        spending[key] = spending.get(key, 0) + p.amount.minor

    order = sorted(range(len(budgets)),
                   key=lambda i: (budgets[i].pattern, _KIND_ORDER[budgets[i].period_kind], budgets[i].start, i))
    lines = []
    for i in order:
        b = budgets[i]
        frac = _allowance_fraction(b, period)
        if frac is None:
            continue
        code = b.amount.currency
        scaled = frac * b.amount.minor
        allowance = round_div(scaled.numerator, scaled.denominator)
        segs = b.pattern.split(":")
        per_account = {}
        for (account, cur), minor in spending.items():
            if cur == code and _pattern_matches(segs, account):
                per_account[account] = per_account.get(account, 0) + minor
        actual = sum(per_account.values())
        accounts = tuple((a, Money(v, code)) for a, v in sorted(per_account.items()) if v != 0)
        lines.append(BudgetLine(b.pattern, b.period_kind, Money(allowance, code), Money(actual, code),
                                Money(allowance - actual, code), _percent(actual, allowance),
                                actual > allowance, accounts))
    return lines

"""Recurring transactions: schedules in words and dated copies of a template."""

import datetime
import re

from tallybook.dates import DateError, add_months, last_day, parse_date
from tallybook.errors import ValidationError, is_int
from tallybook.model import Transaction

__all__ = ["Schedule", "Recurring", "RecurringError", "parse_schedule", "occurrences", "expand",
           "instantiate", "next_occurrence", "describe"]


class RecurringError(ValidationError):
    """A malformed schedule or recurring item."""


SHAPES = ("daily, weekly on DAY (mon..sun), monthly on N (1-31), monthly on last, yearly on MM-DD, "
          "every N days|weeks|months|years from YYYY-MM-DD")

_WEEKDAYS = ("mon", "tue", "wed", "thu", "fri", "sat", "sun")
_WEEKDAY_NAMES = ("Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday")
_MONTH_NAMES = ("January", "February", "March", "April", "May", "June", "July", "August", "September",
                "October", "November", "December")
_UNITS = {"day": "day", "days": "day", "week": "week", "weeks": "week",
          "month": "month", "months": "month", "year": "year", "years": "year"}
_NAME_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]*")
_MIN_ORD = datetime.date.min.toordinal()
_MAX_ORD = datetime.date.max.toordinal()


def _is_date(value):
    return isinstance(value, datetime.date) and not isinstance(value, datetime.datetime)


def _ceil_div(a, b):
    return -((-a) // b)


class Schedule:
    """A rhythm of dates. Build one with parse_schedule.

    kind is one of daily, weekly (value: weekday 0-6), monthly (value: 1-31 or "last"),
    yearly (value: (month, day)), every (value: (n, unit, from_date)).
    """

    __slots__ = ("_kind", "_value")

    def __init__(self, kind, value=None):
        object.__setattr__(self, "_kind", kind)
        object.__setattr__(self, "_value", value)

    kind = property(lambda self: self._kind)
    value = property(lambda self: self._value)

    def __setattr__(self, name, value):
        raise AttributeError("Schedule is immutable")

    def __delattr__(self, name):
        raise AttributeError("Schedule is immutable")

    def __reduce__(self):
        return (parse_schedule, (str(self),))

    def __eq__(self, other):
        if not isinstance(other, Schedule):
            return NotImplemented
        return self._kind == other._kind and self._value == other._value

    def __ne__(self, other):
        r = self.__eq__(other)
        return r if r is NotImplemented else not r

    def __hash__(self):
        return hash((self._kind, self._value))

    def __str__(self):
        k, v = self._kind, self._value
        if k == "daily":
            return "daily"
        if k == "weekly":
            return "weekly on %s" % _WEEKDAYS[v]
        if k == "monthly":
            return "monthly on %s" % v
        if k == "yearly":
            return "yearly on %02d-%02d" % v
        n, unit, frm = v
        return "every %d %s from %s" % (n, unit if n == 1 else unit + "s", frm.isoformat())

    def __repr__(self):
        return "Schedule(%r)" % str(self)

    # ------------------------------------------------------------ index model
    # The schedule's dates are indexed by integers k, ascending in k. _date(k)
    # returns the k-th date or None when it is outside the date range;
    # _index_ge(d) returns the smallest index whose date is >= d.

    def _date(self, k):
        kd, v = self._kind, self._value
        try:
            if kd == "daily":
                if not _MIN_ORD <= k <= _MAX_ORD:
                    return None
                return datetime.date.fromordinal(k)
            if kd == "weekly":
                o = 7 * k + 1 + v
                if not _MIN_ORD <= o <= _MAX_ORD:
                    return None
                return datetime.date.fromordinal(o)
            if kd == "monthly":
                y, m = divmod(k, 12)
                m += 1
                if not 1 <= y <= 9999:
                    return None
                ld = last_day(y, m)
                return datetime.date(y, m, ld if v == "last" else min(v, ld))
            if kd == "yearly":
                if not 1 <= k <= 9999:
                    return None
                mo, dd = v
                return datetime.date(k, mo, min(dd, last_day(k, mo)))
            n, unit, frm = v
            if k < 0:
                return None
            if unit in ("day", "week"):
                o = frm.toordinal() + k * n * (7 if unit == "week" else 1)
                if o > _MAX_ORD:
                    return None
                return datetime.date.fromordinal(o)
            months = k * n * (12 if unit == "year" else 1)
            if frm.year * 12 + frm.month - 1 + months > 9999 * 12 + 11:
                return None
            return add_months(frm, months)
        except (OverflowError, ValueError, DateError):
            return None

    def _index_ge(self, d):
        kd, v = self._kind, self._value
        if kd == "daily":
            return d.toordinal()
        if kd == "weekly":
            return _ceil_div(d.toordinal() - 1 - v, 7)
        if kd == "monthly":
            k = d.year * 12 + d.month - 1
        elif kd == "yearly":
            k = d.year
        else:
            n, unit, frm = v
            if d <= frm:
                return 0
            if unit in ("day", "week"):
                step = n * (7 if unit == "week" else 1)
                return _ceil_div(d.toordinal() - frm.toordinal(), step)
            step = n * (12 if unit == "year" else 1)
            diff = (d.year * 12 + d.month) - (frm.year * 12 + frm.month)
            k = max(0, diff // step)
            while k > 0:
                prev = self._date(k - 1)
                if prev is None or prev < d:
                    break
                k -= 1
        # Step forward while the k-th date is before d (at most a couple of times).
        while True:
            x = self._date(k)
            if x is None or x >= d:
                return k
            k += 1

    def _iter(self, lo, hi=None, kmax=None):
        """Dates of the schedule from index lo on, up to date hi and index kmax."""
        k = lo
        while kmax is None or k <= kmax:
            x = self._date(k)
            if x is None or (hi is not None and x > hi):
                return
            yield x
            k += 1

    def between(self, start, end):
        if not _is_date(start) or not _is_date(end):
            raise RecurringError("between needs two dates, got %r and %r" % (start, end))
        if end < start:
            return []
        return list(self._iter(self._index_ge(start), end))


def _bad(text):
    shown = "'%s'" % text if isinstance(text, str) else repr(text)
    return RecurringError("invalid schedule %s: expected one of %s" % (shown, SHAPES))


def parse_schedule(text):
    if isinstance(text, Schedule):
        return text
    if not isinstance(text, str):
        raise _bad(text)
    words = text.lower().split()
    if words == ["daily"]:
        return Schedule("daily")
    if len(words) == 3 and words[1] == "on":
        kind, _, arg = words
        if kind == "weekly" and arg in _WEEKDAYS:
            return Schedule("weekly", _WEEKDAYS.index(arg))
        if kind == "monthly":
            if arg == "last":
                return Schedule("monthly", "last")
            if re.fullmatch(r"[0-9]{1,2}", arg) and 1 <= int(arg) <= 31:
                return Schedule("monthly", int(arg))
        if kind == "yearly":
            m = re.fullmatch(r"([0-9]{2})-([0-9]{2})", arg)
            if m:
                mo, dd = int(m.group(1)), int(m.group(2))
                if 1 <= mo <= 12 and 1 <= dd <= last_day(2024, mo):
                    return Schedule("yearly", (mo, dd))
    if len(words) == 5 and words[0] == "every" and words[3] == "from":
        n, unit, frm = words[1], words[2], words[4]
        if re.fullmatch(r"[0-9]+", n) and int(n) >= 1 and unit in _UNITS:
            try:
                d = parse_date(frm)
            except DateError:
                d = None
            if d is not None:
                return Schedule("every", (int(n), _UNITS[unit], d))
    raise _bad(text)


def _ordinal(n):
    if 10 <= n % 100 <= 20:
        suffix = "th"
    else:
        suffix = {1: "st", 2: "nd", 3: "rd"}.get(n % 10, "th")
    return "%d%s" % (n, suffix)


def describe(schedule):
    s = parse_schedule(schedule)
    k, v = s.kind, s.value
    if k == "daily":
        return "every day"
    if k == "weekly":
        return "every %s" % _WEEKDAY_NAMES[v]
    if k == "monthly":
        if v == "last":
            return "on the last day of every month"
        return "on the %s of every month" % _ordinal(v)
    if k == "yearly":
        return "every year on %d %s" % (v[1], _MONTH_NAMES[v[0] - 1])
    n, unit, frm = v
    if n == 1:
        return "every %s from %s" % (unit, frm.isoformat())
    return "every %d %ss from %s" % (n, unit, frm.isoformat())


class Recurring:
    __slots__ = ("_name", "_schedule", "_template", "_start", "_end", "_count")

    def __init__(self, name, schedule, template, start, end=None, count=None):
        if not isinstance(name, str) or not _NAME_RE.fullmatch(name):
            raise RecurringError("invalid recurring name %s: use ASCII letters, digits, '-' and '_', "
                                 "not starting with '-' or '_'"
                                 % ("'%s'" % name if isinstance(name, str) else repr(name)))
        if isinstance(schedule, str):
            schedule = parse_schedule(schedule)
        elif not isinstance(schedule, Schedule):
            raise RecurringError("invalid schedule %r: expected a Schedule or text" % (schedule,))
        if not isinstance(template, Transaction):
            raise RecurringError("invalid template %r: expected a Transaction" % (template,))
        if not _is_date(start):
            raise RecurringError("invalid start %r: expected a date" % (start,))
        if end is not None:
            if not _is_date(end):
                raise RecurringError("invalid end %r: expected a date" % (end,))
            if end < start:
                raise RecurringError("end %s is before start %s" % (end.isoformat(), start.isoformat()))
        if count is not None and (not is_int(count) or count < 1):
            raise RecurringError("invalid count %r: expected a whole number of at least 1" % (count,))
        object.__setattr__(self, "_name", name)
        object.__setattr__(self, "_schedule", schedule)
        object.__setattr__(self, "_template", template)
        object.__setattr__(self, "_start", start)
        object.__setattr__(self, "_end", end)
        object.__setattr__(self, "_count", count)

    name = property(lambda self: self._name)
    schedule = property(lambda self: self._schedule)
    template = property(lambda self: self._template)
    start = property(lambda self: self._start)
    end = property(lambda self: self._end)
    count = property(lambda self: self._count)

    def __setattr__(self, name, value):
        raise AttributeError("Recurring is immutable")

    def __delattr__(self, name):
        raise AttributeError("Recurring is immutable")

    def _key(self):
        return (self._name, self._schedule, self._template, self._start, self._end, self._count)

    def __reduce__(self):
        return (Recurring, self._key())

    def __eq__(self, other):
        if not isinstance(other, Recurring):
            return NotImplemented
        return self._key() == other._key()

    def __ne__(self, other):
        r = self.__eq__(other)
        return r if r is NotImplemented else not r

    __hash__ = None  # the template is a mutable Transaction

    def __repr__(self):
        return "Recurring(%r, %r, %r, start=%r, end=%r, count=%r)" % (
            self._name, str(self._schedule), self._template, self._start, self._end, self._count)


def _check_rec(rec):
    if not isinstance(rec, Recurring):
        raise RecurringError("not a recurring item: %r" % (rec,))


def _series(rec, lo_date, hi_date):
    """Dates of rec's series that are >= lo_date and <= hi_date (hi_date may be None)."""
    s = rec.schedule
    if rec.end is not None and (hi_date is None or rec.end < hi_date):
        hi_date = rec.end
    kmax = None
    if rec.count is not None:
        kmax = s._index_ge(rec.start) + rec.count - 1
    lo = s._index_ge(max(lo_date, rec.start))
    return s._iter(lo, hi_date, kmax)


def occurrences(rec, start, end):
    _check_rec(rec)
    if not _is_date(start) or not _is_date(end):
        raise RecurringError("occurrences needs two dates, got %r and %r" % (start, end))
    if end < start:
        return []
    return list(_series(rec, start, end))


def next_occurrence(rec, after):
    _check_rec(rec)
    if not _is_date(after):
        raise RecurringError("invalid date %r" % (after,))
    if after >= datetime.date.max:
        return None
    for d in _series(rec, after + datetime.timedelta(days=1), None):
        return d
    return None


def instantiate(rec, on):
    _check_rec(rec)
    if not _is_date(on):
        raise RecurringError("invalid date %r" % (on,))
    t = rec.template
    tags = tuple(sorted(set(tuple(t.tags) + ("recurring",))))
    return Transaction(on, t.payee, t.narration, list(t.postings), tags, t.flag, None)


def expand(recs, start, end):
    if isinstance(recs, (str, bytes)):
        raise RecurringError("expand needs a list of Recurring")
    recs = list(recs)
    for r in recs:
        _check_rec(r)
    if not _is_date(start) or not _is_date(end):
        raise RecurringError("expand needs two dates, got %r and %r" % (start, end))
    items = []
    for i, r in enumerate(recs):
        for d in occurrences(r, start, end):
            items.append((d, r.name, i))
    items.sort()
    return [instantiate(recs[i], d) for d, _, i in items]

"""Reports: trial balance, balance sheet, income statement, cash flow, register, net worth."""

import datetime

from tallybook.accounts import ROOT_TYPES
from tallybook.currency import currency as _currency
from tallybook.dates import Period, periods
from tallybook.errors import ValidationError
from tallybook.export import money_to_dict, render_table, to_csv
from tallybook.ledger import Ledger
from tallybook.money import Money, round_div

__all__ = ["trial_balance", "balance_sheet", "income_statement", "cashflow", "register", "net_worth",
           "render_text", "report_to_csv", "ReportError"]

REPORT_KINDS = ("trial_balance", "balance_sheet", "income_statement", "cashflow", "register", "net_worth")
STEPS = ("week", "month", "quarter", "year")


class ReportError(ValidationError):
    """A report that cannot be made or drawn."""


# ---------------------------------------------------------------- helpers
def _is_date(value):
    return isinstance(value, datetime.date) and not isinstance(value, datetime.datetime)


def _date_text(d):
    return None if d is None else "%04d-%02d-%02d" % (d.year, d.month, d.day)


def _check_ledger(ledger):
    if not isinstance(ledger, Ledger):
        raise ReportError("not a ledger: %r" % (ledger,))


def _check_as_of(as_of):
    if as_of is not None and not _is_date(as_of):
        raise ReportError("invalid date %r" % (as_of,))


def _check_period(period, optional=False):
    if period is None and optional:
        return
    if not isinstance(period, Period):
        raise ReportError("invalid period %r" % (period,))


def _check_convert_to(convert_to):
    if convert_to is not None:
        _currency(convert_to)  # CurrencyError as it is


def _type_of(path):
    return ROOT_TYPES.get(path.split(":", 1)[0])


def _m(minor, code):
    return money_to_dict(Money(minor, code))


def _money_list(sums, keep_zero):
    """A list of money dicts from {currency: minor}, sorted by currency."""
    return [_m(v, c) for c, v in sorted(sums.items()) if keep_zero or v != 0]


def _account_lines(sums):
    """Sorted (account, currency, minor) for non-zero entries of {(account, currency): minor}."""
    return [(a, c, v) for (a, c), v in sorted(sums.items()) if v != 0]


def _add(d, key, value):
    d[key] = d.get(key, 0) + value


def _percent(part, total):
    if total == 0:
        return "0.0"
    if total < 0:
        part, total = -part, -total
    tenths = round_div(part * 1000, total)
    if tenths == 0:
        return "0.0"
    sign = "-" if tenths < 0 else ""
    a = abs(tenths)
    return "%s%d.%d" % (sign, a // 10, a % 10)


def _convert(ledger, minor, code, convert_to, on):
    return ledger.rates.convert(Money(minor, code), convert_to, on)


# ------------------------------------------------------------ trial balance
def trial_balance(ledger, as_of=None):
    _check_ledger(ledger)
    _check_as_of(as_of)
    sums = {}
    for tx, p in ledger.postings():
        if as_of is not None and tx.date > as_of:
            continue
        _add(sums, (p.account, p.amount.currency), p.amount.minor)
    accounts = []
    totals = {}
    for account, cur, v in _account_lines(sums):
        t = totals.setdefault(cur, [0, 0])
        if v > 0:
            t[0] += v
        else:
            t[1] += -v
        accounts.append({"account": account, "type": _type_of(account),
                         "debit": _m(v, cur) if v > 0 else None,
                         "credit": _m(-v, cur) if v < 0 else None})
    return {"report": "trial_balance", "as_of": _date_text(as_of), "accounts": accounts,
            "totals": [{"currency": c, "debit": _m(d, c), "credit": _m(cr, c), "balanced": d == cr}
                       for c, (d, cr) in sorted(totals.items())]}


# ------------------------------------------------------------ balance sheet
def balance_sheet(ledger, as_of=None, convert_to=None, today=None):
    _check_ledger(ledger)
    _check_as_of(as_of)
    if convert_to is not None and as_of is None:
        raise ReportError("converting needs a date: give as_of with convert_to")
    _check_convert_to(convert_to)
    sections = {"asset": {}, "liability": {}, "equity": {}}
    retained = {}
    for tx, p in ledger.postings():
        if as_of is not None and tx.date > as_of:
            continue
        t = _type_of(p.account)
        cur, v = p.amount.currency, p.amount.minor
        if t == "asset":
            _add(sections["asset"], (p.account, cur), v)
        elif t in ("liability", "equity"):
            _add(sections[t], (p.account, cur), -v)
        elif t in ("income", "expense"):
            _add(retained, cur, -v)

    def section(kind):
        lines = []
        total = {}
        for account, cur, v in _account_lines(sections[kind]):
            if convert_to is None:
                lines.append({"account": account, "balance": _m(v, cur)})
                _add(total, cur, v)
            else:
                conv = _convert(ledger, v, cur, convert_to, as_of)
                lines.append({"account": account, "balance": money_to_dict(conv), "original": _m(v, cur)})
                _add(total, convert_to, conv.minor)
        return lines, total

    a_lines, a_total = section("asset")
    l_lines, l_total = section("liability")
    e_lines, e_total = section("equity")
    if convert_to is None:
        re_list = _money_list(retained, keep_zero=False)
        for c, v in retained.items():
            if v != 0:
                _add(e_total, c, v)
    else:
        nonzero = [(c, v) for c, v in sorted(retained.items()) if v != 0]
        re_list = []
        if nonzero:
            s = 0
            for c, v in nonzero:
                s += _convert(ledger, v, c, convert_to, as_of).minor
            re_list = [_m(s, convert_to)]
            _add(e_total, convert_to, s)
        for t in (a_total, l_total, e_total):
            t.setdefault(convert_to, 0)
    curs = set(a_total) | set(l_total) | set(e_total)
    balanced = all(a_total.get(c, 0) == l_total.get(c, 0) + e_total.get(c, 0) for c in curs)
    return {"report": "balance_sheet", "as_of": _date_text(as_of), "currency": convert_to,
            "assets": {"accounts": a_lines, "total": _money_list(a_total, True)},
            "liabilities": {"accounts": l_lines, "total": _money_list(l_total, True)},
            "equity": {"accounts": e_lines, "retained_earnings": re_list, "total": _money_list(e_total, True)},
            "balanced": balanced}


# --------------------------------------------------------- income statement
def income_statement(ledger, period, convert_to=None):
    _check_ledger(ledger)
    _check_period(period)
    _check_convert_to(convert_to)
    sums = {"income": {}, "expense": {}}
    for tx, p in ledger.postings():
        if not (period.start <= tx.date <= period.end):
            continue
        t = _type_of(p.account)
        if t == "income":
            _add(sums["income"], (p.account, p.amount.currency), -p.amount.minor)
        elif t == "expense":
            _add(sums["expense"], (p.account, p.amount.currency), p.amount.minor)

    def section(kind):
        raw = _account_lines(sums[kind])
        total = {}
        items = []
        for account, cur, v in raw:
            if convert_to is None:
                items.append((account, cur, v, None))
                _add(total, cur, v)
            else:
                conv = _convert(ledger, v, cur, convert_to, period.end)
                items.append((account, convert_to, conv.minor, _m(v, cur)))
                _add(total, convert_to, conv.minor)
        if convert_to is not None:
            total.setdefault(convert_to, 0)
        lines = []
        for account, cur, v, original in items:
            line = {"account": account, "amount": _m(v, cur), "percent": _percent(v, total[cur])}
            if original is not None:
                line["original"] = original
            lines.append(line)
        return lines, total

    i_lines, i_total = section("income")
    e_lines, e_total = section("expense")
    net = {c: i_total.get(c, 0) - e_total.get(c, 0) for c in set(i_total) | set(e_total)}
    return {"report": "income_statement", "start": _date_text(period.start), "end": _date_text(period.end),
            "currency": convert_to,
            "income": {"accounts": i_lines, "total": _money_list(i_total, True)},
            "expenses": {"accounts": e_lines, "total": _money_list(e_total, True)},
            "net": _money_list(net, True)}


# ----------------------------------------------------------------- cashflow
def cashflow(ledger, period):
    _check_ledger(ledger)
    _check_period(period)
    opening, closing, flows = {}, {}, {}
    for tx in ledger.transactions():
        if tx.date > period.end:
            continue
        for p in tx.postings:
            if _type_of(p.account) == "asset":
                cur = p.amount.currency
                closing.setdefault(cur, 0)
                opening.setdefault(cur, 0)
                closing[cur] += p.amount.minor
                if tx.date < period.start:
                    opening[cur] += p.amount.minor
        if tx.date < period.start:
            continue
        asset_sum = {}
        for p in tx.postings:
            if _type_of(p.account) == "asset":
                _add(asset_sum, p.amount.currency, p.amount.minor)
        for p in tx.postings:
            if _type_of(p.account) != "asset" and asset_sum.get(p.amount.currency, 0) != 0:
                _add(flows, (p.account, p.amount.currency), -p.amount.minor)
    inflows, outflows = [], []
    total_in = {c: 0 for c in closing}
    total_out = {c: 0 for c in closing}
    for account, cur, v in _account_lines(flows):
        if v > 0:
            inflows.append({"account": account, "amount": _m(v, cur)})
            total_in[cur] = total_in.get(cur, 0) + v
        else:
            outflows.append({"account": account, "amount": _m(-v, cur)})
            total_out[cur] = total_out.get(cur, 0) - v
    net = {c: total_in.get(c, 0) - total_out.get(c, 0) for c in closing}
    return {"report": "cashflow", "start": _date_text(period.start), "end": _date_text(period.end),
            "opening": _money_list(opening, True), "inflows": inflows, "outflows": outflows,
            "total_in": _money_list(total_in, True), "total_out": _money_list(total_out, True),
            "net": _money_list(net, True), "closing": _money_list(closing, True)}


# ----------------------------------------------------------------- register
def register(ledger, account, period=None, rollup=False):
    _check_ledger(ledger)
    _check_period(period, optional=True)
    if not isinstance(rollup, bool):
        raise ReportError("rollup must be true or false, got %r" % (rollup,))
    if not isinstance(account, str) or not ledger.chart.exists(account):
        raise ReportError("no such account %s" % ("'%s'" % account if isinstance(account, str) else repr(account)))
    prefix = account + ":"
    opening, running, rows = {}, {}, []
    for tx in ledger.transactions():
        if period is not None and tx.date > period.end:
            continue
        for p in tx.postings:
            if not (p.account == account or (rollup and p.account.startswith(prefix))):
                continue
            cur, v = p.amount.currency, p.amount.minor
            opening.setdefault(cur, 0)
            running.setdefault(cur, 0)
            running[cur] += v
            if period is not None and tx.date < period.start:
                opening[cur] += v
                continue
            rows.append({"date": _date_text(tx.date), "id": tx.id, "payee": tx.payee, "narration": tx.narration,
                         "account": p.account, "amount": _m(v, cur), "balance": _m(running[cur], cur)})
    return {"report": "register", "account": account, "rollup": rollup,
            "start": _date_text(period.start) if period is not None else None,
            "end": _date_text(period.end) if period is not None else None,
            "opening": _money_list(opening, True), "rows": rows, "closing": _money_list(running, True)}


# ---------------------------------------------------------------- net worth
def net_worth(ledger, period, step="month"):
    _check_ledger(ledger)
    _check_period(period)
    if not isinstance(step, str) or step not in STEPS:
        raise ReportError("unknown step %r: expected week, month, quarter or year" % (step,))
    steps = periods(period.start, period.end, step)
    txs = ledger.transactions()
    points = []
    for st in steps:
        d = st.end
        assets, liabilities = {}, {}
        for tx in txs:
            if tx.date > d:
                break
            for p in tx.postings:
                t = _type_of(p.account)
                if t in ("asset", "liability"):
                    cur = p.amount.currency
                    assets.setdefault(cur, 0)
                    liabilities.setdefault(cur, 0)
                    if t == "asset":
                        assets[cur] += p.amount.minor
                    else:
                        liabilities[cur] -= p.amount.minor
        net = {c: assets[c] - liabilities[c] for c in assets}
        points.append({"date": _date_text(d), "assets": _money_list(assets, True),
                       "liabilities": _money_list(liabilities, True), "net": _money_list(net, True)})
    return {"report": "net_worth", "start": _date_text(period.start), "end": _date_text(period.end),
            "step": step, "points": points}


# --------------------------------------------------------------- rendering
def _kind(report):
    if not isinstance(report, dict) or report.get("report") not in REPORT_KINDS:
        raise ReportError("not a report: %r" % (report,))
    return report["report"]


def _mt(m):
    return "%s %s" % (m["amount"], m["currency"])


def _blocks(width, *blocks):
    rows = []
    for b in blocks:
        if not b:
            continue
        if rows:
            rows.append([""] * width)
        rows.extend(b)
    return rows


def _text_trial_balance(r):
    title = "Trial balance as of %s" % r["as_of"] if r["as_of"] else "Trial balance"
    rows = [[a["account"], a["type"], _mt(a["debit"]) if a["debit"] else "",
             _mt(a["credit"]) if a["credit"] else ""] for a in r["accounts"]]
    rows += [["Total", "", _mt(t["debit"]), _mt(t["credit"])] for t in r["totals"]]
    return title, ["Account", "Type", "Debit", "Credit"], rows, "llrr"


def _text_balance_sheet(r):
    title = "Balance sheet as of %s" % r["as_of"] if r["as_of"] else "Balance sheet"
    if r.get("currency"):
        title += " (in %s)" % r["currency"]

    def block(key, heading, total_label, extra=()):
        sec = r[key]
        b = [[heading, ""]]
        b += [["  " + a["account"], _mt(a["balance"])] for a in sec["accounts"]]
        b += list(extra)
        b += [[total_label, _mt(m)] for m in sec["total"]]
        return b

    rows = _blocks(2, block("assets", "Assets", "Total assets"),
                   block("liabilities", "Liabilities", "Total liabilities"),
                   block("equity", "Equity", "Total equity",
                         [["  Retained earnings", _mt(m)] for m in r["equity"]["retained_earnings"]]))
    return title, ["Account", "Balance"], rows, "lr"


def _text_income_statement(r):
    title = "Income statement %s to %s" % (r["start"], r["end"])
    if r.get("currency"):
        title += " (in %s)" % r["currency"]

    def block(key, heading, total_label):
        sec = r[key]
        b = [[heading, "", ""]]
        b += [["  " + a["account"], _mt(a["amount"]), a["percent"] + "%"] for a in sec["accounts"]]
        b += [[total_label, _mt(m), ""] for m in sec["total"]]
        return b

    rows = _blocks(3, block("income", "Income", "Total income"),
                   block("expenses", "Expenses", "Total expenses"),
                   [["Net income", _mt(m), ""] for m in r["net"]])
    return title, ["Account", "Amount", "Percent"], rows, "lrr"


def _text_cashflow(r):
    title = "Cash flow %s to %s" % (r["start"], r["end"])

    def block(lines, totals, heading, total_label):
        b = [[heading, ""]]
        b += [["  " + a["account"], _mt(a["amount"])] for a in lines]
        b += [[total_label, _mt(m)] for m in totals]
        return b

    rows = _blocks(2, [["Opening balance", _mt(m)] for m in r["opening"]],
                   block(r["inflows"], r["total_in"], "Money in", "Total money in"),
                   block(r["outflows"], r["total_out"], "Money out", "Total money out"),
                   [["Net change", _mt(m)] for m in r["net"]] + [["Closing balance", _mt(m)] for m in r["closing"]])
    return title, ["Account", "Amount"], rows, "lr"


def _text_net_worth(r):
    title = "Net worth %s to %s (by %s)" % (r["start"], r["end"], r["step"])
    rows = []
    for p in r["points"]:
        if not p["assets"]:
            rows.append([p["date"], "", "", ""])
        for a, l, n in zip(p["assets"], p["liabilities"], p["net"]):
            rows.append([p["date"], _mt(a), _mt(l), _mt(n)])
    return title, ["Date", "Assets", "Liabilities", "Net"], rows, "lrrr"


def _text_register(r):
    title = "Register %s" % r["account"]
    if r["rollup"]:
        title += " (with sub-accounts)"
    if r["start"] is not None:
        title += " %s to %s" % (r["start"], r["end"])
    rows = [["", "", "Opening balance", "", "", _mt(m)] for m in r["opening"]]
    for row in r["rows"]:
        rows.append([row["date"], "" if row["id"] is None else str(row["id"]), row["payee"], row["account"],
                     _mt(row["amount"]), _mt(row["balance"])])
    rows += [["", "", "Closing balance", "", "", _mt(m)] for m in r["closing"]]
    return title, ["Date", "Id", "Payee", "Account", "Amount", "Balance"], rows, "llllrr"


_TEXT = {"trial_balance": _text_trial_balance, "balance_sheet": _text_balance_sheet,
         "income_statement": _text_income_statement, "cashflow": _text_cashflow,
         "net_worth": _text_net_worth, "register": _text_register}


def render_text(report):
    kind = _kind(report)
    try:
        title, headers, rows, align = _TEXT[kind](report)
    except (KeyError, TypeError, IndexError, AttributeError):
        raise ReportError("malformed %s report" % kind) from None
    return title + "\n\n" + render_table(headers, rows, align)


# --------------------------------------------------------------------- CSV
def _csv_trial_balance(r):
    rows = []
    for a in r["accounts"]:
        m = a["debit"] or a["credit"]
        rows.append([a["account"], a["type"], m["currency"], a["debit"]["amount"] if a["debit"] else "",
                     a["credit"]["amount"] if a["credit"] else ""])
    return ["account", "type", "currency", "debit", "credit"], rows


def _csv_balance_sheet(r):
