def _percent(actual, allowance):
    if allowance == 0:
        tenths = 0 if actual == 0 else 1000
    else:
        tenths = round_div(actual * 1000, allowance)
    sign = "-" if tenths < 0 else ""
    q, r = divmod(abs(tenths), 10)
    return decimal.Decimal("%s%d.%d" % (sign, q, r))


class BudgetLine:
    __slots__ = ("_pattern", "_period_kind", "_budget", "_actual", "_remaining", "_percent", "_over", "_accounts")
    _FIELDS = ("pattern", "period_kind", "budget", "actual", "remaining", "percent", "over", "accounts")

    def __init__(self, pattern, period_kind, budget, actual, remaining, percent, over, accounts):
        for name, value in zip(self._FIELDS, (pattern, period_kind, budget, actual, remaining, percent, over,
                                              tuple(tuple(a) for a in accounts))):
            object.__setattr__(self, "_" + name, value)

    pattern = property(lambda self: self._pattern)
    period_kind = property(lambda self: self._period_kind)
    budget = property(lambda self: self._budget)
    actual = property(lambda self: self._actual)
    remaining = property(lambda self: self._remaining)
    percent = property(lambda self: self._percent)
    over = property(lambda self: self._over)
    accounts = property(lambda self: self._accounts)

    def __setattr__(self, name, value):
        raise AttributeError("BudgetLine is immutable")

    def __delattr__(self, name):
        raise AttributeError("BudgetLine is immutable")

    def _key(self):
        return tuple(getattr(self, "_" + f) for f in self._FIELDS)

    def __reduce__(self):
        return (BudgetLine, self._key())

    def __eq__(self, other):
        if not isinstance(other, BudgetLine):
            return NotImplemented
        return self._key() == other._key()

    def __ne__(self, other):
        r = self.__eq__(other)
        return r if r is NotImplemented else not r

    def __hash__(self):
        return hash(self._key())

    def __repr__(self):
        return "BudgetLine(%s)" % ", ".join("%s=%r" % (f, getattr(self, f)) for f in self._FIELDS)

    def to_dict(self):
        def money(m):
            return {"amount": m.amount_str(), "currency": m.currency}
        return {
            "pattern": self._pattern,
            "period_kind": self._period_kind,
            "budget": money(self._budget),
            "actual": money(self._actual),
            "remaining": money(self._remaining),
            "percent": str(self._percent),
            "over": bool(self._over),
            "accounts": [{"account": a, "amount": money(m)} for a, m in self._accounts],
        }


